pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable, penalize hard.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (1.0 - (post_residual as f64) / 12.0);
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Reward tight fits relative to residual.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // Open-bin pressure: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when open bins are mostly full/tight.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score = 35.0 - pressure * 40.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer small post residual, with smooth non-linear shaping
    let mut score = post;

    // Non-linear polynomial coupling of post residual with stream progress:
    // early on, tolerate residual slack (keep bins flexible); later, crush dead space harder.
    let coupling = norm_post * norm_post * (1.0 + 3.0 * progress);
    score += coupling * cap * 0.5;

    // Reward tight fits smoothly (quadratic in fill ratio)
    let fill = norm_item;
    score -= 10.0 * fill * fill;

    // Lookahead: bonus if the post residual can smoothly accommodate the next item
    if next_item_size > 0 {
        let gap = norm_post - norm_next;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - gap) * (1.0 - gap) * norm_next;
        } else {
            score += 6.0 * gap * gap * cap;
        }
    }

    // Last-chance bin: smooth urgency term
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 + progress);
    }

    // Penalize divergence from mean residual (smooth dispersion penalty)
    let dev = (post - mean_residual) / cap;
    score += 4.0 * dev * dev * cap;

    // Mild penalty for bin proliferation
    score += 0.3 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer-division thresholds (capacity fractions)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let cls = post_residual / 20; // 5 harmonic classes: 0..19,20..39,40..59,60..79,80..99

    // Reward large post_residual classes (usable space), non-linearly
    score -= (cls as f64) * (cls as f64) * 0.9;

    // Perfect/near-perfect fits get strong bonus
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Penalize awkward dead space: post_residual in (10, 20) is hard to fill
    if post_residual > 10 && post_residual < 20 {
        score += 40.0;
    }
    if post_residual > 30 && post_residual < 40 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item fits: residual class compatibility via modulo
            let m = post_residual % next_item_size.max(1);
            if m == 0 {
                score -= 120.0;
            } else {
                score -= (post_residual.min(next_item_size * 2) as f64) * 0.5;
            }
        } else {
            // next item won't fit here: penalize small residuals that strand the next item
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // New-bin candidate handling: only attractive late or when open bins are poor fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let waste = (mean_residual - item_size as f64).max(0.0);
        score = cap - pr + 60.0 + waste * 0.3 - progress * 40.0;
        if fitting_bins_count == 1 {
            score += 200.0; // opening a new bin when a usable bin exists is bad
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.15;

    // Prefer tighter bins (small residual before placement)
    score += (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual ---
    // Class residual into capacity fractions; small leftovers in low classes are "dead space".
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    if post_residual == 0 {
        // Perfect closure: extremely desirable.
        score -= 400.0;
    } else if post_residual < eighth {
        // Tiny sliver (1..12): nearly dead space.
        score += 120.0;
    } else if post_residual < quarter {
        // Class (12,25]: usable only for small items.
        score += 30.0;
    } else if post_residual < 2.0 * quarter {
        // Class (25,50]: still flexible.
        score -= 10.0;
    } else {
        // Class (50,100]: roomy bin, good for future large items.
        score -= 25.0;
    }

    // Integer-division threshold coupling: does post_residual still admit the lookahead item?
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size <= post_residual {
            // Lookahead fits here: reward proportional to how "tight" the pair is.
            let pair_tightness = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 60.0 + 80.0 * pair_tightness;
            // Harmonic bonus: post_residual / next_item_size integer multiple (clean division)
            if post_residual % next_item_size.max(1) == 0 && post_residual != next_item_size {
                score -= 20.0;
            }
        } else {
            // Lookahead cannot use this bin's leftover: penalize more if leftover is awkwardly small.
            if pr < quarter {
                score += 40.0;
            } else {
                score += 10.0;
            }
        }
    } else {
        // Last item: only closure matters.
        score -= 200.0 * (1.0 - pr / cap);
    }

    // Tight fit reward: residual barely above item size.
    let gap = (bin_residual - item_size) as f64;
    if gap < eighth {
        score -= 70.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: it should only win when open bins are truly poor.
    if bin_residual == bin_capacity {
        // Neutral base for fresh bin; gets modest preference only late in stream
        // or when many bins are open with poor mean residual.
        score = 0.5 * pr; // = 50 for empty bin
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < quarter {
            score -= 90.0; // existing bins are fragmented; open fresh one
        } else if fitting_bins_count > 0 {
            score += 60.0; // decent fits exist; discourage opening new bin
        }
        if progress > 0.8 {
            score -= 15.0; // late stream: consolidation slightly favored
        }
    }

    // Mild penalty for proliferating bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: multiples of 10 are "usable" residues
    let residue_class = post_residual % 10;
    if residue_class == 0 {
        score -= 6.0; // perfectly aligned leftover, reusable by class-aligned items
    } else if residue_class <= 3 {
        score += 4.0 + residue_class as f64; // small dead-space slivers
    } else {
        score += 1.5;
    }

    // Integer-division thresholds on post_residual: big chunks are valuable
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual >= half {
        score -= 8.0;
    } else if post_residual >= quarter {
        score -= 2.0;
    } else if post_residual > 0 {
        score += 5.0; // near-empty leftover = wasted bin space
    }

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 7.0;
        // extra reward if next item exactly consumes the remainder (harmonic pairing)
        if post_residual - next_item_size < 5 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; leftover becomes dead space
        score += 3.0;
    }

    // Fraction-of-capacity coupling: penalize leaving > 40% free in an old bin
    let free_frac = post_residual as f64 / cap;
    if free_frac > 0.4 && bin_residual != bin_capacity {
        score += free_frac * 10.0;
    }

    // New-bin candidate handling: neutral-ish baseline, cheaper early in stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.55 + progress * 10.0 - (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a bin
        }
    }

    // Mild preference for fuller bins when many are open
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match bonus: next item fits with small leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: next item cannot fit into leftover.
        score += 12.0 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward bins tighter than the mean residual (good packing density).
    score -= 0.35 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize very small unusable residuals (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild preference for reusing existing bins as stream progresses.
    if bin_residual != bin_capacity {
        score -= 3.0 + 5.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    // Items are >= 1, but treat residuals below a small threshold as dead space.
    let dead_threshold: f64 = 4.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    }

    // Penalize "awkward" residuals: small but not zero gaps that are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 2 {
        score -= 40.0;
    }

    // Reward leaving room for the next item (lookahead coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin: strong preference to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor tight packing.
    let open_pressure = open_bins_count as f64;
    score += 0.8 * open_pressure;

    // Penalize bins whose residual deviates far above the mean (fragmentation signal).
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.3 * dev;
    } else {
        score += 0.15 * dev;
    }

    // New-bin candidate: only attractive when current bins are heavily fragmented
    // or item is large relative to all residuals.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let base = 35.0 + 30.0 * fragmentation + 0.5 * open_pressure;
        // If item fits well nowhere else, new bin becomes competitive.
        if fitting_bins_count == 0 {
            score = base - 20.0;
        } else {
            score = base;
        }
    }

    // Mild stream-progression term: slightly prefer reusing bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact matches between
    // post_residual and the next item's size (perfect follow-up placement).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            score -= 60.0; // perfect two-item packing (item + next fills bin)
        } else if post >= nxt {
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize proportional to wasted gap
            score += 5.0 + diff * 0.15;
        }
        // If post_residual fits next item but leaves tiny unusable sliver, penalize
        if post >= nxt && (post - nxt) < 5.0 {
            score -= 10.0; // near-perfect double fill
        }
        if post > 0.0 && post < nxt && post < 10.0 {
            score += 20.0; // dead sliver unusable by next item
        }
    } else {
        // Last item: strongly prefer tightest fit
        score -= 40.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Penalize large remaining residual (wasted space) nonlinearly
    let post_f = post_residual as f64;
    score += 0.01 * post_f * post_f / bin_capacity as f64;

    // Last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin
        score += 45.0;
        // Attractive if item is large and current bins are fragmented
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if large_item || mean_residual < item_size as f64 {
            score -= 55.0;
        }
        // Slightly less penalized early in stream
        score -= 10.0 * (1.0 - progress);
        // Prefer new bin if next item pairs well with residual after placing item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Mild penalty for proliferating open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1, but
    // realistically small gaps) can use are pure waste. Penalize gaps in the
    // "dead zone" super-linearly.
    if post_residual > 0 {
        // Dead-zone threshold: gaps too small for typical items to matter.
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64);
        } else if post_residual <= 25 {
            // Moderately wasteful zone.
            score += 8.0 * (26.0 - post_residual as f64);
        }
    } else {
        // Perfect fit: strongly reward.
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (good chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Bin cannot host the next item; mild penalty, worse if gap is tiny.
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; encourage using existing bins when many are open.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.3 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the
    // stream and when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * progress + 1.5 * open_bins_count as f64;
    }

    // Mild alignment with mean residual: prefer bins with below-average
    // residual (tighter bins) to consolidate.
    score += 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 and mod 25
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;

    // Penalize post-residuals that are small but not zero (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }
    // Harmonic residue penalty: residues 1..9 are least reusable
    score += (r10 as f64) * 0.8;

    // Quarters of capacity: post_residual near C/4, C/2, 3C/4 are reusable
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let d_q = (post_residual as i64 - quarter as i64).abs();
    let d_h = (post_residual as i64 - half as i64).abs();
    if d_q <= 5 || d_h <= 5 {
        score -= 15.0;
    }

    // Reward if next item fits exactly into post_residual (perfect chaining)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
            // harmonic class match: next_item and post_residual same mod 10
            if next_item_size % 10 == r10 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this bin's remainder
            score += (r25 as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish, but prefer it when mean residual is tight
    if bin_residual == bin_capacity {
        // opening fresh is fine if existing bins are fragmented
        score = 20.0 + mean_residual * 0.1 - (open_bins_count as f64);
        if fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 25.0; // existing bins too fragmented, discourage new bin
        }
    }

    // Late in the stream, consolidate: penalize spreading across many bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (open_bins_count as f64) * 0.5;

    // Integer-division threshold: post_residual in [0, C/5) is dead space
    if post_residual < bin_capacity / 5 && post_residual > 0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum item size) are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0;
    }

    // Penalize small-but-nonzero dead space more aggressively than large gaps:
    // a gap of 1..=10 is nearly unusable, larger gaps may still fit items.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    if post_residual > 0 {
        score -= (bin_capacity as f64 / post_residual as f64).min(50.0);
    } else {
        // Perfect fit: strong reward.
        score -= 120.0;
    }

    // Open-bins pressure: discourage spreading across many bins when few
    // fitting bins exist; encourage using scarce fitting bins.
    if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it over opening a new bin.
        score -= 60.0;
    } else {
        score += open_bins_count as f64 * 0.8;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item fits
    // poorly everywhere else (large item relative to typical residuals).
    if bin_residual == bin_capacity {
        let openness = step_index as f64 / (total_items.max(1) as f64);
        // Early in stream, opening bins is cheap; late, consolidation matters.
        let new_bin_bias = 25.0 + 60.0 * openness;
        // If the item is big, a fresh bin is often good (full-ish packing).
        if item_size >= 70 {
            score = new_bin_bias - 20.0;
        } else {
            score = new_bin_bias;
        }
        // Lookahead: if next item is large, a fresh bin is attractive.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    } else {
        // Lookahead synergy: if the post residual exactly fits the next item,
        // this placement is excellent.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 10 {
            score -= 20.0;
        }
    }

    // Mild preference for bins with residuals below mean (consolidate emptier
    // space into fewer bins).
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight post_residual relative to mean residual.
    score = post_residual as f64 * 1.0 + (post_residual as f64 - mean_residual) * 0.5;

    if next_item_size > 0 {
        // Perfect 2-step lookahead: post_residual exactly matches next item.
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // chain two items perfectly
        } else if diff <= 5.0 {
            score -= 25.0;
        } else if diff <= 15.0 {
            score -= 8.0;
        } else {
            // post_residual too far from next item: dead space risk
            score += diff * 0.3;
        }
        // If next item can't fit in post_residual, penalize proportionally
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    } else {
        // Last item: just minimize waste
        score = post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize creating tiny unusable residuals (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // New-bin candidate (empty bin): only attractive when current bin fit is bad.
    if bin_residual == bin_capacity {
        // Prefer new bin when mean residual is low (open bins are nearly full)
        // or the item is large.
        score = 40.0 + mean_residual * 0.5 - item_size as f64 * 0.3
            - if next_item_size > 0 { (bin_capacity as f64 - next_item_size as f64) * 0.1 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: wasted space, with smooth non-linear (quadratic/cubic) shaping.
    let x = pr / cap;
    let mut score = pr as f64 * (1.0 + 0.6 * x * x + 0.4 * x * x * x);

    // Coupling: large residuals matter more late in the stream (smooth ramp).
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += late * 12.0 * x * x;

    // Lookahead: reward leaving room for the next item (smooth coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if pr >= nxt { 1.0 } else { 0.0 };
        let gap = (pr - nxt).abs() / cap;
        score -= 8.0 * fit_next * (1.0 - gap * gap);
        // Penalize blocking the next item, stronger mid-stream.
        score += (1.0 - fit_next) * (5.0 + 10.0 * late);
    }

    // Last-chance bonus: only bin that fits -> strong reward to avoid new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mean residual coupling: prefer bins near/below the mean residual (tight fits).
    score += 0.3 * (pr as f64 - mean_residual).abs();

    // New-bin candidate handling: empty bin gets a smooth opening penalty,
    // relaxed when open bins are fragmented or progress is late.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let open_factor = (open_bins_count as f64).ln().max(0.0);
        score = 25.0 + 20.0 * (1.0 - late) + 30.0 * fragmentation - 6.0 * open_factor;
        // Small item on fresh bin is wasteful; smooth penalty.
        score += 15.0 * (1.0 - (item_size as f64 / cap));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual (capacity fractions) ---
    // Residuals are bucketed into harmonic classes relative to capacity:
    // tiny (0..=5), small (6..=15), medium (16..=34), large (35..=100)
    let tiny = if post_residual <= 5 { 1.0 } else { 0.0 };
    let small = if post_residual > 5 && post_residual <= 15 { 1.0 } else { 0.0 };
    let large = if post_residual >= 35 { 1.0 } else { 0.0 };

    // Tiny residuals are near-perfect fills: strongly reward.
    score -= 30.0 * tiny;

    // Small residuals are dead space (items >=10 can never use them): penalize.
    score += 25.0 * small;

    // Large residuals leave usable space: mild reward so we don't over-punish.
    score -= 6.0 * large;

    // --- Modulo arithmetic on post_residual: residuals divisible by common
    // item-size classes (10, 20, 25, 50) are re-usable by future items. ---
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 3.0; }
    }

    // --- Lookahead: does the next item fit exactly into post_residual? ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 12.0; // next item can still use this bin
        } else {
            score += 5.0;  // next item won't fit here
        }
    }

    // --- Integer division threshold: how many "average" items still fit? ---
    let avg_item = 30u32;
    let fits_avg = post_residual / avg_item;
    score -= fits_avg as f64 * 4.0;

    // --- Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible). ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling: brand-new empty bin. ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are crowded
        // and the item is large relative to capacity.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        score += 15.0; // base cost of opening a new bin
        score -= 20.0 * crowding * (item_size as f64 / bin_capacity as f64);
        score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // --- Many open bins with slack: discourage spreading items thin. ---
    if open_bins_count > 3 && (post_residual as f64) > mean_residual {
        score += 3.0;
    }

    score
}

