    let norm_pr = pr / cap;

    // Base: post-residual, modulated by non-linear polynomial coupling with progress
    let mut score = pr * (1.0 + 0.8 * progress * (1.0 - progress) * 4.0);

    // Polynomial decay of residual value: small residuals are less useful later
    let q = norm_pr * norm_pr;
    score += 40.0 * q * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (cap - pr) as f64 * 0.1 * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: penalize if next item fits well in post_residual (waste of perfect slot)
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score += 15.0 * (1.0 - gap / cap) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        // Reward when next item won't fit here (no conflict)
        score -= 8.0;
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably from mean
    score += 0.3 * (pr as f64 - mean_residual) * (1.0 + progress);

    // New-bin candidate handling: penalize opening new bins early, allow late
    if bin_residual == bin_capacity {
        score = cap * (1.2 - 0.6 * progress) + 20.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual ---
    // Class residual into capacity fractions; small leftovers in low classes are "dead space".
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    if post_residual == 0 {
        // Perfect closure: extremely desirable.
        score -= 400.0;
    } else if post_residual < eighth {
        // Tiny sliver (1..12): nearly dead space.
        score += 120.0;
    } else if post_residual < quarter {
        // Class (12,25]: usable only for small items.
        score += 30.0;
    } else if post_residual < 2.0 * quarter {
        // Class (25,50]: still flexible.
        score -= 10.0;
    } else {
        // Class (50,100]: roomy bin, good for future large items.
        score -= 25.0;
    }

    // Integer-division threshold coupling: does post_residual still admit the lookahead item?
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size <= post_residual {
            // Lookahead fits here: reward proportional to how "tight" the pair is.
            let pair_tightness = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 60.0 + 80.0 * pair_tightness;
            // Harmonic bonus: post_residual / next_item_size integer multiple (clean division)
            if post_residual % next_item_size.max(1) == 0 && post_residual != next_item_size {
                score -= 20.0;
            }
        } else {
            // Lookahead cannot use this bin's leftover: penalize more if leftover is awkwardly small.
            if pr < quarter {
                score += 40.0;
            } else {
                score += 10.0;
            }
        }
    } else {
        // Last item: only closure matters.
        score -= 200.0 * (1.0 - pr / cap);
    }

    // Tight fit reward: residual barely above item size.
    let gap = (bin_residual - item_size) as f64;
    if gap < eighth {
        score -= 70.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: it should only win when open bins are truly poor.
    if bin_residual == bin_capacity {
        // Neutral base for fresh bin; gets modest preference only late in stream
        // or when many bins are open with poor mean residual.
        score = 0.5 * pr; // = 50 for empty bin
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < quarter {
            score -= 90.0; // existing bins are fragmented; open fresh one
        } else if fitting_bins_count > 0 {
            score += 60.0; // decent fits exist; discourage opening new bin
        }
        if progress > 0.8 {
            score -= 15.0; // late stream: consolidation slightly favored
        }
    }

    // Mild penalty for proliferating bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (<= 4) are nearly worthless; penalize them hard.
    if post_residual > 0 && post_residual <= 4 {
        score += 60.0;
    } else if post_residual > 4 && post_residual <= 9 {
        score += 25.0;
    }

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving gaps that can host the lookahead item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 4 {
        // Gap would become dead space after the next item lands here.
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin; reward it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: make the fresh bin attractive only when no existing
    // bin offers a good fit (i.e., when existing scores are inflated by
    // dead-space penalties). Penalize it otherwise.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.3;
        // Late in the stream, opening new bins is fine since consolidation
        // opportunities shrink.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 25.0;
    }

    // Slight preference for bins whose residual is close to the mean
    // (keeps the bin profile balanced).
    score += (bin_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit reward (strongly prefer filling a bin completely)
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space quadratically, normalized by capacity
        let dead_frac = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * dead_frac * dead_frac * (bin_capacity as f64);
    }

    // 2-step lookahead: reward if next item fits into post_residual (chained packing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chain continues; reward proportional to how snugly next item fits
            let leftover2 = post_residual as f64 - next_item_size as f64;
            score -= 60.0 - 0.5 * leftover2;
        } else {
            // Next item won't fit: penalize if post_residual is small but nonzero
            // (wasted sliver) unless it's near capacity-filling
            if post_residual < 10 {
                score += 30.0;
            }
        }
    } else {
        // Last item: pure fill, reward tight fits harder
        score -= 50.0;
    }

    // Reward matching post_residual against mean residual (bins below mean residual
    // are "behind" in filling; prefer placing items there to balance residuals)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening new bins late in the stream unless the fit is perfect
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, discounted if many bins open / early stream
        score += 55.0 + 45.0 * progress;
        // Allow opening a new bin when no good fit exists: if post_residual of this
        // fresh bin leaves room for the next item, it's attractive
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 70.0;
        }
        if post_residual == 0 {
            score -= 500.0;
        }
    }

    // Mild preference for bins with less residual before placement (denser bins)
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary driver: penalize waste quadratically so tight fits dominate.
    let waste = post_residual as f64;
    score += 0.035 * waste * waste / bin_capacity as f64;

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 12.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
    }
    // If next item cannot fit here, mild penalty proportional to how far off it is.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit this item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins whose residual is close to the mean (keep residual spread small).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.10 * dev;

    // Time horizon: early in the stream, be conservative about opening new bins;
    // late in the stream, closing out bins tightly matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early (avoid bin proliferation), reward late
        // only when residuals are large and unusable.
        let avg_unusable = mean_residual / bin_capacity as f64;
        let new_bin_score = 15.0 - 10.0 * progress + 20.0 * avg_unusable * (1.0 - progress);
        score = score.max(new_bin_score + score * 0.5);
        // Base handicap so new bins only win when open bins are genuinely bad.
        score += 6.0 - 4.0 * progress;
    }

    // Reward filling large items into already-open bins (consolidation).
    score -= 0.05 * item_size as f64 * (1.0 - progress);

    // Slight preference for bins with fewer alternatives when residuals are small.
    if post_residual < 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer tight fits (small post_residual), with polynomial shaping.
    let mut score = post_norm * post_norm * (3.0 - 2.0 * post_norm);

    // Smooth coupling of post_residual with stream progress:
    // late in the stream, small residuals matter even more (avoid waste near the end).
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * post_norm * post_norm * cap * 0.01;

    // Penalty for large dead space, smoothly amplified by number of open bins.
    let open_scale = (open_bins_count as f64).ln_1p() * 0.3 + 1.0;
    score += 0.4 * post_norm * post_norm * open_scale;

    // Deviation from mean residual: prefer bins whose residual is close to mean
    // (keeps balance), smooth quadratic coupling.
    let mean_norm = mean_residual / cap;
    let dev = post_norm - mean_norm;
    score += 0.15 * dev * dev;

    // Lookahead: if next item fits into post_residual, reward this bin smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post - nxt) / cap;
            score -= 0.6 * (1.0 - slack) * (1.0 - slack);
        } else {
            // Next item won't fit: penalize proportionally to how much it misses.
            let miss = (nxt - post) / cap;
            score += 0.25 * miss * miss;
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 0.8 + 0.4 * progress;
    }

    // New-bin candidate: make it moderately attractive early, less so later,
    // so tight fits in existing bins are preferred as the stream matures.
    if bin_residual == bin_capacity {
        score += 0.5 - 0.6 * progress * progress;
        // If existing bins are all poor fits, opening a new bin is fine.
        score -= 0.2 * (post_norm * 0.0);
    }

    // Reward filling bins completely (post_residual near 0) with smooth term.
    score -= 0.3 * (1.0 - post_norm) * (1.0 - post_norm) * (1.0 - post_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // "reusable" residue classes modulo common item sizes (capacity fractions).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact-fill reward: zero residual is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: leftover too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic classes: leftover divisible by 25 / 20 / 10 is highly reusable
    // (matches capacity-fraction item sizes), reward those residue classes.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 25.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 15.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Perfect next-item fit: lookahead exactly matches the leftover.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    }
    // Lookahead fits comfortably: reward proportional to the slack match.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / cap);
    }
    // Lookahead cannot use the leftover: penalize proportionally.
    if next_item_size > post_residual {
        score += 10.0;
    }

    // Integer-division thresholds on residual size classes.
    let resid_class = post_residual / 10; // 0..10 coarse class
    match resid_class {
        0 => score += 20.0,          // tiny unusable sliver
        1 => score += 5.0,           // marginal
        2..=4 => score -= 5.0,       // sweet spot for medium items
        5..=7 => score -= 10.0,      // roomy, still useful
        _ => {}                      // near-empty bin, neutral
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = cap - 70.0 * pressure - 10.0 * (open_bins_count as f64).ln();
        if next_item_size > 0 && next_item_size > bin_residual {
            score += 100.0; // can't happen for empty bin, but guard
        }
    }

    // Late-stream tightening: be more conservative with leftovers early,
    // more aggressive about closing bins near the end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    // Tie-break toward fewer open bins (prefer filling existing bins).
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers (< 10, min item size) are pure waste.
    if post_residual < 10 {
        score += 25.0; // unusable gap penalty
    } else if post_residual < 20 {
        score += 8.0; // hard-to-fill gap
    }

    // Reward tight fits proportionally to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: penalize spreading across many bins slightly,
    // but a last-chance bin (fitting_bins_count == 1) should be strongly favored
    // over opening a new bin when the fit is decent.
    if fitting_bins_count == 1 && post_residual < item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large post_residual relative to capacity means good future flexibility),
    // or when open bins are heavily fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).max(0.0);
        score -= 12.0 * fragmentation / bin_capacity as f64;
        // Mild penalty so tight fits in existing bins still win.
        score += 10.0;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Lookahead: if next item can use this bin's leftover, reward placement here.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover too small for the next item: penalize if it's dead space
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Slight preference for fuller bins among equals (reduce open bin count over time).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact fill of the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        let next_fits = next_item_size <= post_residual;
        if next_fits {
            let gap = (post_residual - next_item_size) as f64;
            if gap == 0.0 {
                score -= 800.0; // two-step perfect chain
            } else {
                score -= 150.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item would need a different bin: penalize leaving awkward residue.
            let overhang = (next_item_size - post_residual) as f64;
            score += 0.3 * overhang;
        }
    }

    // Penalize large dead space relative to mean residual across open bins.
    if post_residual as f64 > mean_residual + 20.0 {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && post_residual as f64 <= mean_residual + 30.0 {
        score -= 120.0;
    }

    // Mild penalty for opening new bins when many bins are already open and tight.
    if bin_residual == bin_capacity {
        score += 50.0 + 2.0 * open_bins_count as f64;
    }

    // Small tie-breaker: prefer filling bins with less remaining space overall.
    score += 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            // Extra reward if next item fills it almost perfectly too.
            let next_fit = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 * (1.0 - next_fit);
        } else if bin_residual >= next_item_size {
            // Bin could host next item if we DON'T place here -> mild penalty.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Penalize creating dead space smaller than the smallest plausible item (<= 10),
    // but only when it cannot host the lookahead item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Global state: when many bins are open relative to progress, prefer consolidation
    // (penalize the new-bin candidate less implicitly by penalizing spread).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let spread = open_bins_count as f64 / (bin_capacity as f64) - mean_residual / bin_capacity as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, increasingly costly as stream progresses,
        // unless it would be much better than fragmenting an existing bin.
        score = post_residual as f64 + 8.0 + 20.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    } else {
        // Existing bins: reward placing into bins with below-average residual
        // (i.e., already fragmented bins) to consolidate waste.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        score -= 4.0 * spread.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress) - 30.0 * x * (1.0 - x) * (1.0 - progress);

    // Reward tight fits more strongly as the stream progresses (waste becomes costly).
    score -= (1.0 - x) * (1.0 - x) * (20.0 + 40.0 * progress);

    // Penalize large dead space quadratically late in the stream.
    score += 15.0 * x * x * progress;

    // Last-chance bin bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: reward bins whose post residual can host the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0 + 10.0 * progress;
    } else if next_item_size > 0 {
        score += 5.0 * progress;
    }

    // Slight preference for consolidating into fewer bins.
    score += 0.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mild mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.1 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" is the leftover space?
    // Residuals divisible by small class sizes (e.g. 10, 20, 25, 50) pair well with
    // typical item sizes; odd/prime-like residuals create dead space.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward residuals that land on friendly class boundaries.
    let friendly = |r: u32| -> f64 {
        let rf = r as f64;
        let mut bonus = 0.0;
        if r % 50 == 0 { bonus += 6.0; }
        else if r % 25 == 0 { bonus += 4.0; }
        else if r % 10 == 0 { bonus += 3.0; }
        else if r % 5 == 0 { bonus += 1.5; }
        // Penalize prime-like residuals in the awkward small zone.
        if rf > 0.0 && rf < 10.0 { bonus -= 8.0; }
        bonus
    };
    score -= friendly(post_residual);

    // Fractional fill: prefer bins that become more "complete".
    let fill_frac = (bin_residual - post_residual) as f64 / cap;
    score -= 12.0 * fill_frac * fill_frac;

    // Lookahead coupling: if next item fits the post residual exactly or on a
    // friendly class boundary, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect pairing
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            score -= friendly(nxt_post);
            score += (nxt_post as f64) * 0.15;
        } else {
            // next item cannot use this bin's leftover; slight penalty scaled by gap
            score += ((next_item_size - post_residual) as f64) * 0.08;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on a bad fit.
    if fitting_bins_count == 1 {
        score -= 5.0;
        if post_residual < 10 { score -= 6.0; } // near-perfect fit on last chance
    }

    // New-bin candidate handling: an empty bin has large post_residual; keep it
    // attractive only when open bins are fragmented or the fit is poor.
    if bin_residual == bin_capacity {
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
        if item_size as f64 > 0.7 * cap { score -= 8.0; } // big items prefer fresh bins
    }

    // Late in the stream, tighten packing (prefer tightest fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.05 * (post_residual as f64 - mean_residual).abs();

    // Mild tie-break toward consolidating many open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (1..10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual as i32) as f64 * 3.0;
    }
    // Perfect fit: extremely desirable.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to the bin's remaining space.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // over spreading; penalize candidates that would leave large gaps when
    // the bin count is already high.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += (post_residual as f64 / bin_capacity as f64) * pressure * 2.0;

    // Last-chance bin: strongly favor using the only bin that can fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // this placement chains nicely; otherwise the leftover may be dead.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // New-bin candidate: only attractive when existing residuals are large
    // (item would fit poorly everywhere) or no bins fit at all.
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = mean_residual < item_size as f64 + 5.0;
        if poor_fit_everywhere || fitting_bins_count == 0 {
            score -= 35.0;
        } else {
            // Prefer any reasonable existing bin over opening a new one.
            score += 30.0 + open_bins_count as f64 * 2.0;
        }
    }

    // Mild alignment with mean residual: prefer bins whose leftover after
    // placement lands near the stream-average residual (typical gap size).
    score -= 3.0 * (-((post_residual as f64 - mean_residual) / 20.0).powi(2));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post_residual (tight fit), but scaled
    score = post_residual as f64 * 1.0;

    // Exact or near-exact fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        // Perfect chain: post_residual exactly fits next item
        if post_residual == next_item_size {
            score -= 45.0;
        } else if diff <= 5.0 {
            score -= 15.0;
        }
        // Penalize leaving dead space that nothing (current dist) can use
        if post_residual > 0 && post_residual < 10 {
            score += 25.0; // tiny unusable sliver
        }
    } else {
        // last item: just minimize waste
        score = post_residual as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but more attractive late in the stream when consolidation is done
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 - 20.0 * progress;
        // Opening a new bin is good if next item is huge and this item is small
        if next_item_size >= 60 && item_size <= 30 {
            score -= 10.0;
        }
    }

    // Prefer filling fewer bins overall when many open
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead: if next item fits in post_residual, reward this placement strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.06 * next_item_size as f64;
        // extra reward if next item is a very tight fit in post_residual
        let next_slack = post_residual - next_item_size;
        score -= 6.0 * (1.0 - next_slack as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty proportional to leftover dead space
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize bins far below mean residual (fragmented bins), reward above-mean usage
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    // Prefer filling bins with small residuals when many bins are open
    if open_bins_count > 3 {
        score -= 0.05 * (bin_capacity - bin_residual) as f64 / open_bins_count as f64;
    }

    // Time horizon: late in stream, be greedier (minimize post_residual harder)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.10 * post_residual as f64;

    // New-bin candidate: only attractive when no tight option exists
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 25.0 + 0.2 * mean_residual;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress.
    let pr_norm = pr / cap;
    let w = 0.5 + 0.5 * progress;
    score += w * 40.0 * pr_norm * pr_norm;

    // Penalize dead space more when many bins are open.
    let open_factor = (open_bins_count as f64).ln() + 1.0;
    score += 5.0 * open_factor * pr_norm * pr_norm * (1.0 + progress);

    // Reward tight fits (small post residual) with polynomial decay.
    score -= 30.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - progress);

    // Lookahead: favor leaving space for the next item smoothly.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = pr - ns;
        score += 8.0 * (diff / cap) * (diff / cap).abs();
    }

    // Last-chance bin bonus (smoothly weighted).
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mean residual coupling.
    score += 3.0 * (pr - mean_residual) / cap * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: quarter-capacity buckets
    let quarter = bin_capacity / 4;
    let post_class = post_residual / quarter; // 0..4
    let next_class = if next_item_size == 0 { 0 } else { next_item_size / quarter };

    // Reward when next item fits exactly into a harmonic class of post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack < quarter as f64 {
            score -= 6.0 + 0.05 * item_size as f64;
        } else if slack < (2 * quarter) as f64 {
            score -= 2.0;
        }
    }

    // Penalize post_residuals in awkward classes (small dead space unusable for mid items)
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening new bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: neutral baseline; discourage opening when a decent fit exists
    if bin_residual == bin_capacity {
        score = cap * 0.75;
        if fitting_bins_count > 0 {
            let best_possible = (bin_residual - item_size) as f64;
            if best_possible < quarter as f64 {
                score += 5.0; // force using the well-fitting open bin
            }
        }
        // late in stream, opening fresh bins is cheaper than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * progress;
    }

    // Mean residual coupling: prefer bins close to mean (balance-aware)
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // Prefer filling large fractions of the bin now
    score -= 0.3 * (item_size as f64 / cap) * 10.0;

    // Modulo tie-break: favor post_residual divisible into nice halves
    if post_residual % 2 == 0 { score -= 0.5; }
    if post_residual % 10 == 0 { score -= 1.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit typical future
    // items are wasted. Penalize small nonzero post_residuals heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 35 {
        score += 5.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 25.0 + 8.0 * open_bins_count as f64;
        // But if no open bin fits well (large mean residual mismatch), allow it.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    } else {
        // Slight reward for using already-open bins when many are open.
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Progress scaling: later in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: post_residual exactly matches next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Dead space: post_residual too small for the next item (unusable gap).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 2.0 * post_residual as f64;
        // Extra penalty if next item is large (big item stranded).
        score += 0.5 * next_item_size as f64;
    }

    // Tight fit reward: leaving minimal slack relative to capacity.
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Penalize new bins early / when open bins are still roomy.
        score += 60.0 - 50.0 * fragmentation + 2.0 * open_bins_count as f64;
        // Late in stream, opening fresh bins is more acceptable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    // Slight preference for bins already below mean residual (consolidate waste).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_capacity as f64 - post_residual as f64) * (0.3 + 0.7 * progress);

    // Penalize dead space: post-residual too small to ever be useful (min item 1, but
    // practically small residuals are waste); quadratic penalty on tiny leftovers.
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += 40.0 / pr; // smaller leftover => bigger penalty... invert: reward moderate leftovers
        score -= 40.0 / pr;
        if pr < 5.0 {
            score += 8.0 * (5.0 - pr); // dead space penalty
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 10.0 + 0.2 * n;
        } else if next_item_size <= bin_residual {
            // next fits current bin but not after this placement -> mild penalty
            score += 3.0;
        }
        // Penalize leaving a residual that almost fits next item (tempting waste)
        let gap = post_residual as f64 - n;
        if gap > 0.0 && gap < 5.0 {
            score += 4.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing
    // bins with residual near mean (consolidation), discourage fragmentation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    if open_bins_count > 4 && mean_residual > item_size as f64 {
        score -= 2.0; // encourage packing into existing space when bins abound
    }

    // New-bin candidate handling: empty bin should only win when item is large
    // relative to capacity or no good fits exist.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 6.0 + 20.0 * (1.0 - frac);
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin
        }
        if item_size > bin_capacity / 2 {
            score -= 8.0; // large items pair well with fresh bins
        }
    }

    // Mild preference for bins whose residual is close to item size (perfect-ish fit).
    let fit_gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 15.0 * fit_gap * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling: post_residual scaled by progress polynomial
    let norm_pr = pr / cap;
    let poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 12.0 * norm_pr * norm_pr * (1.0 + poly);

    // Reward tight fits, stronger as stream progresses
    score -= poly * (1.0 - norm_pr) * 8.0;

    // Last-chance bonus (smooth ramp, not piecewise)
    let last_chance = 1.0 / fitting_bins_count.max(1) as f64;
    score -= 6.0 * last_chance * (1.0 + poly);

    // Penalize creating dead space below next item's needs (smooth quadratic)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 15.0 * gap * gap * (1.0 - poly);
    } else {
        // end of stream: fully reward using residual space
        score -= 5.0 * (1.0 - norm_pr);
    }

    // Mild penalty for opening new bins when many exist (smooth in open_bins_count)
    if bin_residual == bin_capacity {
        score += 2.0 * (open_bins_count as f64).sqrt() * (1.0 - poly) + 4.0;
    }

    // Coupling with mean residual: prefer bins deviating favorably from mean
    score += 0.15 * (pr - mean_residual).abs() * (0.5 + poly);

    // Prefer larger items into tighter bins (smooth interaction)
    let item_frac = item_size as f64 / cap;
    score -= 4.0 * item_frac * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: classify dead space into capacity fractions ---
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Class bonus/penalty based on which capacity-fraction band post_residual falls into.
    if post == 0.0 {
        score -= 60.0; // perfect fit: always reward heavily
    } else if post <= eighth {
        score -= 25.0; // near-perfect: small sliver, still great
    } else if post <= quarter {
        // quarter-class: only good if a future item of that class can use it
        score -= 8.0;
    } else if post <= cap / 2.0 {
        score += 6.0; // half-class: mediocre
    } else {
        score += 14.0; // large residual: wasteful placement
    }

    // --- Harmonic divisibility: does post_residual decompose into small item sizes? ---
    let pr = post_residual;
    // Item sizes 1..100; common small sizes create reusable remainders.
    let mut harmony = 0.0f64;
    for s in [10u32, 20, 25, 30, 40, 50].iter() {
        if pr >= *s && pr % s == 0 {
            harmony += 10.0;
        }
    }
    // Exact harmonic: post_residual is itself a plausible item size (10..80 range heuristic)
    if pr >= 10 && pr <= 80 {
        harmony += 12.0;
    }
    score -= harmony;

    // --- Lookahead coupling: can next_item_size exactly consume the post residual? ---
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0; // chain fit: reserve this bin for the next item
        } else if next_item_size < pr {
            let nxt = next_item_size as f64;
            let fill_ratio = nxt / post;
            // reward leaving space proportional to how well the next item fills it
            score -= 20.0 * fill_ratio;
            // penalize if next item leaves another awkward half-class gap
            let nxt_post = pr - next_item_size;
            if nxt_post > 0 && nxt_post < 10 {
                score -= 6.0; // tiny dead space is fine
            } else if nxt_post >= 10 && nxt_post <= 40 {
                score += 4.0; // mid dead space is worse
            }
        } else {
            // next item cannot use this bin's remainder at all: slight penalty
            score += 5.0;
        }
    }

    // --- Integer-division thresholds on post_residual vs item size ---
    let half_items_fit = (pr / item_size.max(1)) as f64;
    if half_items_fit >= 2.0 {
        score -= 5.0; // remainder can hold multiple more items of this size class
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0; // strongly prefer using the only bin that fits, avoid new bin
    }

    // --- New-bin candidate handling: bin_residual == bin_capacity ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing fits are terrible
        // (huge post residual means we'd waste space anyway) or few bins fit.
        let waste_if_forced = if post_residual >= 50 { 20.0 } else { 0.0 };
        score = cap - post as f64 + 15.0 - waste_if_forced;
        // Slightly discourage new bins early in the stream when many bins already fit
        if fitting_bins_count > 2 {
            score += 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= 50 {
            score += 5.0; // fresh bin useful for pairing with next item
        }
    }

    // --- Stream progression: tighten packing as stream matures ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress; // compress scores late (relative ordering preserved, mild sharpening)
    score -= progress * (mean_residual / cap) * 3.0; // favor bins far from mean residual late

    // --- Open bin count pressure: avoid bin explosion ---
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1, but
    // realistically small gaps) can use are pure waste. Penalize gaps in the
    // "dead zone" super-linearly.
    if post_residual > 0 {
        // Dead-zone threshold: gaps too small for typical items to matter.
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64);
        } else if post_residual <= 25 {
            // Moderately wasteful zone.
            score += 8.0 * (26.0 - post_residual as f64);
        }
    } else {
        // Perfect fit: strongly reward.
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (good chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Bin cannot host the next item; mild penalty, worse if gap is tiny.
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; encourage using existing bins when many are open.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.3 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the
    // stream and when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * progress + 1.5 * open_bins_count as f64;
    }

    // Mild alignment with mean residual: prefer bins with below-average
    // residual (tighter bins) to consolidate.
    score += 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 100.0 - gap as f64 * 5.0;
            } else {
                // penalize leaving space that next item only partially uses
                score += gap as f64 * 0.5;
            }
        }
        // penalize if next item cannot fit here (chain break)
        if post_residual < next_item_size && post_residual > 0 {
            score += 30.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin bonus: avoid wasting the only fitting bin's space
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize new-bin candidate slightly unless it's genuinely better
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    // Prefer using more open bins over opening new ones as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed
    let t = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;

    // Reward tight fits: penalize large post_residual nonlinearly
    score += (post_residual as f64 / cap).powi(3) * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here; penalize leaving residual close to but below next item
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * (1.0 - gap / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer filling existing bins over opening new ones
    let pressure = (open_bins_count as f64).ln() * 4.0;
    score += pressure;

    // New-bin candidate handling: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        // base penalty grows over time (consolidation more valuable later)
        score += 35.0 + 25.0 * t;
        // but if mean residual across open bins is small (fragmented), new bin is fine
        score -= (mean_residual / cap).max(0.0) * 15.0;
        // if item is large relative to typical residual, new bin helps
        if (item_size as f64) > mean_residual {
            score -= 12.0;
        }
    }

    // Global state: when mean residual is high, waste is acceptable; when low, be greedy
    score += (mean_residual / cap) * 10.0 * (1.0 - t);

    // Prefer bins whose residual is close to item size (best-fit coupling)
    let tightness = 1.0 - (bin_residual - item_size) as f64 / cap;
    score -= tightness * 12.0;

    // Late stream: penalize residual that can't fit small items (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 5.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) shaping.
    let mut score = pr_norm * (1.0 + pr_norm) + pr_norm * pr_norm * pr_norm * 0.5;

    // Smooth coupling with stream progress: early on, tolerate slack (favor spreading);
    // later, tighten packing and punish residual more aggressively.
    let progress_tightening = 1.0 + 1.5 * progress * progress;
    score *= progress_tightening;

    // Interaction: leftover that could fit the next item is valuable (reward).
    if next_item_size > 0 {
        let nx = (next_item_size as f64).min(cap) / cap;
        // Smooth "fit indicator" via a bell-shaped coupling rather than a hard cutoff.
        let fitness = (-((pr_norm - nx) * (pr_norm - nx)) / 0.02).exp();
        let bonus = 0.6 * fitness * (1.0 - progress * 0.5);
        score -= bonus;
        // Penalize when post-residual is just barely too small for next item (dead space).
        let near_miss = (-((pr_norm - nx + 0.01) * (pr_norm - nx + 0.01)) / 0.005).exp();
        score += 0.35 * near_miss * (1.0 - pr_norm);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 - pr_norm * pr_norm);
    }

    // Slight preference to keep bins balanced with mean residual (smooth term).
    let dev = (mean_residual - pr) / cap;
    score += 0.1 * dev * dev;

    // New-bin candidate: empty bin gets a smooth penalty that grows with progress
    // and with the number of open bins, but relaxes when item is large.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let openness = (open_bins_count as f64).ln_1p();
        score = 1.2 + 2.5 * progress * progress + 0.15 * openness - 1.5 * item_frac * item_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // "usable" residue classes via integer division thresholds.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual: class 0 = tiny leftover (great fit),
    // higher classes = progressively more wasted space.
    let post_class = post_residual / 10; // 0..=10 classes
    let class_penalty: f64 = match post_class {
        0 => -30.0,                       // near-perfect fit
        1 => -12.0,                       // 10..19 leftover, still attractive
        2 => -4.0,
        3 => 3.0,
        4 => 8.0,
        5 => 12.0,                        // half-full leftover: mediocre
        6 => 14.0,
        7 => 16.0,
        8 => 18.0,
        9 => 20.0,
        _ => 22.0,                        // barely touched bin
    };
    score += class_penalty;

    // Modulo coupling: residuals that are multiples of common item sizes
    // (e.g. divisible by 5 or 10) are more likely to be filled later.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving large dead space
            let dead = post_residual as f64;
            if dead > next_item_size as f64 - post_residual as f64 {
                score += 2.0;
            }
        }
    } else {
        // Last item: just minimize waste.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // New-bin candidate handling: an empty bin has post_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin early in the stream or when existing bins
        // have poor (large) residuals; penalize it when a decent fit exists.
        let mean_r = mean_residual;
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 25.0 + open_pressure * 5.0 - mean_r * 0.3 - progress * 10.0;
        // If the item is large, a fresh bin is more attractive.
        score -= (item_size as f64) * 0.15;
    }

    // Slight bias toward filling bins with small residuals relative to mean.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never be filled again
    // (below the minimum plausible item size) are doubly wasteful.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 50.0; // unreachable, but keeps invariant
    }

    // Quadratic penalty on unusable dead space: gaps that are too small for
    // the lookahead item (or any realistic item) are pure loss.
    let pr = post_residual as f64;
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 0.8 * pr * pr / bin_capacity as f64;
    }
    // General dead-space curvature: prefer leaving large usable gaps OR zero gap
    // over leaving awkward mid-sized gaps.
    if pr > 0.0 {
        score += 0.35 * (1.0 - pr / bin_capacity as f64) * pr;
    }

    // Reward near-perfect fits strongly.
    if pr == 0 {
        score -= 25.0;
    } else if pr <= 5 {
        score -= 8.0;
    }

    // Open-bins pressure: discourage opening a new bin when plenty of bins
    // already fit the item; encourage reusing existing bins to cap bin count.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 12.0 + 3.0 * fitting_bins_count as f64;
        }
        score += 0.5 * open_bins_count as f64;
    } else {
        // Favor bins that are more filled relative to others (lower residual vs mean).
        score -= 0.4 * (mean_residual - pr);
        // Last-chance bin: if this is the ONLY bin that fits, strongly prefer it.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Lookahead synergy: if the next item exactly matches the post residual,
    // this placement sets up a perfect follow-up fit.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize residuals that cannot fit the next item (dead space for lookahead).
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0 + 0.2 * post_residual as f64;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 10.0;
    }

    // Reward bins whose residual is below mean (already tight bins).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin, unless current placement
    // creates large unusable waste.
    if bin_residual == bin_capacity {
        let waste_penalty = if next_item_size > 0 && post_residual < next_item_size {
            0.0 // allow new bin when placement would strand space
        } else {
            50.0
        };
        score += 25.0 + waste_penalty + 0.1 * open_bins_count as f64;
    }

    // Mild phase scaling: be pickier early when many items remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
    score *= 0.8 + 0.4 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: tiny post_residual is excellent.
    if post_residual > 0 {
        score -= (bin_capacity as f64 / post_residual as f64) * 0.8;
    } else {
        score -= 40.0; // perfect fit bonus
    }

    // Lookahead: if the next item also fits in the post-residual, this bin is doubly valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64 / 10.0);
    }
    // If next item nearly fits, mild penalty for leaving a just-too-small gap.
    if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 10 {
        score += 8.0;
    }

    // New-bin candidate handling: opening a bin wastes capacity; only attractive
    // when no open bin fits, or all fits are terrible, or bin count is low.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let avg_fit_quality = if fitting_bins_count > 0 { mean_residual } else { 0.0 };
        // Penalize new bins more when many bins already fit the item well.
        score += 15.0 + (fitting_bins_count as f64) * 3.0;
        // Late in the stream, prefer reusing bins even more.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 10.0;
        // If mean residual is large, existing bins are roomy; avoid opening new.
        score += avg_fit_quality * 0.15;
        // Early stream with few bins: opening is cheaper.
        if open_bins_count < 3 {
            score -= 10.0;
        }
    } else {
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Prefer bins whose residual is below average (they're getting full).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
        // Slight preference to fill many small bins early, keeping big residuals
        // available for large future items.
        let progress = step_index as f64 / total_items as f64;
        if progress < 0.5 && bin_residual > 50 {
            score += 3.0;
        }
        // Late stream: consolidate aggressively into the emptiest-feeling bins.
        if progress > 0.7 {
            score -= (bin_capacity - bin_residual) as f64 * 0.1;
        }
    }

    // Mild penalty for very large item into a nearly full bin creating dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // small dead space is worse than exact fit but ok
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score += 40.0 * norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score -= 25.0 * norm_pr * progress * (1.0 - progress) * 4.0;
    score -= 18.0 * norm_item * norm_item * (1.0 - progress);
    score += 12.0 * norm_pr * norm_pr * norm_pr;

    // Tight-fit reward: smooth Gaussian-like bump near small post_residual
    score -= 30.0 * (-(norm_pr * norm_pr) / 0.01).exp();

    // Lookahead coupling: reward if next item fits smoothly into post_residual
    if next_item_size > 0 {
        let gap = norm_pr - norm_next;
        let fits = (gap / 0.15).exp() / (1.0 + (gap / 0.15).exp());
        score -= 22.0 * fits * (1.0 - progress);
        score += 10.0 * (norm_next * norm_pr);
    }

    // Penalize many fitting bins weakly (prefer scarce-fit bins)
    if fitting_bins_count > 0 {
        score += 6.0 * (fitting_bins_count as f64).ln();
    }
    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mean-residual smooth deviation term
    score += 8.0 * (pr - mean_residual) / cap;

    // New-bin candidate: neutralize base residual, slight progressive penalty
    if bin_residual == bin_capacity {
        score = pr + 20.0 * progress + 5.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify into capacity fractions.
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward near-perfect fits: residual in the lowest harmonic class.
    if post_residual == 0 {
        score -= 100.0; // perfect closure
    } else if post_residual <= eighth {
        score -= 30.0 + (eighth - post_residual) as f64;
    } else if post_residual <= quarter {
        score -= 12.0;
    } else if post_residual <= quarter * 2 {
        score += 6.0;
    } else {
        score += 15.0;
    }

    // Modulo arithmetic on residual classes: residuals that are "friendly"
    // to common item sizes get a bonus (residual divisible by 10 blocks).
    let friendly = post_residual % 10 == 0 || post_residual % 20 == 0;
    if friendly {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let npost = post_residual - next_item_size;
            if npost <= eighth {
                score -= 18.0 + (eighth - npost) as f64;
            } else {
                score -= (npost as f64) * 0.05;
            }
        } else {
            // next item cannot follow here: penalize blocking small residuals
            score += (post_residual as f64) * 0.10;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer filling already-open bins when many are open (avoid bin proliferation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.3 * (0.5 + progress);

    // New-bin candidate: make it unattractive unless the fit here is terrible.
    if bin_residual == bin_capacity {
        // Opening a new bin is only good if no open bin gives a decent fit.
        let tightness = 1.0 - (item_size as f64 / cap);
        if fitting_bins_count > 0 && tightness < 0.85 {
            score += 60.0; // discourage new bin when an open bin fits reasonably
        } else {
            score -= 5.0; // allow new bin for very large items or no alternatives
        }
    }

    // Mean-residual coupling: if this bin is far below mean residual it is
    // already "wasted"; placing here normalizes residuals.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += ((bin_residual as f64) - mean_residual) * 0.05;
    }

    // Integer-division threshold: residual in (0,10) is dead space; avoid creating it
    // unless it exactly closes the bin (already handled).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (below min item size 1..100,
    // treat < ~15 as likely unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0;
    } else if post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits (post_residual small relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 8.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate, which has bin_residual == bin_capacity).
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pressure = 6.0 * open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        score += pressure;
    } else {
        score -= 0.35 * pressure;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Prefer bins with below-average residual (compact bins first).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: perfect 2-step match bonus — bin fits item AND next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits too: reward tighter combined packing.
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize dead space left behind.
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer bins whose residual is already below mean (well-utilized bins).
    score += 0.3 * (mean_residual - bin_residual as f64).abs()
        * (if (bin_residual as f64) < mean_residual { -0.5 } else { 1.0 });

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize very small unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = bin_capacity as f64 - 20.0 * scarcity
            + if next_item_size > 0 && next_item_size >= item_size { 10.0 } else { 0.0 };
        if fitting_bins_count == 1 {
            score += 50.0; // never abandon the sole fitting bin
        }
    }

    // Slight preference to fill older bins early in the stream.
    score += 0.05 * (step_index as f64 / total_items.max(1) as f64) * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where item nearly fills residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 30.0 * fit_ratio;
    } else if fit_ratio < 0.35 {
        // Poor fit: leaves a large awkward gap; penalize.
        score += 8.0 * (0.35 - fit_ratio);
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item (1..100 range, use small floor).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // nearly unusable sliver
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = next_item_size as f64 / post_residual as f64;
        score -= 12.0 + 10.0 * chain_quality;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't chain here; slight penalty proportional to leftover size.
        score += 3.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: only bin that fits the item — strong reward to use it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Crowding pressure: many open bins with low mean residual -> prefer new bin.
        let crowding = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        let mut new_bonus = -crowding * 2.0;
        // Early on, keep bins open (consolidate); later, allow spreading.
        new_bonus += 10.0 * (1.0 - progress);
        // If item leaves huge residual in a fresh bin (small item), discourage opening.
        new_bonus += 0.15 * post_residual as f64;
        score += new_bonus;
    }

    // Global state: when mean residual across bins is high, encourage consuming it here.
    if !is_new_bin {
        let residual_gap = mean_residual - bin_residual as f64;
        score += 0.5 * residual_gap; // prefer bins with residual below average (tighter bins)
    }

    // Mild time-decay: late in the stream, closing bins tightly matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = fitting_bins_count as f64;

    // Non-linear polynomial coupling: normalized post residual vs progress
    let x = pr / cap;
    let p = progress;
    let coupling = x * x * (1.0 + 2.0 * p) - x * (0.5 + p);
    score += 30.0 * coupling;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - x).powi(2) * (10.0 + 20.0 * p);

    // Lookahead: if next item fits exactly in post residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let exact = 1.0 - (pr - nxt).abs() / cap;
            score -= 25.0 * exact * exact;
        } else {
            // penalize blocking the lookahead item
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * p;
    }

    // Mild penalty when many bins are open (consolidate)
    score += 0.3 * open_bins_count as f64 * x;

    // New-bin candidate: prefer keeping it only when nothing fits well
    if bin_residual == bin_capacity {
        let desperation = (fit - 1.0).max(0.0);
        score += 20.0 + 15.0 * desperation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common item
    // sizes are more reusable; penalize "odd" dead space classes.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly favored.
        score -= 60.0;
    } else {
        // Reusability bonus: post_residual divisible by small harmonic steps
        // (10, 20, 25, 50) tends to accept future items exactly.
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 3.0; }

        // Dead-space penalty for tiny unusable slivers (below the minimum
        // plausible item size), scaled by how "odd" the class is.
        if pr < 10 {
            score += (12.0 - pr as f64) * 2.5;
        }

        // Integer-division threshold classes: residuals in (0,20) rarely help;
        // mid classes are fine.
        let class = pr / 10; // 0..10 harmonic bucket
        score -= (class as f64) * 1.5; // bigger residual generally better

        // Lookahead coupling: if next item fits exactly into post_residual,
        // big reward; if it nearly fits, mild penalty for tempting waste.
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 45.0;
            } else if next_item_size <= pr {
                let slack = (pr - next_item_size) as f64;
                if slack < 10.0 {
                    score += (10.0 - slack) * 1.2; // near-miss creates sliver
                } else if slack % 10 == 0 {
                    score -= 6.0; // next item leaves aligned residual
                }
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin for a tight fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer keeping item with existing bins unless the
    // fit is poor. Penalize opening a new bin mildly, more when many bins
    // are already open with slack available.
    if bin_residual == bin_capacity {
        score += 20.0;
        if open_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 10.0 + mean_residual.min(100.0) * 0.1;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 8.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers mildly.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized. Define a "useful" threshold relative to
    // typical item sizes (assume small items possible, so keep threshold modest).
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) > 0.0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0; // unusable gap penalty
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Coupling with open_bins_count: penalize placements that leave large
    // residuals when many bins are already open (prefer tightening existing bins).
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += open_pressure * (post_residual as f64) * 0.5;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a tight bin; favor filling it (lower its score).
    let tightness = mean_residual - bin_residual as f64;
    score -= tightness * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid unnecessary bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else. Penalize the fresh bin mildly by default,
    // but reduce the penalty late in the stream or when the lookahead item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let lookahead_pressure = if next_item_size > item_size { 0.5 } else { 0.0 };
        score += 20.0 - 10.0 * progress - 10.0 * lookahead_pressure;
    }

    // Lookahead: if the next item exactly fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use the leftover; the residual is likely dead space
        score += (post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits in the post residual -> moderate reward
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 12.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
    }
    // Next item won't fit here: penalize wasted residual, scaled by how big the gap is
    else if next_item_size > 0 {
        score += 6.0 + 10.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Reward bins tighter than the mean residual (good fill), penalize looser ones
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate: encourage only when current bins are poor fits / fragmented
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_next = if next_item_size > 0 && post_residual < next_item_size { 0.5 } else { 0.0 };
        score += 18.0 - 30.0 * poor_fits - 15.0 * big_next - 10.0 * (1.0 - progress);
    }

    // Slight penalty for opening many bins late in the stream
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving dead space that no future item (min size 1..10) can use
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small slivers are fine-ish
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 5.0; // awkward gap zone
    }

    // Lookahead: if next item fits in post_residual, reward this bin strongly
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            // next item won't fit here; mild penalty scaled by waste
            score += 0.05 * (next_item_size as f64 - post_residual as f64).max(0.0);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins with high mean residual: encourage consolidation into emptier bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 6.0 * fill * (1.0 + progress);
        // prefer bins below mean residual (already well filled) when many bins open
        if open_bins_count > 3 {
            score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);
        }
    }

    // New-bin candidate handling: only attractive early or when nothing fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        // base cost of a new bin
        score += 18.0;
        // early stream or huge item: opening a fresh bin is more acceptable
        score -= 20.0 * (1.0 - progress) * (0.5 + big_item);
        score -= 30.0 * desperation;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // reserve space for a large follower
        }
    }

    // Mild penalty for wasting a nearly-full bin on a small item late in stream
    if bin_residual < bin_capacity && item_size < bin_residual / 2 && progress > 0.7 {
        score += 4.0 * (1.0 - item_size as f64 / bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_frac = item_size as f64 / cap;
    let pr_frac = pr / cap;

    // Base: prefer small post-residual, with a non-linear penalty on large dead space.
    let mut score = pr + 18.0 * pr_frac * pr_frac;

    // Reward tight fits: smooth polynomial coupling of fill ratio with post-residual.
    score -= 30.0 * fit_frac * fit_frac * (1.0 - pr_frac) * (1.0 + 0.5 * progress);

    // Stream-progress coupling: as the stream advances, demand tighter packing.
    score += 12.0 * progress * pr_frac * (1.0 - fit_frac);

    // Lookahead: penalize if next item cannot use the leftover space (smooth falloff).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = ((pr - nx) / cap).max(0.0);
        score += 10.0 * waste * waste;
        // Reward when leftover exactly accommodates the next item.
        let gap = (pr - nx).abs() as f64 / cap;
        score -= 8.0 * (1.0 - gap) * (1.0 - gap) * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a bin early, less so late in the stream.
    if bin_residual == bin_capacity {
        score += 6.0 + 20.0 * (1.0 - progress) + 0.8 * open_bins_count as f64;
    } else {
        // Mild congestion reward: using crowded bins is good.
        score -= 0.3 * open_bins_count as f64 * fit_frac;
    }

    // Mean-residual coupling: if bin residual is far from mean, slight penalty.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into coarse buckets.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 4.0).floor() as i32; // 0..3 quartile class
    let class_penalty = match class {
        0 => 0.0,      // nearly full bin: excellent
        1 => 8.0,      // small gap remains
        2 => 18.0,     // medium gap: wasteful
        _ => 30.0,     // large gap: very wasteful
    };
    score += class_penalty;

    // Reward near-perfect fits strongly.
    if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Modulo-arithmetic coupling: residual divisible by common item sizes (10/20/25/50)
    // suggests the leftover can host future harmonic items.
    if post_residual > 0 {
        let harmonics = [(10u32, 6.0), (20, 10.0), (25, 8.0), (50, 12.0)];
        for &(h, rew) in &harmonics {
            if post_residual % h == 0 && post_residual >= h {
                score -= rew;
                break;
            }
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 20.0 - (slack.min(20) as f64) * 0.5;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // leftover too small for next item: penalize dead space proportionally
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tighter ones (post_residual already does this)
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Prefer filling bins with low mean residual (compact the bin set).
    if mean_residual > 0.0 {
        score += (mean_residual - post_residual as f64) * 0.2;
    }

    // New-bin candidate handling: empty bin gets a neutral-but-not-terrible score.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, softened late in stream or when no good fit exists.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut nb = 40.0 + item_size as f64 * 0.15;
        if fitting_bins_count == 0 {
            nb -= 60.0; // no alternative
        } else if item_size > 60 {
            nb -= 20.0; // large items: fresh bin is reasonable
        }
        if progress > 0.9 {
            nb -= 5.0;
        }
        score = nb + post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps (< 10,
    // the minimum item size), which are guaranteed dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0 + (10 - post_residual) as f64 * 20.0;
    }

    // Slightly superlinear penalty on residual waste to prefer tight fits.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 150.0;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 300.0;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // and encourage consolidating into existing ones.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 40.0 + 60.0 * open_pressure;
        // But if no open bin fits well (best existing post-residual is tiny gap),
        // opening a new bin is fine — handled by the dead-space penalty above.
    } else {
        // Reward placing into existing bins when bin count is high.
        score -= 30.0 * open_pressure;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover < 10 {
            score -= 80.0;
        } else {
            score -= 20.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        }
    }

    // Mean-residual coupling: prefer bins close to the mean residual (balanced packing),
    // slightly more weight early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 - mean_residual).abs() * (0.3 + 0.4 * (1.0 - progress));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base best-fit: prefer tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Dead-space penalty: residual after placement that is too small for typical items.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: reward leaving room for the next item, penalize blocking it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // We could have left room for next item but won't after this placement.
            score += 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidating
    // into bins with below-average residual (tighter bins).
    if open_bins_count > 0 {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.3;
    }

    // Time horizon: early in the stream, be more liberal about opening new bins to keep
    // flexibility; late in the stream, pack tightly to close out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: discourage opening a new bin unless the fit into any
    // existing bin is poor.
    if bin_residual == bin_capacity {
        // Slight early-stream openness: cheaper to open bins when young.
        score += 20.0 - 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        } else if fitting_bins_count == 1 {
            score += 10.0; // there is a last-chance bin, prefer it over new
        }
        // If next item is large and this item is small, opening fresh may be fine.
        if next_item_size > item_size && next_item_size > 0 && item_size <= 20 {
            score -= 5.0;
        }
    }

    // Fragmentation guard: penalize bins whose residual becomes an awkward prime-like sliver.
    if post_residual > 0 && post_residual < 5 {
        score += 40.0;
    }

    // Mild preference for filling larger items into emptier bins early on.
    score += (item_size as f64 / bin_capacity as f64) * (1.0 - progress) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth coupling of post_residual with stream progress:
    // early on, waste is more tolerable; later, tight packing matters more
    let tightness = 0.5 + 1.5 * progress;
    score *= tightness;

    // Interaction: post_residual relative to mean residual across open bins
    let rel_mean = pr - mean_residual;
    score += 2.0 * rel_mean * (0.3 + progress);

    // Lookahead: reward leaving space for the next item (smooth polynomial)
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let fit_next = (pr >= nx) as i32 as f64;
        let gap = (pr - nx).abs() / cap;
        score -= fit_next * (8.0 + 20.0 * (1.0 - gap * gap));
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Slight penalty for many open bins relative to progress (encourage consolidation mid-stream)
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make empty bins mildly unattractive unless residuals elsewhere are bad
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" the leftover space is.
    // Residuals in coarse classes (e.g. >= next typical item) are valuable.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Integer-division thresholds on post_residual: classify leftover space.
    let class = post_residual / 10; // harmonic class bucket 0..=10
    let next_class = if next_item_size > 0 { next_item_size / 10 } else { 0 };

    // Reward when post_residual class is at least the next item's class
    // (next item fits without opening a new bin).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.5 * (class as f64 - next_class as f64);
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use, scaled by dead fraction
        let dead = (next_item_size - post_residual) as f64;
        score += 0.15 * dead;
    }

    // Modulo arithmetic: residuals that are "round" multiples of 25 or 50 are
    // naturally reusable (many item sizes divide into them).
    let m25 = post_residual % 25;
    let m50 = post_residual % 50;
    if m50 == 0 && post_residual > 0 {
        score -= 4.0;
    } else if m25 == 0 && post_residual > 0 {
        score -= 2.0;
    } else {
        // penalize awkward remainders
        score += 0.05 * (m25 as f64);
    }

    // Small post_residual => tight packing, reward strongly (best-fit flavor).
    if post_residual <= 5 {
        score -= 8.0;
    } else if post_residual <= 10 {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fits badly.
    if bin_residual == bin_capacity {
        // Opening fresh is fine early or when the item is huge relative to residuals.
        let waste = (bin_capacity - item_size) as f64;
        score += 12.0 - 0.1 * waste - 5.0 * progress;
        // If many open bins with slack, opening new is worse
        score += 0.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    } else {
        // Prefer fuller bins: reward low residual relative to mean
        score -= 2.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Slight tie-break toward bins far below mean residual (balance avoidance of
    // many half-empty bins) late in the stream.
    score += 0.02 * progress * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit
    }

    // Reward fits that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // creates gap the next item cannot use
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).sqrt() * 4.0 * (0.5 + progress);
    if bin_residual == bin_capacity {
        score += bin_pressure + 20.0; // new-bin candidate penalty
    } else {
        score -= bin_pressure * 0.5;
    }

    // Slight preference for bins tighter than average.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit bonus: strongly prefer filling the bin completely.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: does the NEXT item fit into the post residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            // Next item fits after this placement: excellent chain.
            score -= 60.0 + 0.5 * nxt;
            // Perfect 2-step fill: post residual exactly consumed by next item.
            if (post - nxt).abs() < 1.0 {
                score -= 120.0;
            }
        } else {
            // Next item will NOT fit here: penalize wasted residual proportional
            // to the gap, but discount for small dead space.
            let gap = post - nxt;
            score += 0.8 * gap;
            // Penalize leaving residual smaller than the smallest conceivable item (1),
            // i.e. unusable dead space.
            if post < 1.0 {
                score += 200.0;
            }
        }
        // Coupling with mean residual: prefer bins whose post-residual tracks
        // the mean residual (balanced packing), penalize outliers.
        let dev = (post - mean_residual).abs();
        score += 0.15 * dev;
    } else {
        // Last item: minimize final residual, exact fit is ideal.
        score -= 0.4 * (bin_residual as f64);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity and few bins fit it.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        // Mild penalty for opening a new bin by default.
        score += 25.0;
        // But if the item is huge and nothing else fits, allow the new bin:
        if fitting_bins_count == 0 {
            score -= 300.0;
        } else if fill_ratio > 0.7 && fitting_bins_count <= 2 {
            score -= 60.0 * fill_ratio;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Slight preference for tighter bins (small residual before placement)
    // to consolidate packing.
    score += 0.05 * (bin_residual as f64);

    // Mild penalty scaling with number of open bins to discourage sprawl.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: bonus if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here; mild penalty proportional to waste.
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // New-bin candidate handling: make opening a new bin attractive only
    // when the current item is large and open bins are quite full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fullness = 1.0 - mean_residual / cap;
        let pressure = avg_fullness * (item_size as f64 / cap);
        // Default new-bin score sits above good fits but below bad fits.
        score = cap * 0.55 - 40.0 * pressure - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative anyway
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0; // pairing potential in a fresh bin
        }
    }

    // Mild reward for consolidating when many bins are open.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * tightness;

    // Slight preference for filling bins deeper as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Reward tight fits: penalize non-zero post_residual quadratically.
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * cap;

    // Reward perfect fill strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let exact = ((pr - nx) / cap).powi(2);
            score -= 15.0 * (1.0 - exact) * (1.0 - progress);
        } else {
            // Next item won't fit here: mild penalty for stranding residual.
            score += 6.0 * norm_pr * progress;
        }
    }

    // Late in stream, prefer packing into existing bins (close them out).
    score -= 10.0 * progress * (1.0 - norm_pr);

    // Discard fragmentation relative to mean residual of open bins.
    score += 0.05 * (pr - mean_residual);

    // Mild penalty for opening new bins when many already open.
    if bin_residual == bin_capacity {
        score += 4.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: bins whose leftover lands in a
    // "usable" class (large enough to host future small items) get rewarded. ---
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: heavily reward.
        score -= 1000.0;
    } else {
        // Class the residual by integer division into 10-wide bands.
        let band = pr / 10; // 0..=9 bands
        // Dead-space bands: residuals of 1..9 are nearly useless.
        if band == 0 {
            score += 60.0;
        }
        // Mid bands: residual 20..50 is the most re-usable zone for typical items.
        match band {
            2 | 3 | 4 => score -= 15.0,
            5 => score -= 10.0,
            6 | 7 => score -= 5.0,
            8 => score -= 2.0,
            _ => {}
        }
        // Modulo-structure: residuals divisible by 10 are "clean" targets.
        if pr % 10 == 0 {
            score -= 6.0;
        }
        // Residual exactly matching a common item class (10/20/25/50) is prime.
        if pr == 10 || pr == 20 || pr == 25 || pr == 50 {
            score -= 12.0;
        }
    }

    // --- Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement sets up a perfect follow-up. ---
    if next_item_size > 0 {
        if next_item_size == pr && pr > 0 {
            score -= 80.0;
        } else if next_item_size <= pr && pr > 0 {
            let slack = pr - next_item_size;
            if slack <= 10 {
                score -= 20.0;
            } else {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here regardless; slight penalty for wasting
            // this bin's residual on a large leftover.
            if pr > 50 {
                score += 8.0;
            }
        }
    }

    // --- Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible. ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual <= 10 {
            score -= 30.0; // near-perfect use of last-chance bin
        }
    }

    // --- New-bin candidate handling: penalize opening a fresh bin when good
    // fits exist; reward it when all open bins would leave huge dead space. ---
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score += 40.0;
        // If current item is small and some bin nearly matches it, discourage new bin.
        if fitting_bins_count > 0 {
            let best_waste = (bin_capacity - item_size) as f64;
            if best_waste <= 15.0 {
                score += 50.0;
            }
        }
        // Late in the stream, opening bins is more acceptable (fragmentation risk lower).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // If mean residual across open bins is small (all bins nearly full),
        // a new bin is the right call.
        if mean_residual < 15.0 {
            score -= 45.0;
        }
        // Large items prefer fresh bins when nothing fits well.
        if item_size >= 60 && post_residual as f64 > mean_residual + 20.0 {
            score -= 10.0;
        }
    } else {
        // Existing bin: mild bonus for keeping bins balanced vs mean residual.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 3.0 / (1.0 + dev * 0.1);
    }

    // --- Fill-rate reward: prefer bins that become fuller. ---
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // --- Many open bins: encourage consolidation into fuller bins. ---
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count.min(20) as f64) * (1.0 - fill);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum item size) are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0;
    }

    // Penalize small-but-nonzero dead space more aggressively than large gaps:
    // a gap of 1..=10 is nearly unusable, larger gaps may still fit items.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    if post_residual > 0 {
        score -= (bin_capacity as f64 / post_residual as f64).min(50.0);
    } else {
        // Perfect fit: strong reward.
        score -= 120.0;
    }

    // Open-bins pressure: discourage spreading across many bins when few
    // fitting bins exist; encourage using scarce fitting bins.
    if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it over opening a new bin.
        score -= 60.0;
    } else {
        score += open_bins_count as f64 * 0.8;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item fits
    // poorly everywhere else (large item relative to typical residuals).
    if bin_residual == bin_capacity {
        let openness = step_index as f64 / (total_items.max(1) as f64);
        // Early in stream, opening bins is cheap; late, consolidation matters.
        let new_bin_bias = 25.0 + 60.0 * openness;
        // If the item is big, a fresh bin is often good (full-ish packing).
        if item_size >= 70 {
            score = new_bin_bias - 20.0;
        } else {
            score = new_bin_bias;
        }
        // Lookahead: if next item is large, a fresh bin is attractive.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    } else {
        // Lookahead synergy: if the post residual exactly fits the next item,
        // this placement is excellent.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 10 {
            score -= 20.0;
        }
    }

    // Mild preference for bins with residuals below mean (consolidate emptier
    // space into fewer bins).
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but never leave unusably tiny space
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space penalty: residual too small for any item (sizes >= 10... but sizes can be 1..100)
    }
    if post_residual > 0 && post_residual < 5 {
        score += 60.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // perfect chaining: this bin will be exactly filled next step
        } else if next_item_size <= post_residual {
            // next item fits here too: good, but not perfect
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual: mild penalty proportional to mismatch
            score += 5.0 * ((next_item_size - post_residual) as f64 / 100.0);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    let diff = mean_residual - bin_residual as f64;
    score += 0.5 * diff; // lower residual than mean => lower score

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: neutralize its raw full-residual score, make it moderately attractive
    // only when open bins are fragmented (high mean residual) or it's the only option.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: slightly worse than a good fit, better than a bad one
        score = bin_capacity as f64 * 0.85;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        if fitting_bins_count == 1 {
            // no open bin fits at all: opening a new bin is fine
            score -= 20.0;
        }
        if open_bins_count > 0 && mean_residual < 25.0 {
            // existing bins are tight and fragmented; opening a new bin is reasonable
            score -= 15.0;
        }
    }

    // Late in the stream: consolidate, avoid opening new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose residual is close to item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).powi(3);

    // Penalize post-residual dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can also host the lookahead item.
            score -= 8.0;
            let combo_waste = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - combo_waste / bin_capacity as f64);
        } else {
            // Dead space relative to lookahead item.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Near end of stream: prefer filling bins as fully as possible.
        score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this bin would leave a large unusable gap.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        let poor_fit_elsewhere = if fitting_bins_count > 0 {
            ((bin_residual - item_size) as f64).max(0.0)
        } else {
            0.0
        };
        let waste_penalty = if post_residual < 10 { 0.0 } else { post_residual as f64 };
        score += waste_penalty
            + 20.0 * (1.0 - crowded.min(1.0))
            - 12.0 * poor_fit_elsewhere / bin_capacity as f64
            - 5.0 * progress;
    } else {
        // Mild preference for bins below mean residual (rebalance load).
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Early stream: slightly favor opening bins to build flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post-residual), non-linearly scaled.
    let mut score = norm_pr * norm_pr * 40.0 + norm_pr * 20.0;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; late, minimize residual aggressively.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward near-exact fills with a smooth cubic bonus.
    let exactness = 1.0 - norm_pr;
    score -= exactness * exactness * exactness * 15.0;

    // Penalize bins whose residual deviates from the mean residual
    // (keeps residual distribution homogeneous and mergeable).
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0;

    // Lookahead: reward leaving space the next item can use.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let usable = if pr >= n { 1.0 } else { 0.0 };
        score -= usable * 6.0 * (1.0 - progress);
        // Smooth penalty if post-residual just barely misses next item.
        let miss = (n - pr) / cap;
        if miss > 0.0 && miss < 0.2 {
            score += miss * 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild penalty for spreading across too many open bins early.
    let bin_pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.1);
    score += bin_pressure * (1.0 - progress) * 3.0;

    // Slight preference for fuller bins overall (best-fit flavor).
    let fill = 1.0 - norm_pr;
    score -= fill * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod small divisors reveals
    // how "usable" the leftover space is for typical item granularities.
    let pr = post_residual;
    // Dead-space penalty grows when post_residual is small but not zero
    // (unusable slivers). Zero residual is perfect.
    if pr > 0 {
        let tiny = (pr <= 10) as f64 * 25.0;          // sliver penalty
        let awkward = ((pr % 10 != 0) as f64) * 3.0;   // non-decade leftover
        score += tiny + awkward;
    } else {
        score -= 40.0; // perfect closure reward
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            // next fits, but penalize by how much slack remains after it
            score -= 20.0 - ((pr - next_item_size) as f64) * 0.3;
        } else {
            // next item won't fit here: mild penalty proportional to gap
            score += ((next_item_size - pr) as f64).min(30.0) * 0.4;
        }
    }

    // Fraction-of-capacity harmonic classes on the current fill level.
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    let quarter = fill.fract(); // position within capacity fractions
    score += (quarter * 8.0).sin().abs() * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tighter fits among many candidates (best-fit core)
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are very full.
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        // early stream: keep bins open and pack them; late stream: allow spread
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + avg_fullness * 30.0 - progress * 15.0;
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity {
            score -= 8.0; // fresh bin useful for a big follower
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // it's already tight — reward finishing it.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.15;
    }

    // Prefer closing bins as open_bins_count grows (fragmentation control).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any item (min size 1)
    // are worthless; residuals in the awkward mid-range are heavily penalized.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: ideal
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect fit, likely dead space but tiny
    } else if post_residual < 25 {
        score += 35.0; // awkward gap: large enough to waste, small to be useful
    } else if post_residual < 50 {
        score += 8.0;  // moderately reusable gap
    } else {
        score -= 5.0;  // large residual remains flexible
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 10.0 + 4.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins with residual close to item size (tight fit relative to mean).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would exactly fill post-residual, reward more.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= 10.0 * progress;
    } else {
        score += 15.0 * progress;
    }

    // Mild preference relative to mean residual: avoid bins deviating wildly.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + item_size as f64;
    }

    // Reward when the next item can still fit in the residual (soft lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (post_residual as f64 - next_item_size as f64).min(30.0);
    }

    // Penalize residuals too small for the next item (dead space risk),
    // scaled by how close the dead space is to the smallest useful size.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = post_residual as f64;
        score += 8.0 * (1.0 - waste / next_item_size as f64);
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= 0.30 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no open bin gives a good fit,
    // i.e. when its full residual (== capacity) is large and fits the next item too.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) - 15.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        // Discourage new bins early in the stream when plenty of bins are open.
        score += 2.0 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream (0..1), used to modulate exploration vs exploitation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional tightness of the fit: how well item fills this bin.
    let fill = item_size as f64 / bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward excellent fits strongly (subtract).
    if post_residual == 0 {
        score -= 60.0; // perfect closure is always great
    } else if post_residual < 10 {
        score -= 35.0 * tightness;
    } else if post_residual < 25 {
        score -= 18.0 * tightness;
    } else if post_residual > 50 && item_size < 40 {
        // Penalize dumping small items into very roomy bins (waste of large residual).
        score += 12.0 + 0.15 * (post_residual as f64 - 50.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item would fit perfectly in the post
    // residual, reward this placement (creates a future perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize leaving awkward gaps
            // that are too small for typical items.
            if post_residual < 10 {
                score += 5.0;
            }
        }
    } else {
        // Last item in stream: closing bins is pure gain.
        score -= 20.0 * tightness;
    }

    // Global state coupling: many open bins with high mean residual means
    // fragmentation; prefer reusing bins and avoid opening new ones early.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins when existing bins
        // have plenty of collective room; allow it when bins are crowded.
        let crowd = mean_residual / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
        score += 30.0 + crowd * 20.0 - pressure.min(30.0);
        // Late in the stream, opening fresh bins is fine (spread tail items).
        score -= progress * 10.0;
    } else {
        // Favor bins whose residual deviates from the mean in a useful way:
        // prefer bins with residual close to item_size (tight relative fit).
        let rel_waste = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += rel_waste * 15.0;
        // Slight preference for bins with above-mean residual when item is large.
        if item_size as f64 > mean_residual {
            score -= 5.0;
        }
    }

    // Mild exploration bonus early in stream: encourage trying diverse bins.
    score -= (1.0 - progress) * 3.0 * ((step_index % 7) as f64 - 3.0).abs() / 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual
    let pr = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: post_residual penalized more heavily as stream progresses
    let poly = pr * pr * (1.0 + 3.0 * progress) + pr * progress * progress;
    score += poly * bin_capacity as f64;

    // Reward tight fits with smooth term
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 2.5 * tightness * tightness * (1.0 + progress);

    // Penalize residual smaller than next item (dead space), smoothly
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64 / bin_capacity as f64;
        score += 4.0 * gap * gap * (0.5 + progress);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        let fit = next_item_size as f64 / post_residual as f64;
        score -= 1.5 * fit * (1.0 - progress);
    }

    // Last-chance bin bonus (smooth, avoid new bin when it's the only fitting one)
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Slight preference to fill bins when many are open
    score += 0.1 * open_bins_count as f64 * pr;

    // Mean-residual coupling: discourage bins far from the mean in a smooth way
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 1.2 * dev * dev;

    // New-bin candidate: baseline cost plus progress-dependent reluctance to open new bins
    if bin_residual == bin_capacity {
        score += bin_capacity as f64 * (0.6 + 0.8 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space.
    // Class by integer division into bands of 10 (capacity fractions).
    let class = post_residual / 10;

    // Reward small residuals (perfect packing), scaled by class depth.
    score -= (10 - class.min(10)) as f64 * 2.0;

    // Dead-space penalty: residuals that are too small for the smallest
    // possible future item (1..100 interface) are nearly worthless.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: next item plugs the hole exactly or nearly.
            let slack = post_residual - next_item_size;
            score -= 25.0 + (10 - slack.min(10)) as f64 * 1.5;
        } else {
            // Next item won't fit here; penalize proportionally to overshoot.
            let over = next_item_size - post_residual;
            score += (over.min(50)) as f64 * 0.6;
        }
    } else {
        // Last item: prefer the tightest fit overall.
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits via residual ratio.
        let ratio = post_residual as f64 / bin_capacity as f64;
        score += ratio * 20.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by common
    // item sizes (multiples of 5/10) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Harmonic class threshold: residuals in [10, 30) are the classic
    // "awkward zone" for capacity-100 bins; discourage landing there
    // unless the next item fills it (already rewarded above).
    if class >= 1 && class <= 2 && next_item_size > post_residual {
        score += 12.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; keep it
    // attractive only when no open bin fits well or few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = open_bins_count as f64;
        // Early stream: opening bins is cheap. Late stream: prefer filling.
        score = score * 0.5 + 60.0 - progress * 25.0 - scarcity * 2.0;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big next item benefits from fresh space
        }
    }

    // Mean residual coupling: if this bin's post residual is far below the
    // mean, we are consolidating well.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= (mean_residual - post_f) * 0.3;
    } else {
        score += (post_f - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (min size 1, but practically small gaps waste capacity)
    // are heavily penalized. Dead space = post_residual that can't fit
    // next_item_size or a "typical" item.
    if post_residual > 0 {
        let next_fits = next_item_size > 0 && post_residual >= next_item_size;
        if !next_fits {
            // Gap is unusable for the lookahead item -> dead space penalty
            let dead = post_residual as f64;
            score += 2.5 * dead;
            // Extra penalty if gap is below the smallest plausible item band
            if post_residual < 10 {
                score += 30.0;
            }
        } else {
            // Reward a gap that exactly/loosely matches the next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 1.5 * (post_residual as f64) * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: prefer bins where item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open bins pressure: penalize using bins when many are open, to avoid
    // scattering; but if this is the only fitting bin, strongly prefer it
    // (last chance before opening a new bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    } else {
        score += 0.8 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: empty bin starts with score = capacity.
    // Make it moderately attractive only when current bin would leave a
    // large dead gap or when many bins are open.
    if bin_residual == bin_capacity {
        score -= 15.0;
        if post_residual > 60 {
            score += 25.0; // opening fresh for a small item wastes capacity
        }
        score += 1.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward leaving zero residual.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // 2-step lookahead: reward if next item fits exactly into post_residual.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 45.0;
            } else if next_item_size <= post_residual {
                // next item fits, but penalize leftover after the hypothetical second placement
                let two_step_left = post_residual - next_item_size;
                score -= 20.0 - (two_step_left as f64) * 0.25;
            } else {
                // next item won't fit here: penalize dead space relative to next item
                score += ((next_item_size - post_residual) as f64) * 0.3;
            }
        }
    }

    // Compare post_residual to mean residual: leaving residual near/below mean is good.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when decent alternatives exist, especially late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        // But allow new bin if it would be badly needed (no fitting bins elsewhere handled by comparison).
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin keeps full flexibility for next item
            score -= 10.0;
        }
    }

    // Mild penalty for large post_residual waste relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 150.0 + 20.0 * (5 - post_residual) as f64;
    }

    // Penalize dead space proportional to how unusable the remainder is.
    // Residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0 + 0.5 * next_item_size as f64;
        } else {
            // Penalize leaving a residual that blocks the next item.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
        // Perfect pairing: this item + next item exactly fill the bin.
        if item_size + next_item_size == bin_residual {
            score -= 300.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize opening a new bin when good fits exist.
    if bin_residual == bin_capacity {
        // Base handicap for opening a fresh bin.
        score += 90.0;
        // If many bins fit, discourage new bin further.
        if fitting_bins_count > 0 {
            score += 40.0 * fitting_bins_count as f64;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 70.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin is more attractive.
        score -= 0.4 * item_size as f64;
    } else {
        // Prefer filling bins that are already quite full (low residual).
        score -= 0.6 * (bin_capacity - bin_residual) as f64;
    }

    // Global state coupling: when mean residual across open bins is high,
    // prefer consolidating into existing bins rather than spreading.
    score += 0.25 * mean_residual;
    // More open bins -> slight preference for using existing ones.
    score += 3.0 * open_bins_count as f64;

    // Mild tie-breaking noise-free deterministic jitter based on step.
    score += ((step_index % 7) as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): mild quadratic growth keeps slack flexible.
    // Late (progress ~ 1): stronger cubic penalty on dead space.
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr.powi(3) * (3.0 * progress);
    score += poly * cap * 0.15;

    // Reward tight fits, smoothly scaled by progress.
    score -= (1.0 - norm_pr) * (1.0 + progress) * 6.0;

    // Last-chance bonus: strongly prefer this bin if it's the only fitting one,
    // amplified as the stream progresses.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + 2.0 * progress);
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack_ratio = (pr - nxt) / cap;
            score -= 4.0 * (1.0 - slack_ratio) * (1.0 + progress);
        } else {
            // Penalize leaving a residual just below the next item size.
            let gap = (nxt - pr) / cap;
            score += 6.0 * gap * gap * cap * 0.1;
        }
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    score += (open_bins_count as f64).ln() * 0.5;
    if mean_residual > 0.0 {
        score += (norm_pr * cap - mean_residual).abs() * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: harmonic class of post_residual modulo 10.
    let pr = post_residual;
    let class = pr % 10;
    if pr == 0 {
        score -= 1000.0; // perfect fill
    } else if class == 0 {
        score -= 40.0;   // residual in a "round" class, easy to fill later
    } else if class <= 3 {
        score -= 15.0;   // small residual, still usable
    } else {
        score += (class as f64) * 2.5; // awkward dead space penalty
    }

    // Integer-division threshold: residual buckets of size 10.
    let bucket = pr / 10;
    if bucket == 0 {
        score += 5.0; // nearly-full bin, fine
    } else if bucket <= 2 {
        score -= 10.0; // leaves a useful small pocket
    } else {
        score += bucket as f64; // large leftover, mild penalty beyond raw residual
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr {
            score -= 25.0;
        } else {
            // next item won't fit here: penalize leaving large unusable residual
            score += (pr as f64 - (pr % (next_item_size.max(1)) as f64)) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or there are many open bins with slack.
    if bin_residual == bin_capacity {
        let avg_frac = mean_residual / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0
            - avg_frac * 120.0
            - pressure * 200.0
            - (fitting_bins_count as f64) * 10.0;
        // If item is small, a fresh bin wastes capacity potential.
        if item_size <= 30 {
            score += 20.0;
        }
    }

    // Stream progression: early on, be more willing to open bins (explore).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 15.0;
    }

    // Tie-break: prefer bins whose residual deviates from mean (keep uniform bins flexible).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but practically < next_item_size) are wasted. Penalize unusable gaps hard.
    if post_residual > 0 {
        let unusable = post_residual < next_item_size.max(1);
        if unusable {
            score += 40.0 + post_residual as f64 * 0.5;
        }
    }

    // Reward exact and near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Fit ratio: prefer bins where item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage new bins and
    // encourage consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to pressure.
        score += 15.0 + pressure * 2.0;
    } else {
        score -= pressure * 0.5;
    }

    // Coupling with mean residual: if this bin's residual is far below mean,
    // it's a tight bin — favor filling it.
    let bin_res_f = bin_residual as f64;
    score -= (mean_residual - bin_res_f).max(0.0) * 0.3;

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 3 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) more aggressively than linear.
    score += (post_residual as f64).powf(1.3) * 0.02;

    // Aggressive 2-step lookahead: reward when next item exactly fills the residual left behind.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: this bin becomes exactly usable by the next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here: good, reward proportionally to how snugly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.15;
        } else {
            // Next item cannot use this bin: penalize dead space, worse when very small.
            let dead = post_residual as f64;
            score += (15.0 - dead.min(15.0) as f64) * 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64 > mean_residual.max(1.0) * 1.5
            || fitting_bins_count == 0;
        if poor_fit {
            score -= 10.0;
        } else {
            score += 50.0;
        }
    }

    // Mild pressure toward consolidating into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 + open_bins_count as f64 * 0.05;

    // Relative-to-mean adjustment: bins with residual below mean are more precious.
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that nearly fill the bin.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward mid-range dead space (hard to fill later).
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score -= 6.0; // tiny scraps are fine — nearly perfect fill
    } else if dead >= 10.0 && dead < 30.0 {
        score += 9.0; // awkward zone: neither small-item nor mid-item friendly
    } else if dead >= 30.0 {
        score += 2.0; // large residual still usable by many items
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 7.0;
        } else {
            score += 4.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64)).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 14.0;
        // Opening a bin is more attractive when many bins are open (spread load)
        // and residuals are large/fragmented.
        score -= 0.35 * open_bins_count as f64;
        // If the current item is small relative to mean residual, prefer existing bins.
        score += 10.0 * (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        // Late in the stream, consolidate rather than open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If next item is large, a fresh bin preserves a big contiguous space.
        if next_item_size >= 60 {
            score -= 8.0;
        }
    } else {
        // Prefer using more-open bins rather than fragmenting few bins heavily:
        // mild penalty when this bin's residual is much larger than mean (hoarding).
        if bin_residual as f64 > mean_residual * 1.5 {
            score += 3.0;
        }
    }

    // Early stream: slight preference to keep bins balanced.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (low post residual), non-linearly.
    let mut score = 2.0 * x * x + 0.5 * x;

    // Smooth polynomial coupling of post residual with stream progress:
    // early stream: mild preference for leaving medium space; late stream: strongly avoid residuals.
    let coupling = (x - 0.5) * (x - 0.5) * (0.5 - progress) * 3.0
                 + x * x * progress * 4.0;
    score += coupling;

    // Reward filling a bin completely (tiny post residual), smoothly.
    score -= (1.0 - x) * (1.0 - x) * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 6.0 + 3.0 * progress;
    } else if fitting_bins_count > 1 {
        // mild competition scaling: keep scores comparable across fitting bins
        score += 0.15 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: penalize residuals that cannot fit the next item, reward those that can.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 2.0 * (n / cap);
        } else {
            score += 1.5 * (1.0 - pr / n.max(1.0));
        }
    }

    // Contextual: when many bins are open, prefer consolidating into tight fits;
    // penalize bins far from the mean residual (encourages uniform depletion).
    if open_bins_count > 1 {
        let dev = (pr - mean_residual).abs() / cap;
        score += 0.8 * dev * dev;
        score -= 0.3 / (open_bins_count as f64).ln().max(1.0) * (1.0 - x);
    }

    // New-bin candidate handling: an empty bin has x = 1; add a moderate penalty
    // so a new bin is opened only when no open bin offers a decent fit,
    // with the penalty easing as the stream progresses.
    if bin_residual == bin_capacity {
        score += 5.0 - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact fit (0) is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Classify dead space by integer division thresholds.
        let cls = post_residual / 10; // 0..9 harmonic class
        // Dead space below 10 is nearly unusable (min item is 1..100, but small
        // residuals rarely match); penalize tiny-but-nonzero residuals hardest.
        if post_residual < 10 {
            score += 40.0;
        } else if post_residual < 25 {
            score += 10.0;
        } else {
            // Larger residuals are reusable; reward proportionally.
            score -= cls as f64 * 2.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 300.0;
        } else if slack < 10 {
            score -= 120.0;
        } else {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize mildly, scaled by how close it was.
        let gap = next_item_size.saturating_sub(post_residual);
        score += gap as f64 * 0.3;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tightest fit (already via post_residual),
        // small bonus for spreading load.
        score -= (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 60.0 - 20.0 * progress;
        // If the item fills the new bin well, encourage opening.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.7 {
            score -= 40.0;
        }
        // If no open bin fits, opening is unavoidable: make it cheap.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // If many open bins exist with high mean residual, prefer reusing them.
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 25.0;
        }
    }

    // Mild preference for balancing residuals toward the mean.
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }
    // Gaps that are too small for the smallest plausible future item (<= 3) are dead.
    if post_residual <= 3 {
        score += 60.0;
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + post_residual as f64 - next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here; penalize leaving a stranded gap.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.0 + progress);

    // Prefer bins with residuals close to the mean residual (balanced packing).
    score -= 1.0 / (1.0 + (bin_residual as f64 - mean_residual).abs());

    // Slight preference for tighter fits.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: post_residual == 0 is ideal
    if post_residual == 0 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nxt).abs();
        if nxt <= pr {
            // next item fits: reward tight coupling
            score -= 80.0 * (1.0 - gap / bin_capacity as f64);
            if gap < 1.0 {
                score -= 120.0; // perfect chain
            }
        } else {
            // next item won't fit here: penalize wasted residual proportional to gap
            score += 0.3 * gap;
        }
    }

    // Compare post_residual against mean residual: prefer bins left tighter than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize leaving large dead space relative to smallest possible item (1..100 unknown, use conservative 10)
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score -= 40.0; // small unusable slivers are fine (bin nearly full)
    } else if dead >= 10.0 && dead < 20.0 {
        score += 10.0; // awkward zone: too small for typical items, too big to ignore
    }

    // Early in stream: slight preference to consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage filling existing ones rather than spreading
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Lookahead coupling: reward bins whose leftover can host the next item,
    // weighted more strongly early in the stream (long remaining horizon).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + 0.3 * next_item_size as f64 * (1.0 - 0.6 * progress);
    }

    // Penalize dead space the next item cannot use (unusable fragmentation).
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0 + 0.12 * post_residual as f64 * (1.0 + progress);
    }

    // Last-chance bin: strongly favor the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening a fresh bin while open bins exist,
    // scaled by how much capacity is still idle elsewhere; relax late in stream.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 14.0 + 0.25 * mean_residual * (1.0 - 0.5 * progress);
        // If the next item also won't fit here later, opening now is less bad.
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 6.0;
        }
    }

    // Prefer tighter-than-average bins (below-mean residual = better packing).
    score += 0.18 * (mean_residual - bin_residual as f64);

    // Mild bonus for near-perfect fills.
    if post_residual <= 2 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, tolerate leftover space; late in the stream, squeeze harder.
    let mut score = post * (1.0 + 2.5 * progress) + 0.004 * post * post;

    // Reward tight fits non-linearly: fill ratio of the bin after placement.
    let fill = (cap - post) / cap;
    score -= 30.0 * fill * fill;

    // Penalize creating dead space that can't fit typical future items.
    if post > 0.0 && post < 10.0 {
        score += 6.0; // unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 + progress);
    }

    // New-bin candidate: only attractive when open bins are congested
    // or the fit is very poor relative to mean residual.
    if bin_residual == bin_capacity {
        let congestion = (fitting_bins_count as f64) / (open_bins_count.max(1) as f64);
        let poor_fit = (item_size as f64) / cap;
        score = 8.0 + 20.0 * (1.0 - congestion) + 15.0 * poor_fit * poor_fit - 10.0 * progress;
        // Discourage new bins when mean residual across bins is still healthy.
        score += 0.08 * mean_residual;
    }

    // Lookahead: if next item would fit in the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 5.0;
    }
    // If next item is big and this bin is the only fitting one, prefer placing here.
    if next_item_size > 0 && (next_item_size as f64) > post && (next_item_size as f64) <= bin_residual as f64 {
        score -= 3.0;
    }

    // Mild penalty for spreading across too many open bins late in the stream.
    score += 0.15 * (open_bins_count as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals that are "perfect partners" for common item sizes (10..100)
    // get rewarded; awkward residuals get penalized.
    let pr = post_residual;

    // Class A: residual is exactly reusable by next item -> strong reward.
    if next_item_size > 0 && pr == next_item_size {
        score -= 40.0;
    }
    // Class B: residual divisible into clean halves/quarters of capacity.
    if pr > 0 && (bin_capacity % pr.max(1)) == 0 {
        score -= 8.0;
    }
    // Class C: dead space bands — residual too small for typical next items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead_threshold = 5.0 + 10.0 * progress;
    if pr > 0 && (pr as f64) < dead_threshold {
        score += 25.0;
    }

    // Harmonic coupling: if next item fits exactly in post_residual's
    // integer-division slot, reward.
    if next_item_size > 0 {
        let slots = pr / next_item_size.max(1);
        if slots >= 1 {
            score -= 6.0 * slots as f64;
        }
        // Penalize wasting residual larger than next item by a lot.
        if pr > next_item_size * 2 {
            score += 4.0;
        }
    }

    // Last chance bin: strongly favor using it rather than opening new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline, penalized slightly so we
    // prefer filling open bins unless fit is terrible.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
        // If current item leaves a harmonic residual in a fresh bin, prefer open bins less
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 5.0;
        }
    }

    // Prefer tighter bins overall: compare against mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Mild pressure to consolidate when many bins open.
    score -= 1.5 * open_bins_count as f64 / (open_bins_count as f64 + 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 12) are dead weight; penalize them quadratically.
    if post_residual <= 12 {
        score += (13.0 - post_residual as f64) * (13.0 - post_residual as f64) * 1.5;
    } else if post_residual < item_size as f64 * 0.25 {
        // Small relative gap: unusable for most items, mild penalty.
        score += 8.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 10.0;

    // If the next item can use the remaining space, reward keeping it usable.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
        // Bonus when post_residual is a near-perfect slot for the next item.
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 6.0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Next item cannot use this gap; penalize proportionally.
        score += (next_item_size as f64 - post_residual as f64).min(15.0) * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins (penalize the new-bin candidate).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + open_bins_count as f64 * 1.2 + progress * 8.0;
        // Allow opening a new bin early in the stream when few bins exist.
        if open_bins_count <= 2 && progress < 0.1 {
            score -= 6.0;
        }
    } else {
        // Slight preference for bins with below-average residual (fuller bins).
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Two-step lookahead: reward when the next item exactly fills the leftover space ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect 2-chain: next item exactly fills the bin -> strong reward
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item fits into the post-residual gap: reward proportional to tightness
        else if next_item_size <= post_residual {
            let fit_ratio = nxt / post;
            score -= 35.0 * fit_ratio;
        }
        // Next item cannot use the gap: penalize proportional to wasted gap size
        else {
            let waste_ratio = post / nxt;
            score += 12.0 * waste_ratio.min(3.0);
        }

        // Coupling with mean residual: gaps far below mean are less valuable to preserve
        let dev = (post - mean_residual) / (mean_residual + 1.0);
        score += 8.0 * dev;
    } else {
        // Last item: purely minimize residual
        score = post_residual as f64;
    }

    // --- Last-chance bonus: this is the only bin that can fit the item ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // --- New-bin candidate handling: only attractive when no open bin fits well ---
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when open bins leave large gaps
        let mut new_bin_score = bin_capacity as f64 * 0.9;
        if next_item_size > 0 && next_item_size <= post_residual {
            new_bin_score -= 20.0;
        }
        // More open bins with small residuals -> opening a new bin is more attractive
        let crowding = (open_bins_count as f64).ln() * 5.0;
        new_bin_score -= crowding;
        score = new_bin_score;
    }

    // --- Slight progression pressure: prefer compacting early, spreading later ---
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Perfect fit gets a huge reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins -> mild penalty to encourage spreading across bins
    // (keep the tightest ones); few fitting bins -> mild reward.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // post_residual too small for next item: penalize dead space unless tiny.
            if post_residual < 10 && post_residual > 0 {
                score += 5.0;
            }
        }
    }

    // Global state coupling: penalize placements into bins whose residual deviates
    // from the mean residual (prefer balancing residuals across open bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: late in the stream, be more conservative about opening new bins
    // (fewer items left to fill them), so reward using existing bins more strongly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tight;

    // New-bin candidate: make it attractive only when no open bin fits well,
    // i.e., when mean residual is large but this bin (empty) offers clean space.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, discounted when few bins are open or
        // when the current item is large (large items leave big residuals anyway).
        let open_cost = 20.0 + 0.3 * open_bins_count as f64;
        let discount = if item_size > 60 { 0.5 } else { 1.0 };
        score += open_cost * discount;
        // If existing bins have lots of scattered residual, a fresh bin is fine.
        if mean_residual > 40.0 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: tight fits preferred (small post-residual rewarded).
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post-residual with stream progress.
    // Early on, large residuals are tolerable; late in the stream, waste is punished harder.
    let waste_penalty = x * x * (1.0 - progress) * 8.0 + x * x * x * progress * 22.0;
    score += waste_penalty;

    // Smooth reward for residuals that still accommodate plausible future items.
    let next_fits = if next_item_size > 0 { (next_item_size as f64 / cap) } else { 0.0 };
    let usable = if x >= next_fits && next_item_size > 0 {
        (x - next_fits).max(0.0)
    } else {
        0.0
    };
    score -= usable * usable * 10.0 * (1.0 + progress);

    // Penalize near-full-but-not-full dead zones with a smooth bump around small x.
    let dead_zone = (-(x - 0.05) * (x - 0.05) / 0.01).exp();
    score -= dead_zone * 6.0;

    // Last-chance bin: strong incentive to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.05 * progress;

    // Encourage closeness to mean residual (balance load) via smooth quadratic.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 4.0;

    // New-bin candidate: keep it neutral-to-slightly-high so it only wins when
    // all open bins are truly poor fits; the polynomial waste penalty dominates.
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify leftover space by capacity fraction.
    // Small post-residuals (< 10) are "perfect fits" -> strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 40.0;
    } else {
        // Dead-space penalty grows for residuals in awkward harmonic bands.
        let band = post_residual / 10; // integer division: 1..=9 bands
        score += (band as f64) * 2.0;
        // Residuals that are NOT expressible as sums of typical item sizes get extra penalty.
        let m = post_residual % 10;
        if m != 0 && m < 5 {
            score += 3.0;
        }
    }

    // Coupling with next item: reward if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item won't fit here: penalize leaving a large unusable chunk.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when no open bin
    // offers a good (tight) fit.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // A new bin is attractive for large items or when existing residuals are all poor.
        let mean_tight = mean_residual / bin_capacity as f64;
        if fitting_bins_count == 0 || mean_tight < tightness * 0.5 {
            score -= 20.0 + tightness * 30.0;
        } else {
            score += 15.0 + mean_tight * 20.0;
        }
    }

    // Progress-based modulation: early in the stream, keep bins open and flexible;
    // late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;
    score += (open_bins_count as f64) * 0.3;

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (keeps the bin population homogeneous and predictable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to be useful are heavily penalized.
    // Treat residual < 10 (min plausible item) as pure dead space.
    let dead_threshold: f64 = 10.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        // dead space: quadratic blow-up, worse the closer to being wasted
        score += (dead_threshold - pr) * 8.0 + 15.0;
    } else if pr == 0.0 {
        // perfect fit: strong reward
        score -= 40.0;
    } else {
        // usable gap: mild reward proportional to tightness of fit
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 10.0 * tightness;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            // post residual can't host next item: penalize proportionally
            score += ((next_item_size - post_residual) as f64).min(30.0) * 0.5;
        } else {
            score += (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // Open-bin pressure: discourage proliferation of bins, scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (keeps the fleet homogeneous and predictable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // New-bin candidate: base penalty so it only wins when all open fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tightest fill (lowest post_residual), scaled.
    score *= 1.0;

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post_residual, strongly reward this bin (chain of perfect fits).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportionally to how well next item fits the leftover.
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space more
            // when the leftover is small and unusable.
            let dead = next_item_size - post_residual;
            score += dead as f64 * 0.15;
        }
    }

    // Compare post_residual relative to mean residual of open bins:
    // leaving less than average is good (bin more consolidated).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral baseline; discourage it when decent fits
    // exist, but keep it attractive when open bins would waste space.
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost = full capacity of potential.
        // Prefer it only if the best existing fit would leave big waste.
        score = 100.0 - 0.3 * mean_residual;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.2 * next_item_size as f64;
        }
        if fitting_bins_count == 1 && item_size >= 50 {
            // Last-chance with a large item: opening new bin is wasteful.
            score += 30.0;
        }
    }

    // Early in the stream, be slightly more willing to consolidate
    // (fewer bins open => better future flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Penalize creating very small unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are valuable: reward small post-residual super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no future item (sizes >= 1) can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny slivers are nearly unusable
    }

    // Lookahead: if next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack_after_pair = post_residual - next_item_size;
            score -= 15.0 * (1.0 - slack_after_pair as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow here; mild penalty scaled by overflow
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.15 * overflow;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += 4.0 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: placing into a bin far from the mean residual
    // (i.e., unusually full) is good if it fits — reward balancing toward fullness.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev * (bin_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); later, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 20.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: neutral-ish, but penalize slightly so it only wins
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 35.0 - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Smooth interaction: penalize large post-residuals more as stream progresses
    score += 20.0 * pr_norm * pr_norm * progress;

    // Reward tight fits (small post_residual) with a smooth coupling term
    score -= 15.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 + progress);

    // Lookahead coupling: favor bins whose post_residual fits the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 10.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 5.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - pr_norm);
    }

    // Mean residual deviation: smooth quadratic penalty for deviating from average slack
    score += 3.0 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Mild preference to fill existing bins as open bins accumulate
    score += open_bins_count as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals in "tight" classes (small leftovers) are valuable; large leftovers waste space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Integer-division thresholds: post_residual bucketed by 10s (harmonic classes of C/10).
    let class = post_residual / 10; // 0..=10
    match class {
        0 => score -= 25.0,                 // near-perfect fit, tiny dead space
        1 => score -= 18.0,                 // excellent fit
        2 => score -= 10.0,                 // good fit
        3 => score -= 4.0,                  // decent
        4 | 5 => { score += 3.0; }          // mediocre: half-capacity leftovers
        6 | 7 => { score += 8.0; }          // poor
        _ => { score += 14.0; }             // mostly-empty bin being used poorly
    }

    // Exact-fit classes via modulo: residuals divisible by 5 or 10 pair better with
    // typical item sizes drawn on the same lattice.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item exactly fills the post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after that pair
            let after2 = post_residual - next_item_size;
            score -= (10.0 - (after2 as f64) / 10.0).max(0.0);
            if after2 % 10 == 0 { score -= 4.0; }
        } else {
            // next item cannot use this residual: penalize large residuals more
            score += pr / 20.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless it's clearly needed.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Soften as stream progresses and bins accumulate (avoid bin explosion early).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
        // If next item is large, a fresh bin is a reasonable hedge.
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Mean-residual coupling: when open bins are on average roomy, prefer filling
    // the tightest ones (score already scales with post_residual); add small pressure.
    score += (pr - mean_residual).max(0.0) * 0.15;

    // Tie-break with a slight preference for bins with smaller residual overall.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Residuals that can't hold a mid-size item are semi-waste.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward keeping residual large enough for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize opening new bins when few bins exist,
    // reward consolidation when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 25.0 + 3.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins with below-average residual (tighter bins) for tight packing.
    score += (post_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    let tightness = (post_residual as f64) / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Lookahead: reward when next item fits the post residual exactly-ish
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if nr <= post_residual as f64 {
            let slack_after_next = post_residual as f64 - nr;
            // reward perfect chain: post_residual == next_item_size
            let chain_quality = 1.0 - (slack_after_next / bin_capacity as f64);
            score -= 20.0 * chain_quality;
        } else {
            // next item can't use this residual: penalize proportionally to wasted space
            let unusable = (nr - post_residual as f64).min(bin_capacity as f64);
            score += 8.0 * (unusable / bin_capacity as f64);
        }
    } else {
        // last item: just minimize residual
        score -= 5.0;
    }

    // Relative to mean residual: placing in below-average-residual bin is good
    score += 6.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = if next_item_size == 0 {
            false
        } else {
            fitting_bins_count == 0
        };
        let big_waste = post_residual as f64 > 0.0 && (bin_residual as f64 - item_size as f64) > 40.0;
        score += if poor_fit_elsewhere { 5.0 } else { 60.0 };
        if big_waste && !poor_fit_elsewhere {
            score += 15.0;
        }
    }

    // Late stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (best-fit core).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward near-perfect fills strongly (non-linear).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space relative to capacity, scaled by stream progress.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += waste * (30.0 + 40.0 * t);

    // Lookahead: if the next item fits the post-residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            // next item fits: residual reusability bonus, weighted by leftover after next.
            let after_next = post_residual - next_item_size;
            score -= 15.0 - (after_next as f64) * 0.2;
        } else {
            // next item cannot use this residual: mild penalty for large leftovers.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 + 20.0 * (1.0 - t);
    }

    // Global state coupling: many open bins with high mean residual -> prefer reusing bins.
    if open_bins_count > 2 {
        score -= (mean_residual - post_residual as f64).abs() * 0.3;
        score -= open_bins_count as f64 * 0.5;
    }

    // New-bin candidate handling: opening a bin is costly early and when reuse is possible.
    if bin_residual == bin_capacity {
        let reuse_pressure = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 20.0 + 30.0 * reuse_pressure + 10.0 * t;
        // Opening a new bin is attractive only if it enables a perfect pair with lookahead.
        if next_item_size > 0 && next_item_size + item_size >= bin_capacity {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth coupling: residual becomes more costly as stream progresses
    score += 6.0 * pr_norm * (1.0 + progress);

    // Penalize residuals that no typical next item could use (dead space)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 4.0 * (nx - pr) / cap * (1.0 + progress);
        } else {
            score -= 3.0 * (1.0 - (pr - nx) / cap);
        }
    } else {
        score += 2.0 * pr_norm;
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * (1.0 - pr_norm);
    }

    // Mild penalty for spreading across many open bins when residuals are large
    score += 0.3 * (open_bins_count as f64).ln() * mean_residual / cap;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: how "reusable" is the leftover space?
    // Residuals that are multiples of common item sizes (10, 20, 25, 50) stay useful.
    let residual = post_residual;
    let harmonic_bonus = if residual == 0 {
        -30.0 // perfect fit, ideal
    } else if residual % 50 == 0 {
        -12.0
    } else if residual % 25 == 0 {
        -8.0
    } else if residual % 20 == 0 {
        -7.0
    } else if residual % 10 == 0 {
        -5.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Integer-division class of residual: small leftovers are dead space.
    let dead_class = residual / 10; // 0..=10
    score += (10 - dead_class as f64) * 0.8; // penalize tiny residuals

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= residual {
            // Reward if next item would fit nicely (ideally with harmonic leftover)
            let next_post = residual - next_item_size;
            score -= 4.0 + (next_post % 10 == 0) as f64 * 3.0;
        } else {
            // Next item won't fit here: penalize slightly, more if residual is small
            score += 2.0 + (residual as f64 / bin_capacity as f64) * 4.0;
        }
    } else {
        // Last item: strongly prefer tightest fill
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: empty bin should win only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and congestion
        score += 15.0
            - (step_index as f64 / total_items.max(1) as f64) * 5.0
            - (open_bins_count as f64 * 0.3);
        // If many bins fit the item, opening a new one is wasteful
        score += fitting_bins_count as f64 * 2.0;
    } else {
        // Prefer bins whose residual is close to the item (tight fit)
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 3.0;
        // Reward using bins with below-mean residual (consolidating fragmented space)
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible next item are nearly worthless — penalize them hard.
    let min_item = 1u32;
    let usable_threshold = 12u32; // below this, a gap rarely fits anything useful
    if post_residual < usable_threshold && post_residual >= min_item {
        score += 60.0 + (usable_threshold - post_residual) as f64 * 4.0;
    } else if post_residual == 0 {
        // Perfect fit is the ideal outcome: strong reward.
        score -= 120.0;
    } else {
        // Usable gaps: reward tight fits mildly, penalize large waste gently.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * 40.0;
    }

    // If a lookahead item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack.min(30.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual cannot host the lookahead item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (8.0 + 10.0 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new one (unless it would create dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual < usable_threshold && post_residual > 0 {
            score -= 10.0; // still prefer it slightly over a fresh bin
        } else {
            score -= 50.0;
        }
    }

    // New-bin candidate: keep it neutral-ish; only attractive when all open bins
    // would produce tiny dead space or mean residual is already very low.
    if bin_residual == bin_capacity {
        let bad_open_bins = mean_residual < 12.0 && mean_residual > 0.0;
        if bad_open_bins {
            score -= 20.0; // open bins are full of dead space; fresh bin is fine
        } else {
            score += 45.0; // default: prefer filling existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match gives a strong discount; near matches decay quadratically.
        if diff == 0.0 {
            score -= 60.0 + 20.0 * (1.0 - progress);
        } else {
            score += diff * (0.5 + 0.5 * progress);
            // Penalize residuals that cannot fit the next item at all (dead space risk).
            if post_residual < next_item_size {
                score += 15.0;
            }
        }
    } else {
        // Last item: just prefer tightest fit (already via post_residual).
        score -= 5.0;
    }

    // Relative to mean residual: prefer bins whose post_residual stays near/below
    // the mean residual (keeps open bins homogeneous and packable).
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit
    // (post_residual of an empty bin after placement is large, so it is naturally
    // penalized; add extra penalty scaled by how many bins could fit).
    if bin_residual == bin_capacity {
        let fit_penalty = if fitting_bins_count == 0 { -40.0 } else { 10.0 + 8.0 * fitting_bins_count as f64 };
        score += fit_penalty;
        // Early in the stream, opening bins is cheaper.
        score -= 20.0 * (1.0 - progress);
    }

    // Small tie-breaker favoring tighter fits nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post-residual dominates).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness * (item_size as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: if the next item can also fit in the leftover space,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 6.0 + 10.0 * chain_quality;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: penalize proportionally.
        score += 4.0 * (post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (0.5 + 0.5 * progress);

    // Relative residual vs mean residual: bins with less residual than
    // average are "nearly full" — placing here is efficient.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 3.0 * (rel - 1.0);
    }

    // New-bin candidate: should only win when existing fits are terrible.
    // Penalize opening a new bin, more so early in the stream.
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * (1.0 - progress);
        // But if the item is huge relative to capacity and few bins fit it,
        // a fresh bin is a reasonable hedge.
        if item_size > bin_capacity / 2 && fitting_bins_count <= 2 {
            score -= 20.0;
        }
    }

    // Small penalty for leaving large unusable gaps (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 2.0; // tiny dead space is still mildly bad, but tight fits already rewarded
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress and item scale
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let item_frac = item_size as f64 / cap;
    let post_frac = post_residual as f64 / cap;
    let resid_frac = bin_residual as f64 / cap;

    // Tightness: reward near-perfect fits with a smooth quadratic coupling
    let tightness = 1.0 - post_frac;
    score -= 60.0 * tightness * tightness * (0.5 + item_frac);

    // Penalize unusable dead space: residuals too small for the smallest item
    let dead = (post_frac / 0.01).min(1.0);
    score += 25.0 * dead * dead;

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        let next_frac = next_item_size as f64 / cap;
        let gap = (post_frac - next_frac).abs();
        score -= 45.0 * (1.0 - gap.min(1.0)) * (1.0 - gap.min(1.0)) * (0.3 + progress);
        // Penalize if post_residual slightly larger than next item (wasted sliver)
        if post_frac >= next_frac {
            score += 10.0 * gap * gap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 30.0 * (0.5 + progress);
    }

    // Crowding pressure: with many open bins, prefer filling existing ones
    let crowd = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).powf(2.0);
    score += 15.0 * crowd * resid_frac;

    // Smooth alignment with mean residual: prefer bins near the mean (keeps spread balanced)
    let dev = ((post_residual as f64 - mean_residual).abs()) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: make empty bins less attractive unless item is huge or no good fits
    if bin_residual == bin_capacity {
        let big_item = (item_frac - 0.8).max(0.0) * 5.0;
        score += 35.0 - 40.0 * big_item * (0.5 + progress) - (fitting_bins_count as f64) * 12.0;
    }

    // Mild progress-driven urgency to close bins as stream advances
    score += 6.0 * progress * post_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) and tiny dead zones are bad,
    // residuals that pair with common small items are good.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit, always best
    } else {
        // dead space classes: residuals that few item sizes (1..=100) can use
        // residual r is usable by item sizes 1..=r => usage fraction r/100
        let usable = pr as f64 / bin_capacity as f64;
        score += (1.0 - usable) * 60.0; // penalize hard-to-fill dead space

        // harmonic mod-10 classes: residuals divisible by 10 pair with decile items
        if pr % 10 == 0 {
            score -= 8.0;
        }
        // awkward classes (1..=9 mod 10) are nearly unusable
        if pr % 10 != 0 && pr < 10 {
            score += 25.0;
        }

        // lookahead coupling: does post_residual exactly fit next item?
        if next_item_size > 0 {
            if pr == next_item_size {
                score -= 120.0;
            } else if pr >= next_item_size {
                let rem2 = pr - next_item_size;
                score -= 15.0 - (rem2 as f64) * 0.1; // reward chainable fits
                if rem2 % 10 == 0 { score -= 6.0; }
            } else {
                score += 10.0; // next item cannot use this bin's remainder
            }
        }
    }

    // last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // new-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score = 400.0 - fit_quality * 100.0;
        if fitting_bins_count <= 1 {
            score -= 150.0; // nothing else fits, new bin is fine
        }
        if post_residual > 0 && post_residual < 20 {
            score += 30.0; // opening new bin to make tiny dead space is bad
        }
    }

    // stream progression: early on, be slightly more willing to spread (open bins),
    // later, consolidate to avoid bin explosion
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.15;

    // prefer tighter bins relative to current mean residual
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.3;

    // mild penalty on very tight fits that leave 1..=5 units (unusable)
    if pr >= 1 && pr <= 5 {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest future item (min size 1, but typical items are >= 10) are
    // heavily penalized as unusable gaps.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // dead space below minimum item size
        } else if post_residual < 20 {
            score += 25.0; // near-dead space, very few items fit
        } else if post_residual < 35 {
            score += 8.0;
        }
    }

    // Reward tight fits (exact or near-exact packing).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits the post-residual, this placement
    // chains nicely; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // next item won't fit here; gap likely wasted
    }

    // Open-bin pressure: prefer consolidating into fewer bins, but when
    // this is the ONLY bin that fits, strongly favor using it.
    score += open_bins_count as f64 * 1.5;
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Slight preference for bins with below-average residual (tighter bins
    // should absorb items first, preserving roomy bins for large items).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Late in the stream, waste matters more (no future to amortize it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.2 * progress;

    // New-bin candidate: keep it moderately attractive so a fresh bin wins
    // when all open bins would leave bad dead space.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: bin residual after this item exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match lookahead reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 / (1.0 + gap);
        // Penalize residuals too small for the lookahead item (dead space).
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize leaving tiny unusable residual (waste).
    if post_residual < 10 {
        score += 30.0;
    }

    // Tight fit reward relative to item size.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: discourage unless current fit is poor or many fitting bins are wasted.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > mean_residual.max(1.0);
        if fitting_bins_count > 0 && !poor_fit {
            score += 55.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual && post_residual < item_size + next_item_size {
            score -= 20.0;
        }
    }

    // Early in stream: be slightly conservative, keep bins balanced vs mean residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 - mean_residual).abs() * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * fit_quality;

    // Lookahead: reward bins whose post_residual can host the next item,
    // penalize dead space the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 3.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 5.0 * pressure * (bin_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: bins far from the mean residual get a
    // small penalty (prefer homogeneous residual population).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: only attractive when no open bin is a decent fit
    // or the stream is early and bins are scarce.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let early = 1.0 - (step_index as f64 / total_items.max(1) as f64);
        score -= 10.0 * desperation;
        score += 4.0 * (1.0 - desperation) * (1.0 - early);
    }

    // Perfect-fill bonus.
    if post_residual == 0 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 + progress) + norm_post * (1.0 - progress) * 0.5;
    let mut score = post + 40.0 * poly;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 15.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    }

    // Penalize creating dead space that nothing typical can use
    if post > 0.0 && post < 10.0 {
        score += 12.0 * (10.0 - post) / 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild preference for consolidating into fewer bins
    score += (open_bins_count as f64) * 0.3 * norm_post;

    // Deviation from mean residual: prefer bins with residual close to item need
    score += 0.2 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: multiples of 10 are "usable" residues
    let residue_class = post_residual % 10;
    if residue_class == 0 {
        score -= 6.0; // perfectly aligned leftover, reusable by class-aligned items
    } else if residue_class <= 3 {
        score += 4.0 + residue_class as f64; // small dead-space slivers
    } else {
        score += 1.5;
    }

    // Integer-division thresholds on post_residual: big chunks are valuable
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual >= half {
        score -= 8.0;
    } else if post_residual >= quarter {
        score -= 2.0;
    } else if post_residual > 0 {
        score += 5.0; // near-empty leftover = wasted bin space
    }

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 7.0;
        // extra reward if next item exactly consumes the remainder (harmonic pairing)
        if post_residual - next_item_size < 5 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; leftover becomes dead space
        score += 3.0;
    }

    // Fraction-of-capacity coupling: penalize leaving > 40% free in an old bin
    let free_frac = post_residual as f64 / cap;
    if free_frac > 0.4 && bin_residual != bin_capacity {
        score += free_frac * 10.0;
    }

    // New-bin candidate handling: neutral-ish baseline, cheaper early in stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.55 + progress * 10.0 - (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a bin
        }
    }

    // Mild preference for fuller bins when many are open
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever be useful are heavily penalized.
    // Treat a residual as "dead" if it cannot fit even the smallest plausible item (say < 10)
    // or cannot fit the lookahead item when nothing else could.
    let dead_threshold = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 45.0 + (dead_threshold - post_residual) as f64 * 3.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Lookahead coupling: if the next item can use the leftover space, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + next_item_size as f64 * 0.3;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leftover that the next item cannot use: mild dead-space penalty scaled by tightness.
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.25;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: penalize opening a brand-new empty bin when other bins could fit,
    // unless the current bin would leave a very poor fit.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from number of open bins.
        score += 25.0 + open_bins_count as f64 * 2.5;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        if mean_residual > item_size as f64 {
            score += (mean_residual - item_size as f64) * 0.6;
        }
        // Late in the stream, avoid opening bins with big leftover potential.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    } else {
        // Reward filling an existing bin deeply; tighter fits preferred.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= fill_ratio * 15.0;
        // Prefer bins whose residual is close to the item (best-fit coupling).
        let slack = (bin_residual - item_size) as f64;
        score += slack * 0.35;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled against capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item packing
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how well next item fits into the leftover
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item can't use the leftover: dead space unless residual is tiny
            let waste = (next_item_size - post_residual) as f64;
            score += 15.0 * (waste / bin_capacity as f64).min(1.0);
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when existing bins fit well, except early stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // new-bin bias: moderate default; discouraged when good fits exist
        score += 10.0 - 5.0 * progress;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // fresh bin is a good host for the next item
        }
        if fitting_bins_count > 0 && post_residual < 30 {
            score += 25.0; // don't open new bin when an open bin stays tight
        }
    }

    // Slight penalty for leaving awkward mid-range residuals (hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 6.0; // awkward dead zone
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tight = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tight * tight;

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers are wasted capacity
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item cannot use the leftover: leftover becomes dead space
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance dynamics: if this is the only bin that fits, prefer using it
    // over opening a new bin, scaled by how full the bin already is.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 0.1 * (bin_capacity - bin_residual) as f64;
    }

    // Global state: many open bins with large mean residual -> prefer reusing
    // existing bins (consolidation); few open bins -> new bins are cheaper.
    let pressure = mean_residual / bin_capacity as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - pressure);
    score -= 5.0 * pressure;

    // Time horizon: early in the stream, be more selective (open bins freely
    // for future flexibility); late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 4.0 * progress * tight;

    // New-bin candidate: neutral-ish baseline so it only wins when open bins
    // would create significant dead space.
    if bin_residual == bin_capacity {
        score = 25.0 + 0.1 * open_bins_count as f64 - 10.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with smooth non-linear decay shaping
    let mut score = pr * (1.0 + 0.6 * pr_norm * pr_norm);

    // Progress coupling: penalize wasted space more as the stream advances
    score += 18.0 * pr_norm * pr_norm * progress;

    // Tight fit reward (smooth, non-linear)
    let tight = 1.0 - pr_norm;
    score -= 12.0 * tight * tight * tight;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Crowd penalty: many open bins with high mean residual -> prefer consolidation
    let mean_norm = mean_residual / cap;
    score += 6.0 * mean_norm * open_bins_count as f64 * (0.3 + progress);

    // Lookahead: reward leaving space usable by the next item (smooth kernel)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = pr - ns;
        let match_kernel = (-((diff / 20.0f64).powi(2))).exp();
        score -= 14.0 * match_kernel * (0.5 + 0.5 * progress);
        // Penalize leaving a residue just slightly too small for the next item
        if diff < 0.0 && diff > -ns {
            score += 8.0 * (1.0 - (diff.abs() / ns));
        }
    }

    // New-bin candidate: mildly penalize opening new bins early, less so late
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward residuals that fall into "usable" classes
    // (multiples of common small sizes 10/20/25/50), penalize odd dead space.
    let classes: [u32; 4] = [10, 20, 25, 50];
    let mut class_bonus = 0.0;
    for c in classes.iter() {
        if post_residual % c == 0 && post_residual > 0 {
            class_bonus += 6.0;
        }
    }
    score -= class_bonus;

    // Integer-division thresholds: post_residual >= 25 is still usable,
    // post_residual in 1..10 is near-dead space.
    if post_residual >= 25 {
        score -= 4.0;
    } else if post_residual > 0 {
        score += 5.0;
    } else {
        score -= 30.0; // perfect fit
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        if post_residual - next_item_size < 10 {
            score -= 6.0; // near-perfect two-item packing
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 3.0; // residual likely wasted
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Tightness ratio coupling (harmonic fraction of capacity).
    let tight = item_size as f64 / bin_residual as f64;
    if tight > 0.9 {
        score -= 10.0;
    } else if tight > 0.7 {
        score -= 4.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing open bins,
    // unless the stream is early and mean residual is very low.
    if bin_residual == bin_capacity {
        score += 12.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if mean_residual < 5.0 && open_bins_count > 0 {
            score -= 20.0; // all bins nearly full -> open new bin
        }
    }

    // Late-stream consolidation: prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in [1,9] is nearly unusable
    // (items are >= 1 but small gaps waste capacity). Penalize hard.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    } else if post_residual > 9 && post_residual <= 20 {
        // Medium gaps are partially usable; mild penalty scaled by gap smallness.
        score += 8.0 * (20.0 - post_residual as f64) / 11.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight reuse.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Lookahead: if next item fits in post_residual, this placement is doubly good.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits (small miss), mild penalty for near-dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // New-bin candidate: empty bin. Default moderately high score so open bins
    // with decent fits win, but allow opening when the only fits are terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score = bin_capacity as f64 * 0.55;
        // Large items or many open bins make new bins more attractive.
        score -= item_size as f64 * 0.15;
        score += open_bins_count as f64 * 1.5;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
        // Late in stream, prefer consolidating.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 8.0;
    }

    // Slight nudge toward bins below mean residual (balance the pool).
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is gold.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 120.0;
    }

    // Dead space penalty: residuals that can likely never be reused
    // (typical item sizes 10..80; residuals < 10 are pure waste).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 500.0;
        } else if gap <= 5 {
            score -= 200.0;
        } else if gap <= 10 {
            score -= 80.0;
        } else {
            score += gap as f64 * 0.5;
        }
        // If next item cannot fit post_residual, mildly penalize unless post_residual is tiny.
        if post_residual < next_item_size && post_residual >= 10 {
            score += 40.0;
        }
    }

    // Last-chance bin: only this bin can fit the item; strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    // (best-fit style), penalize dumping into already-loose bins.
    score -= (mean_residual - post_residual as f64) * 2.0;

    // New-bin candidate: allow opening a fresh bin when the current fit is poor
    // (large post_residual), but not when it's a good fit.
    if bin_residual == bin_capacity {
        if post_residual > 30 && next_item_size > 0 && post_residual < next_item_size {
            score -= 350.0; // fresh bin preserves space for next item
        } else if post_residual > 50 {
            score -= 100.0;
        } else {
            score += 250.0; // prefer filling existing bins on good fits
        }
    }

    // Slight preference for compacting many open bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Penalize leaving dead space that cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward residual that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strong incentive to use it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, mildly prefer fuller bins.
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Penalize new-bin candidate (bin_residual == bin_capacity) unless fit is poor elsewhere.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in the stream, new bins are cheaper; late, conserve.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // If many open bins already, discourage opening yet another.
        score += open_bins_count as f64 * 1.5;
    }

    // Prefer bins that are already below-average residual (relatively full).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild penalty for very small leftovers that waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: minimize leftover space after placement.
    let mut score = post;

    // Non-linear coupling: squared normalized waste, amplified as stream progresses
    // (dead space is costlier later when consolidation matters).
    let waste_frac = post / cap;
    score += waste_frac * waste_frac * cap * (0.4 + 1.6 * progress * progress);

    // Reward tight fits (small post_residual relative to item) with smooth saturation.
    let tightness = 1.0 - (post / cap).min(1.0);
    score -= tightness * tightness * (item_size as f64) * 0.9;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else {
        // Mild penalty spread over many fitting bins to encourage filling scarce bins.
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Penalize bins far below the mean residual (they are "fresher" and more flexible);
    // smooth quadratic coupling with mean residual.
    let dev = mean_residual - post;
    if dev > 0.0 {
        score += (dev / cap) * (dev / cap) * cap * 0.5;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item is large
    // relative to capacity (poor fit elsewhere) or stream is early and flexibility helps.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        let size_frac = item_size as f64 / cap;
        let openness = 1.0 - progress;
        score += 18.0 * (1.0 - size_frac) * (0.35 + 0.65 * (1.0 - openness));
        // Slight discount if next item is large and would also fit a fresh bin well.
        if next_item_size > 0 {
            let next_frac = next_item_size as f64 / cap;
            score -= (next_frac * next_frac) * 8.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Smooth penalty if next item nearly fits but not quite (near-miss waste).
        let gap = (next_item_size as f64 - post).abs();
        if next_item_size as f64 > post && gap < 10.0 {
            score += gap * 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer-division thresholds (capacity fractions)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let cls = post_residual / 20; // 5 harmonic classes: 0..19,20..39,40..59,60..79,80..99

    // Reward large post_residual classes (usable space), non-linearly
    score -= (cls as f64) * (cls as f64) * 0.9;

    // Perfect/near-perfect fits get strong bonus
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Penalize awkward dead space: post_residual in (10, 20) is hard to fill
    if post_residual > 10 && post_residual < 20 {
        score += 40.0;
    }
    if post_residual > 30 && post_residual < 40 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item fits: residual class compatibility via modulo
            let m = post_residual % next_item_size.max(1);
            if m == 0 {
                score -= 120.0;
            } else {
                score -= (post_residual.min(next_item_size * 2) as f64) * 0.5;
            }
        } else {
            // next item won't fit here: penalize small residuals that strand the next item
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // New-bin candidate handling: only attractive late or when open bins are poor fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let waste = (mean_residual - item_size as f64).max(0.0);
        score = cap - pr + 60.0 + waste * 0.3 - progress * 40.0;
        if fitting_bins_count == 1 {
            score += 200.0; // opening a new bin when a usable bin exists is bad
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.15;

    // Prefer tighter bins (small residual before placement)
    score += (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit is highly desirable
    }

    // Reward tight fits relative to item size.
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Open-bin pressure: discourage spreading across too many bins,
    // but allow opening a new bin when current bins fit poorly.
    let pressure = open_bins_count as f64;
    score += pressure * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    }
    // If next item cannot fit the leftover, penalize large wasted residuals.
    if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 && post_residual > 0 {
        score += (post_residual as f64) * 0.5;
    }

    // New-bin candidate: make it attractive only when existing bins are crowded
    // or the fit here is bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0));
        if mean_residual < item_size as f64 {
            score -= 12.0; // existing bins are tight -> open new bin
        }
    }

    // Mild stream-progression coupling: later in stream, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // tighter chain fit => better
        score -= 40.0 - slack.min(40.0);
        // if next item then exactly fills the bin, extra bonus
        if post_residual == next_item_size {
            score -= 300.0;
        }
    } else if next_item_size > 0 {
        // post_residual too small for next item: penalize dead space unless it's tiny
        let dead = post_residual as f64;
        if dead > 0.0 && dead < next_item_size as f64 {
            score += 0.8 * (next_item_size as f64 - dead);
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize new-bin candidate unless current bins have poor residuals
    if bin_residual == bin_capacity {
        // new bin baseline: neutral-ish, penalized so it's used only when needed
        score += 150.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
        // open a new bin when existing bins are already tight
        if mean_residual < 25.0 {
            score -= 100.0;
        }
    }

    // Prefer filling bins below mean residual (concentrate waste)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot hold even the smallest plausible item,
    // scaled by how "wasted" the leftover is relative to the item itself.
    if post_residual < item_size {
        score += 8.0 * (item_size - post_residual) as f64 / item_size as f64;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (perfect pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // partial reward proportional to how well next item nests
            let nest = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * nest;
        } else {
            // next item would not fit here; slight penalty scaled by overflow
            let overflow = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 5.0 * overflow;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // mild penalty to spread load when many options exist
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global state: many open bins with high mean residual -> prefer reusing
    // existing capacity rather than fragmenting.
    score += 0.02 * (open_bins_count as f64);
    score -= 0.03 * mean_residual;

    // Time horizon: early in the stream, be more conservative about creating
    // dead space; late in the stream, prioritize immediate tightness.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.015 * post_residual as f64;
    score -= progress * 4.0 * tightness;

    // New-bin candidate: an empty bin has full residual; make it moderately
    // attractive only when the fit is very poor elsewhere — approximate via
    // comparing post_residual to item_size. Empty bin gets a neutral-ish
    // baseline with a small exploration bonus early on.
    if bin_residual == bin_capacity {
        let exploration = 1.0 - progress;
        score -= 6.0 * exploration;
        // discourage opening new bins when many are already open
        score += 0.05 * open_bins_count as f64;
    }

    // Small stochastic-free tie-break via residual parity coupling to step
    score += ((step_index as f64 * 0.6180339887 + post_residual as f64 * 0.3141) % 1.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 12.0 * poly;
    // Penalize large dead space late in the stream more strongly
    score += 20.0 * norm_pr * norm_pr * norm_pr * progress;
    // Reward tight fits (small post residual) more when few bins fit the item
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_pr);
    }
    // Lookahead: favor bins whose post residual can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - pr / (next_item_size as f64 + 1.0));
    }
    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual - pr).abs() / cap;
    // New-bin candidate: make it attractive only when existing fits are poor
    if bin_residual == bin_capacity {
        let poor = (pr / cap) - 1.0; // zero for new bin; used for smoothness
        score -= 6.0 * (1.0 - progress) * (1.0 + poor.abs());
        score += 10.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: exact divisions of capacity are
    // "reusable" classes (residuals like 0, 10, 20, 25, 50 are valuable).
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit: always best
    } else {
        // reward residuals that divide capacity evenly (harmonic classes)
        let mut bonus = 0.0;
        if bin_capacity % pr == 0 { bonus += 40.0; }
        if pr % 10 == 0 { bonus += 25.0; }
        if pr % 5 == 0 { bonus += 10.0; }
        // small leftovers are dead space: penalize the smallest classes hardest
        if pr < 10 { bonus -= 60.0; }
        else if pr < 20 { bonus -= 25.0; }
        score -= bonus;

        // look-ahead coupling: if next item fits exactly in post_residual,
        // strongly favor this bin (chain harmonic classes)
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 120.0;
            } else if next_item_size < pr && (pr - next_item_size) % 10 == 0 {
                score -= 45.0;
            } else if next_item_size > pr {
                score += 15.0; // next item won't fit here anyway
            }
        }
    }

    // last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // new-bin candidate: neutral baseline, slightly worse than good fits
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
    }

    // late in the stream, tighten packing (waste matters more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += score * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is too small to fit the smallest plausible item (1..100 range).
    // Treat gaps <= 15 as near-dead (below the typical minimum item of 10 with margin),
    // and gaps in (0, 30) as risky partial dead space.
    let gap = post_residual as f64;
    if gap > 0.0 {
        if gap <= 15.0 {
            // Complete dead space: waste of bin_capacity fraction.
            score += 60.0 * (1.0 - gap / 15.0);
        } else if gap < 30.0 {
            // Risky gap: unlikely to fit a future item well.
            score += 20.0 * (1.0 - (gap - 15.0) / 15.0);
        }
    }

    // Perfect fit reward: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits relative to item size: post_residual small compared to item.
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score += 10.0 * fit_ratio.min(3.0);

    // Open bins pressure: penalize spreading across many bins when residuals are large;
    // encourage closing out bins with small residuals by selecting them.
    score += 2.0 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin (which would strand the current residual).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin should only win when this bin's
    // post-fit residual would be dead space AND other options are poor.
    if bin_residual == bin_capacity {
        // Brand-new empty bin: neutral baseline plus a mild conservatism term that grows
        // with stream progression (prefer consolidating early, fresh bins late).
        score += 40.0 + 20.0 * (step_index as f64 / (total_items.max(1) as f64));
        // If the current item fits tightly in a fresh bin, make it attractive.
        if item_size >= bin_capacity.saturating_sub(15) {
            score -= 90.0;
        }
    }

    // Lookahead coupling: if the next item would fit exactly in the post residual,
    // reward this placement strongly (chain fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot fit here afterwards: mild penalty proportional to wasted opportunity.
        score += 8.0;
    }

    // Mean residual coupling: bins deviating far below mean residual are already tight;
    // placing there when it yields large post residual is bad.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.5 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: minimize wasted space relative to item size
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio;

    // Perfect match with next item: post_residual exactly equals next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Bonus when post_residual can still hold next item
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            // penalize dead space too small for typical items
            if post_residual < 10 {
                score += 25.0;
            }
        }
    }

    // Relative to mean residual: prefer bins with less residual (fuller bins)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 50.0;
        // allow new bin if current bin fit is very poor
        if fit_ratio < 0.5 {
            score -= 20.0;
        }
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score -= 3.0; // small-but-usable
    }

    // Lookahead: bonus if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect chain
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 4.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin gets a mild penalty so it's chosen
    // only when no open bin offers a decent fit.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + mean_residual * 0.15;
        // Late in the stream, opening new bins is more acceptable (less waste risk).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
    }

    // Prefer bins whose residual is close to the global mean (keeps balance),
    // scaled by how many bins are open.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * deviation * (open_bins_count as f64).sqrt();

    // Mild time-horizon shaping: early on, be conservative (favor tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress (smooth, in [0,1])
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized fill level of this bin before placement
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);

    // Non-linear coupling: tight fits are rewarded super-linearly,
    // more so as the stream progresses (closing bins early matters later).
    let tightness = (post_residual as f64 / bin_capacity as f64).powf(1.5 + progress);
    score += tightness * 30.0 * (0.5 + progress);

    // Reward using nearly-full bins (high fill) with a smooth quadratic term
    score -= fill * fill * (10.0 + 15.0 * progress);

    // Dead-space penalty: post_residual that is too small for typical future
    // items is worthless; smooth sigmoid-like decay on usable residual.
    let usable = (post_residual as f64 / 50.0).tanh();
    score -= usable * 8.0;

    // Last-chance bin: strongly favor it to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead (k=2): if the next item fits exactly in the post residual,
    // reward; if it would be blocked, penalize smoothly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next - post_residual as f64).abs() < 1.0 {
            score -= 20.0; // perfect pair fit
        } else if next > post_residual as f64 {
            let blocked = ((next - post_residual as f64) / bin_capacity as f64).powf(2.0);
            score += blocked * 15.0 * (1.0 - progress);
        } else {
            // next item still fits: mild reward proportional to remaining slack use
            score -= ((post_residual as f64 - next) / bin_capacity as f64) * 5.0;
        }
    }

    // Mean-residual coupling: when the fleet average residual is large,
    // discourage fragmenting yet another bin (prefer consolidation).
    let mean_norm = mean_residual / bin_capacity as f64;
    score += mean_norm * (post_residual as f64 / bin_capacity as f64) * 12.0;

    // New-bin candidate handling: opening a fresh bin is only attractive
    // early in the stream or when no open bin fits well.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let poor_alternatives = (fitting_bins_count == 0) as i32 as f64;
        let early = (1.0 - progress).powf(2.0);
        score = 60.0 - poor_alternatives * 40.0 - early * 10.0
            + (mean_residual / bin_capacity as f64) * 20.0;
    }

    // Small smooth open-bin pressure: many open bins -> prefer filling existing ones
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division thresholds.
    // Waste classes: 0 (perfect), <=10 (excellent), <=25 (good), <=50 (marginal), >50 (dead).
    let waste_class: f64 = match post_residual {
        0 => -60.0,
        1..=10 => -30.0,
        11..=25 => -10.0,
        26..=50 => 10.0,
        _ => 35.0,
    };
    score += waste_class;

    // Modulo-arithmetic coupling: residuals that are multiples of small
    // harmonics (4, 8, 16) remain divisible by more future item sizes.
    if post_residual > 0 && (post_residual % 4 == 0) {
        score -= 6.0;
        if post_residual % 8 == 0 {
            score -= 4.0;
            if post_residual % 16 == 0 {
                score -= 3.0;
            }
        }
    }

    // Lookahead: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chain placement
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // reward tight follow-ups, penalize large leftover after chain
            score -= 20.0 * (1.0 - gap / cap);
            if gap > 50.0 {
                score += 12.0;
            }
        } else {
            // next item cannot follow into this bin: leftover is likelier dead
            score += 8.0;
        }
    } else {
        // last item: only the residual matters, reward tight fits strongly
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current fits are poor (large post_residual here)
    // or when many bins are already open with high mean residual.
    if bin_residual == bin_capacity {
        score = cap * 0.6 + 0.5 * mean_residual + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0; // keep pairing freedom
        }
        if fitting_bins_count <= 2 && post_residual as f64 >= 40.0 {
            score -= 25.0; // no good open bin: open a fresh one
        }
    }

    // Progress-aware tightness bonus: later in the stream, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 15.0 * (1.0 - post_residual as f64 / cap);

    // Mild penalty when this bin's residual deviates far from the mean
    // (keeps residual distribution balanced for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // New bin candidate: penalize slightly unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 5.0 + mean_residual * 0.1;
    }

    // Late in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward post_residual matching next_item_size exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect match for the next item -> strong bonus.
        score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Penalize leaving post_residual slightly below next_item_size (dead space).
        if post_residual < next_item_size {
            score += 8.0;
        }
    } else if next_item_size > 0 {
        // post_residual can't fit next item: penalize proportionally to wasted space.
        let waste = post_residual as f64;
        score += 2.0 * (waste / bin_capacity as f64);
    }

    // Relative-to-mean coupling: bins with residual far from mean are treated specially.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly; it wins only if open bins score badly.
        score += 15.0 + 0.5 * (item_size as f64);
        // Early in stream, keep bins consolidated.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Encourage filling nearly-full bins completely.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where item fills most of residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: reward if next item can fit into the post residual.
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 25.0;
            // bonus if post residual is a near-exact match for next item
            let gap = post_residual as f64 - next_item_size as f64;
            if gap < 5.0 { score -= 15.0; }
        } else {
            // next item won't fit here; mild penalty for wasting residual
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when fits are poor or stream is early.
    if bin_residual == bin_capacity {
        let pressure = fitting_bins_count as f64;
        // If few alternatives exist, opening a new bin is fine; otherwise penalize.
        score += 30.0 + 10.0 * pressure.min(5.0);
        // Early in stream, new bins are cheaper; late in stream, consolidate.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - t);
        // If mean residual across open bins is large, we should use existing space.
        if mean_residual > item_size as f64 * 1.3 {
            score += 20.0;
        }
    }

    // Mild preference for bins below mean residual (balancing load).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Slight bonus for using many open bins when there are many (avoid fragmentation).
    if open_bins_count > 20 {
        score -= 0.02 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate leftover space; late, penalize it more aggressively
    let coupling = norm_pr * (1.0 - norm_pr);
    score += 40.0 * coupling * (0.25 + progress);

    // Tight fit reward (small post residual relative to item)
    let tightness = 1.0 - (pr / (item_size as f64 + 1.0));
    score -= 8.0 * tightness.max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 10.0 * (1.0 - (next_item_size as f64 / pr));
    } else if next_item_size > 0 {
        // next item won't fit: penalize dead space proportionally
        score += 4.0 * norm_pr * (1.0 - progress);
    }

    // Prefer bins with below-mean residual (concentrate waste)
    score += 3.0 * ((pr - mean_residual) / cap).max(-1.0).min(1.0);

    // Slight preference for fewer open bins early, more consolidation late
    score += 0.5 * (open_bins_count as f64) * (1.0 - progress) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on "useful"
    // residue classes (multiples of small item sizes) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty grows super-linearly for small unusable leftovers.
    if post_residual > 0 {
        let dead = (post / cap).powf(2.0) * 40.0;
        score += dead;
    } else {
        // Perfect fit is ideal.
        score -= 25.0;
    }

    // Modulo arithmetic on post_residual: leftovers divisible by common
    // item granularities (e.g. 10, 20, 25) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 6.0; }
        if pr % 20 == 0 { bonus += 4.0; }
        if pr % 25 == 0 { bonus += 4.0; }
        if pr % 50 == 0 { bonus += 3.0; }
        score -= bonus;
    } else {
        score -= 8.0; // exact fill
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let npost = post_residual - next_item_size;
            if npost % 10 == 0 { score -= 5.0; }
            score -= (npost as f64 / cap) * 10.0;
        } else {
            // next item cannot use this leftover: leftover is likely dead
            score += (post_residual as f64 / cap) * 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // mostly full / few fitting options. Empty-bin call has residual==capacity.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { fitting_bins_count as f64 };
        let fullness = 1.0 - (mean_residual / cap);
        // Opening new bin is penalized more when existing bins are well used
        // and there are alternatives; rewarded when stream is early or bins full.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + pressure * 4.0 + fullness * 10.0 - progress * 5.0;
    }

    // Mild preference for tighter bins overall (low residual relative to mean).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    let dead_threshold: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual >= 10 {
        // Usable gap: mild reward proportional to future usability.
        score -= 4.0;
    }

    // Open-bins pressure: prefer consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual blocks the next item: penalize.
        score += 15.0;
    }

    // Mean-residual coupling: if this bin is unusually full vs mean, slight reward.
    score += (mean_residual - bin_residual as f64) * 0.2;

    // New-bin candidate handling: only attractive early in the stream or when
    // all open bins would create dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + progress * 40.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect two-item packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Partial credit for near matches with the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if gap < 10 {
            score -= (10 - gap) as f64 * 2.0;
        }
        // Penalize leaving dead space that cannot fit the next item.
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0;
        }
    }

    // Penalize small unusable residuals (dead space) more than linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Compare against mean residual: bins already tighter than average are
    // good candidates; loose bins should be kept loose.
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer keeping the number of open bins modest early in the stream;
    // later, tightness matters more than bin count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (open_bins_count as f64) * (1.0 - progress) * 0.5;

    // Slight preference for filling bins tightly relative to capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 8.0 * tightness * (item_size as f64);

    // Penalize large dead space that nothing can use (post_residual too small for future items).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: if the next item fits into the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.25 * next_item_size as f64;
        } else {
            // Wasted potential: post residual too small for the known next item.
            score += 0.10 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins with residual far from mean residual (diversity of bin states).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, be more willing to open new bins
    // (preserve flexibility); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // New-bin candidate handling: an empty bin is attractive when the item fits poorly
    // in existing bins or when many bins are congested.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_capacity as f64 - item_size as f64) / bin_capacity as f64;
        let congestion = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        score = 25.0 - 20.0 * congestion - 10.0 * poor_fit;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        if fitting_bins_count <= 1 {
            score += 50.0; // don't open a new bin when this is the last resort elsewhere
        }
    }

    // Mild penalty for accumulating too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * progress;
    score += 20.0 * poly;

    // Penalize dead space more as stream progresses (less time to reuse it)
    score += 15.0 * norm_pr * norm_pr * progress;

    // Reward tight fits (small post_residual) with smooth reward
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward leaving space for the next item (smooth interaction)
    let ni = next_item_size as f64;
    if ni > 0.0 {
        let fit_next = (pr >= ni) as i32 as f64;
        let slack = (pr - ni).max(0.0) / cap;
        score -= 8.0 * fit_next * (0.5 + slack);
        score += 6.0 * (1.0 - fit_next) * progress;
    }

    // Mild penalty for spreading across many bins when mean residual is high
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap) * progress;

    // New-bin candidate: make it attractive only when it beats poor fits
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot family" it belongs to.
    // Residuals in {0} are perfect; small residuals (1..10) are near-dead space;
    // mid residuals (10..25) are still usable for typical items.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: strongly reward
    } else if pr < 10 {
        // dead-space penalty grows as residual shrinks (unusable gap)
        score += (10 - pr) as f64 * 4.0;
    } else {
        // Harmonic bucket: classify by integer division on post_residual
        let bucket = pr / 20; // 0: 10..19, 1: 20..39, 2: 40..59, 3+: 60+
        score -= bucket as f64 * 6.0;
    }

    // Modulo-10 harmonic alignment: residuals that are multiples of 10 pair
    // nicely with items on a 10-grid; reward clean alignment.
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    } else if pr % 10 != 0 {
        score += (pr % 10) as f64 * 0.5;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let nr = pr - next_item_size;
            score -= (20.0 - (nr as f64).min(20.0)) * 0.8;
        } else {
            // next item won't fit here; slight penalty scaled by overflow gap
            let gap = next_item_size - pr;
            score += (gap as f64).min(30.0) * 0.6;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing residuals are large/fragmented or many bins are open.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if fitting_bins_count == 0 {
            score -= 25.0; // nothing fits: must open
        } else if open_bins_count > 6 && mean_residual > 40.0 {
            score -= 12.0; // fragmented state: fresh bin helps
        } else {
            score += 40.0 + fragmentation * 0.3; // default: prefer reusing bins
        }
    }

    // Mild stream-position term: late in the stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Tie-break toward fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize large post-residuals if nothing plausible fits them later.
    if post_residual > 0 && post_residual < next_item_size as f64 {
        score += 12.0;
    } else if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.15 + 0.25 * progress);
    score += bin_pressure * 0.5;

    // New-bin candidate: penalize mildly, but allow opening when open bins are fragmented.
    if bin_residual == bin_capacity {
        score += 8.0 + bin_pressure * 0.4;
        if mean_residual < 10.0 && open_bins_count > 2 {
            score -= 25.0; // fragmentation: fresh bin is better than forcing a bad fit
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 2.5 * diff.recip().max(0.0) * 0.0; // placeholder no-op
        // Perfect match bonus: strong subtraction when post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            // graded penalty: closeness of post_residual to next item is rewarded
            let closeness = 1.0 / (1.0 + diff / 10.0);
            score -= 40.0 * closeness;
            // penalize post_residual that is too small for the next item (dead space)
            if post_residual < next_item_size {
                score += 0.5 * diff;
            }
        }
    }

    // Relative-to-mean coupling: bins tighter than average are good targets.
    let rel = mean_residual - post_residual as f64;
    score += 0.3 * rel;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing else is decent.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * item_size as f64;
    }

    // Small late-stream tightening: prefer filling bins more fully as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // a "useless threshold" should be penalized extra.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 3.0 * (dead_threshold - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward heavily; if next item barely misses, penalize slightly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - (pr - nxt) / bin_capacity as f64);
        } else {
            score += 0.15 * (nxt - pr);
        }
    }

    // Time horizon: late in the stream, be conservative — prefer filling
    // existing bins; early, allow spreading to keep flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let spread_penalty = (1.0 - progress) * 6.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += spread_penalty * (1.0 + progress);
        // But if no open bin fits well (large post_residual everywhere),
        // opening a new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 12.0;
        }
    } else {
        // Reward using bins with residuals near mean (balanced usage),
        // penalize using bins far below mean (hoarding big space).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev * progress;
        // Prefer fuller bins later in the stream.
        score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 10.0 * progress;
    }

    // Mild penalty for accumulating many open bins early (fragmentation risk).
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    // Item-size interaction: large items should go into large-residual bins.
    let large = item_size as f64 > 0.5 * bin_capacity as f64;
    if large {
        score -= 0.2 * (bin_residual as f64 - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr) - 0.35 * (norm_pr * norm_pr) * (1.0 - progress);

    // Reward tight fits smoothly
    score -= 12.0 * (1.0 - norm_pr).powi(3);

    // Penalize waste relative to mean residual state
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: favor bins whose post-residual can host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (next_item_size as f64 / cap);
    }

    // Mild pressure against proliferating bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: residual modulo 10 — small "dead" remainders are worse.
    let rmod = (post_residual % 10) as f64;
    score += rmod * 0.8;

    // Fraction of capacity wasted
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 40.0;

    // Prefer bins whose residual is divisible by common item classes (10/20/25/50)
    if post_residual % 50 == 0 { score -= 30.0; }
    if post_residual % 25 == 0 { score -= 15.0; }
    if post_residual % 20 == 0 { score -= 10.0; }

    // Lookahead coupling: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // dead space relative to next item
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Penalize spreading across too many bins with large mean residual
    score += (mean_residual - frac * bin_capacity as f64) * 0.05;

    // New-bin candidate: only attractive when item is large or nothing fits well
    if bin_residual == bin_capacity {
        let tight = if next_item_size > 0 { item_size + next_item_size <= bin_capacity } else { false };
        if tight || fitting_bins_count == 0 {
            score -= 45.0;
        } else {
            score += 80.0;
        }
    }

    // Mild stream progression term: tighten packing later in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead space relative to capacity.
    let dead_ratio = post_residual as f64 / bin_capacity as f64;
    score += dead_ratio * 20.0;

    // Open bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // next item cannot use the leftover gap
    }

    // New-bin candidate: prefer opening a new bin only when it avoids bad dead space
    // or when current bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (mean_residual.max(1.0) / 10.0);
        if post_residual < 20 && fitting_bins_count > 0 {
            score -= 5.0; // opening fresh bin better than tiny dead space
        } else {
            score += 10.0 + pressure.min(20.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-match: reward closeness of post_residual to next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        // If next item can still fit here afterwards, bonus
        if next_item_size <= post_residual {
            score -= 25.0;
        }
    }

    // Penalize dead space that no realistic item (>=1) can use efficiently:
    // small post_residual that doesn't match next item is wasted capacity
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize leaving large residuals relative to capacity when many bins open
    if open_bins_count > 1 {
        score += 0.1 * (post_residual as f64 - bin_capacity as f64 / open_bins_count as f64).abs();
    }

    // Late in the stream, be more conservative: avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses, unless current
        // post_residual would be a terrible fit elsewhere
        score += 80.0 + 60.0 * progress;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 70.0; // fresh bin fits both current and next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: heavily discount when post_residual is small
    let tight_fit_bonus = (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * bin_capacity as f64);
    score -= 30.0 * tight_fit_bonus;

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits perfectly in post_residual, reward strongly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tightness = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 20.0 * next_tightness;
        } else {
            // Next item won't fit here after placing current item; slight penalty if we waste space
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else {
            let best_gap = (bin_residual as f64 - item_size as f64).abs();
            best_gap / bin_capacity as f64
        };
        // Prefer new bin when item is large and fits are poor, more so late in stream
        score += 60.0 - 50.0 * poor_fit - 15.0 * progress;
    }

    // Global state coupling: many open bins with high mean residual -> prefer reusing bins
    let mean_res_norm = mean_residual / bin_capacity as f64;
    score -= 8.0 * mean_res_norm;
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - mean_res_norm);

    // Time horizon: early in stream, be more conservative (favor new bins for flexibility);
    // late in stream, pack tightly into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize leaving residual that matches neither common item sizes nor zero
    if post_residual > 0 && post_residual < item_size {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // base: minimize wasted space, with non-linear penalty on small residuals
    let mut score = pr as f64;

    // non-linear coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly (small post_residual favored more);
    // late, waste is costlier so amplify penalty on large residuals.
    let progress_coupling = (x * x) * (1.0 + 3.0 * progress) - (x * x * x) * (0.5 + 2.0 * progress);
    score += 40.0 * progress_coupling;

    // last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // lookahead: reward leaving space usable by the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_quality = 1.0 - ((pr - nxt) / cap).abs();
            score -= 10.0 * fit_quality * (0.5 + progress);
        } else {
            // post residual too small for next item: penalize dead space
            score += 8.0 * (1.0 - pr / nxt.max(1.0)) * (0.5 + progress);
        }
    }

    // mild penalty for spreading across many open bins vs consolidating
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // deviation from mean residual: prefer bins near the mean (balanced packing)
    score += 3.0 * (pr - mean_residual).abs() / cap;

    // new-bin candidate: penalize slightly so it only wins when open bins are bad fits
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "dead space quality".
    // Residues near 0 are reusable by typical small items; residues in 1..9 are awkward.
    let r = (post_residual % 10) as f64;
    let awkward = if r == 0.0 { 0.0 } else { (10.0 - r) / 10.0 };
    score += awkward * 4.0;

    // Reward near-perfect fits heavily (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // Lookahead: does next_item_size fit into post_residual? Reward harmonic alignment.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: bonus scaled by how well next item's residue matches too.
            let nr = (post_residual - next_item_size) % 10;
            let chain_quality = if nr == 0 { 1.0 } else { (nr as f64) / 10.0 };
            score -= 12.0 + 8.0 * chain_quality;
        } else {
            // Next item won't chain here; penalize proportionally to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // Mild penalty when many bins compete: prefer concentrating load.
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Capacity fraction thresholds via integer division on post_residual.
    // Post-residual in [0,10): excellent; [10,25): good; [25,50): mediocre; else poor.
    let band = post_residual / 25;
    score += match band {
        0 => -6.0,
        1 => 0.0,
        2 => 5.0,
        _ => 9.0,
    };

    // New-bin candidate handling: empty bin should only win when current bin is a bad host.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream or when few bins open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_cost = 22.0 - 8.0 * progress;
        // If mean residual is large, open bins are fragmented; new bin is more acceptable.
        new_bin_cost -= (mean_residual / 10.0).min(6.0);
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size > 50 {
            new_bin_cost -= 4.0;
        }
        score += new_bin_cost.max(0.0);
    }

    // Prefer bins whose residual is close to the item (minimal waste) via harmonic ratio.
    if bin_residual > 0 {
        let ratio = item_size as f64 / bin_residual as f64;
        score += (1.0 - ratio) * 6.0;
    }

    // Small global regularization to break ties deterministically.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are effectively perfect; residuals in the "unusable small gap" zone
    // (just above the smallest plausible item) are heavily penalized.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else if post_residual < 10 {
        score -= 40.0; // near-perfect, unusable gap = good
    } else if post_residual <= 20 {
        score += 25.0; // small dead space: hard to fill later
    } else if post_residual <= 35 {
        score += 10.0; // moderately awkward gap
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Open-bin pressure: discourage spreading across many bins when a
    // reasonable fit exists; encourage consolidation.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive if current item leaves a
    // large residual in existing bins or no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0 + 3.0 * open_bins_count as f64;
        // If next item is large, a fresh bin may be worthwhile.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 25.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Lookahead: if the post-residual exactly accommodates the next item,
    // this placement sets up a perfect follow-up fit.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0;
        }
        // Avoid leaving a gap that just barely fails the next item.
        if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 5.0;
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is
    // already small (consolidation into nearly-full bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 / (1.0 + gap);
        // Exact match bonus: next item will perfectly fill this bin.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Two-item chain: current item + next item exactly fill the bin.
        if item_size + next_item_size == bin_residual {
            score -= 20.0;
        }
        // Penalize post_residual that is unusably small for the next item.
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 5.0;
    }

    // Reward fills relative to capacity (dead-space penalty).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio;

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.10 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 18.0;
        score -= 6.0 * crowding;
        // If next item is large and won't fit in a fresh bin after this item, discourage.
        if next_item_size > 0 && next_item_size > post_residual {
            score += 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Late-stream consolidation: prefer using existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit preference: squared waste penalty
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64 * 2.0);

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead (k=2): reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 - slack * 0.25; // prefer snug chains
        } else {
            // leftover too small for next item: penalize proportionally to waste
            score += (post_residual as f64) * 0.6;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize dumping into bins with already-low residual when many alternatives exist
    if fitting_bins_count > 1 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio < 0.5 {
            score += 10.0 * (1.0 - fill_ratio);
        }
    }

    // Global state: when mean residual is high, prefer consolidating into fuller bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * (0.15 + 0.25 * progress);

    // New-bin candidate logic: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let open_pressure = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).ln() * 8.0 };
        let tight_exists = fitting_bins_count > 0 && post_residual <= 15;
        score += 55.0 + open_pressure;
        if tight_exists { score += 30.0; }
        // late in stream, opening bins is cheaper than scattering
        if progress > 0.7 && fitting_bins_count > 0 { score += 10.0; }
    }

    // Mild preference for bins already partially loaded when few bins open
    if open_bins_count <= 3 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Fragmentation guard: avoid leaving residuals in the awkward 11..25 band
    if post_residual > 10 && post_residual < 25 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress.
    // Squared/cubic terms in post_residual penalize large dead space super-linearly.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Quadratic + cubic dead-space penalty, amplified as the stream progresses.
    let quad = pr_norm * pr_norm;
    let cubic = quad * pr_norm;
    score += (1.0 + 2.0 * progress) * (3.0 * quad + 5.0 * cubic) * cap * 0.1;

    // Smooth interaction: tight fits (small post_residual) get a bonus that grows
    // with progress, encouraging consolidation late in the stream.
    let tightness = 1.0 - pr_norm;
    score -= (progress * tightness * tightness) * cap * 0.5;

    // Penalize bins whose residual deviates from the mean residual when this bin
    // is one of many candidates (non-linear variance-like coupling).
    let dev = (pr - mean_residual) / cap;
    score += dev.abs() * dev.abs() * cap * (1.0 + progress) * 2.0;

    // Last-chance bin: strongly reward using it to avoid opening a new bin,
    // with a smooth saturating reward scaled by how well the item fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 20.0 + 30.0 * fit_ratio * (1.0 + progress);
    }

    // New-bin candidate handling: opening a new bin is attractive early (spread load)
    // and when the item would leave a large awkward residual in an existing bin.
    if bin_residual == bin_capacity {
        // Smooth attractiveness of a fresh bin: decreases with progress,
        // increases with the awkwardness (cubic dead space) of existing fits.
        let awkwardness = cubic * cap * 0.1;
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = 40.0 + progress * 60.0 - awkwardness * 4.0 - open_pressure * 2.0;

        // Lookahead: if the next item is large, a fresh bin is less attractive
        // unless the current fit is already very tight elsewhere.
        if next_item_size > 0 {
            let next_ratio = next_item_size as f64 / cap;
            score += next_ratio * 25.0 * (1.0 - progress);
        }
        // Late in the stream, prefer closing out existing bins rather than opening.
        score += progress * progress * 30.0;
    }

    // Mild reward for bins that can also fit the lookahead item afterwards
    // (smooth interaction term with post_residual).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / cap) * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fraction bands.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits: post_residual in small harmonic class (0..10, 10..20, 25, 50)
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    } else if post_residual <= 20 {
        score -= 40.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item
    // sizes (10, 25, 50) are more likely to be filled later.
    if post_residual % 10 == 0 {
        score -= 15.0;
    }
    if post_residual % 25 == 0 {
        score -= 10.0;
    }
    if post_residual % 50 == 0 {
        score -= 10.0;
    }

    // Integer-division thresholds: post_residual / next_item_size == 1 means
    // the next item exactly fills the leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 60.0; // next item can perfectly consume remainder
        } else {
            score -= 20.0; // next item fits with some waste
        }
    } else if next_item_size > 0 {
        // next item cannot fit here: dead-space penalty scaled by mismatch
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Penalize large unused fractions (harmonic class > 0.5 capacity)
    if frac > 0.5 {
        score += 30.0 * frac;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would
    // leave a very awkward residual and the stream is early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 120.0;
        // allow new bins more readily early in the stream
        score -= 100.0 * (1.0 - progress);
    }

    // Coupling with mean residual: bins far below mean residual are "loose";
    // prefer packing into bins already tight.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Mild pressure against spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "unusable" if it cannot even hold a minimal item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Non-linear penalty: gaps below ~10 are nearly dead space for typical streams.
    if post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }
    // Reward perfect or near-perfect fills strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Tight-fit reward: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 12.0;

    // Open-bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: if average residual is large, prefer using an
    // existing bin (penalize new-bin candidate implicitly through post_residual
    // which is huge for an empty bin, but add extra pressure).
    score += mean_residual * 0.05;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    } else if next_item_size > 0 {
        // Next item won't fit here anyway; slight penalty for leaving awkward gap.
        score += (post_residual as f64 - next_item_size as f64).abs() * 0.1;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Prefer it only when no existing bin gives a good fit; its post_residual is
    // large, so base score already disfavors it. Add mild stream-progression
    // pressure: late in the stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Aggressive 2-step lookahead matching ---
    // If the next item fits exactly into the post-residual, strongly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward proportional to how snug the 2-step fit is
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        // Extra reward for a perfect 2-step chain (post_residual == next_item_size)
        if slack == 0.0 {
            score -= 60.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here: penalize dead space that blocks the chain
        let blocked = (next_item_size - post_residual) as f64;
        score += 0.5 * blocked;
    }

    // Reward leaving residuals close to the mean (keeps bin portfolio balanced)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Penalize very small unusable residuals (dead space) more aggressively
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin, unless post_residual is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // especially early/mid stream; allow it late when consolidation is done.
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress;
        // But if no open bin gives a good 2-step chain, opening a fresh bin
        // is attractive: discount the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 35.0;
        }
    }

    // Mild preference to fill bins that are already quite full
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio * fill_ratio;

    // Slight penalty for proliferating bins
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Perfect pairing: item + next item fill bin exactly.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: maximize fill, minimize leftover.
        score -= 15.0 * (item_size as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when existing fits are poor
    // or few bins can fit; discourage otherwise.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 * pressure;
        score += 10.0 * (1.0 - progress);
        if mean_residual < item_size as f64 {
            score -= 6.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin can host both if large enough
        }
    }

    // Mild preference for fuller bins among many open bins.
    score += 0.05 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (consolidate emptier space).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep shape
    score += 8.0 * poly * (0.5 + progress); // penalize large residuals more as stream progresses

    // Reward tight fits, amplified late in the stream
    let tightness = 1.0 - x;
    score -= 6.0 * tightness * tightness * (1.0 + 2.0 * progress);

    // Last-chance bin: strong reward, stronger as stream progresses
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as i32 as f64;
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 5.0 * fits_next * (1.0 - slack * slack);
    }

    // Penalty for spreading too many open bins relative to mean residual
    let mean_x = mean_residual / cap;
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - mean_x) * (0.3 + 0.7 * progress);

    // New-bin candidate: penalize opening a new bin unless it is genuinely useful
    if bin_residual == bin_capacity {
        let useful = (item_size as f64 / cap) + 0.5 * (next_item_size as f64 / cap);
        score += 15.0 - 10.0 * useful * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "useful" residue classes get rewarded.
    let pr = post_residual;
    let class = pr % 10; // decade residue class
    let class_bonus = match class {
        0 => 6.0,               // perfectly reusable decade
        1..=3 => 4.0,           // small fillable gap
        4..=7 => 0.0,           // neutral
        _ => 5.0,               // awkward 8..9 gap
    };
    score -= class_bonus;

    // Integer-division tier of post_residual: how many "typical" small
    // items (size ~ mean of 1..100 => 50, small items ~25) could fit.
    let tier = pr / 25; // 0..4 tiers
    score -= tier as f64 * 3.0;

    // Coupling with next item: reward residuals that can host the lookahead.
    if next_item_size > 0 {
        if pr >= next_item_size {
            // lookahead fits exactly: big reward scaled by tightness
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 - slack.min(12.0);
            // harmonic match: same residue class of 10 as lookahead
            if pr % 10 == next_item_size % 10 {
                score -= 4.0;
            }
        } else {
            // lookahead cannot fit here: penalize proportional to how much
            // dead space remains relative to lookahead
            score += (next_item_size - pr) as f64 * 0.15;
        }
    } else {
        // last item: just minimize waste
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening fresh bins unless this item is
    // huge relative to capacity or the open bins are all nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_penalty = 8.0;
        // if item is large, fresh bin is fine
        if item_frac > 0.6 {
            new_bin_penalty -= 6.0;
        }
        // if mean residual across open bins is small, opening is justified
        if mean_residual < item_size as f64 {
            new_bin_penalty -= 8.0;
        }
        // late in the stream, prefer consolidation
        new_bin_penalty += progress * 4.0;
        score += new_bin_penalty;
    } else {
        // Existing-bin bonus scaled by how well residual matches item
        let fit_quality = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= (1.0 - fit_quality) * 2.0;
    }

    // Slight preference to spread load when many bins are open with
    // large mean residual (avoid many half-empty bins).
    if bin_residual != bin_capacity && mean_residual > 30.0 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize moderately tight but non-zero leftovers less than large gaps:
    // a gap is "usable" if it could hold a typical item (>= 10).
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Open-bin pressure: discourage spreading across many bins early,
    // encourage consolidation late.
    score += open_bins_count as f64 * (1.0 + progress) * 0.5;

    // Prefer bins whose residual is close to the mean residual (typical fit),
    // penalize outliers.
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item would fit exactly in the post
    // residual, reward this placement; if post residual is smaller than the
    // next item but nonzero, penalize (dead space for the known future item).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            if post_residual == next_item_size {
                score -= 20.0; // perfect chain fit
            } else {
                score -= 5.0;
            }
        } else if post_residual > 0 {
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // New-bin candidate (empty bin): make it attractive only when it keeps
    // a large residual for future items; otherwise prefer existing bins.
    if bin_residual == bin_capacity {
        score += 15.0; // base tax on opening new bins
        score -= 0.05 * item_size as f64; // big items justify new bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: strongly reward when the next item fits exactly
    // into the post residual (perfect chain), mildly when it fits at all.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item pairing
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward decays as leftover slack after next item grows
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * (gap / bin_capacity as f64);
        }
    }

    // Penalize creating tiny unusable dead space (below minimum item size 1
    // never happens, but very small residuals are hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Compare against mean residual: placing into a bin with residual far
    // above mean (a large hole) is good use of space; below mean is risky.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Slight preference for tighter fits when many bins compete.
    if fitting_bins_count > 1 {
        score += 0.1 * post_residual as f64;
    }

    // Late in the stream, consolidate aggressively (avoid new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        // New-bin candidate: penalize more as stream progresses unless it
        // promises a great chain with the next item.
        score += 5.0 * progress;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space: small post_residual is good, but a tiny unusable sliver is bad.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - snug / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow here; mild penalty unless this bin is nearly full anyway.
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item fits poorly
    // everywhere else. An empty bin has post_residual == capacity - item, which is large,
    // so add a fixed opening cost that tight-fit bonuses in existing bins can overcome.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 - 15.0 * progress; // cheaper to open bins later when streams fragment
        // If the item is large relative to capacity, a fresh bin is more acceptable.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Global pressure: many open bins with low mean residual -> consolidate into emptier bins.
    let relative_mean = mean_residual / bin_capacity as f64;
    score += 10.0 * (relative_mean - (post_residual as f64 / bin_capacity as f64)).abs();

    // Prefer bins with residual close to the item when open-bin count is high (reduce spread).
    if open_bins_count > 3 {
        score += 3.0 * ((bin_residual as f64 - item_size as f64) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic penalty on leftover space (dead space avoidance)
    let mut score = x * x * cap;

    // Smooth non-linear coupling of post-residual with stream progress:
    // early on, leftovers matter less; late, they matter more.
    score *= 1.0 + 0.8 * progress * x;
    score += 0.5 * progress * x * cap;

    // Reward tight fits: cubic falloff as post residual shrinks.
    score -= (1.0 - x) * (1.0 - x) * (1.0 - x) * 10.0;

    // Lookahead coupling: penalize if the next item cannot use this bin's leftover.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // next item fits: reward proportionally to how well it fills the leftover
            let fill = nxt / pr;
            score -= 6.0 * fill * (1.0 - fill.abs() - 0.5).abs().max(0.0) + 3.0 * fill;
        } else {
            // next item cannot fit: penalize leftover more as progress advances
            score += 4.0 * (1.0 - x) * (0.5 + progress);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // many alternatives: mild penalty to keep flexibility
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Penalize bins far above mean residual (fragmented outliers), reward near-mean.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * cap;

    // New-bin candidate handling: penalize opening a new bin smoothly,
    // stronger late in the stream and when other bins fit.
    if bin_residual == bin_capacity {
        let open_pen = 8.0 + 20.0 * progress;
        let alt_pen = if fitting_bins_count > 0 { 15.0 } else { 0.0 };
        score += open_pen + alt_pen;
        // early stream: opening bins is cheap-ish
        score -= 10.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item sizes are reusable; odd residuals create dead space.
    let post = post_residual;
    let class = post % 10;
    match class {
        0 => score -= 12.0,           // perfectly harmonic residual
        1 | 2 | 3 => score += 6.0,    // sliver dead space
        4 | 5 => score -= 3.0,        // half-class usable
        6 | 7 | 8 => score += 4.0,    // awkward class
        _ => score += 1.0,
    }

    // Reward residuals that can exactly host the lookahead item.
    if next_item_size > 0 && post >= next_item_size {
        let slack = (post - next_item_size) as f64;
        if slack == 0.0 {
            score -= 20.0; // perfect lookahead fit
        } else if slack < 10.0 {
            score -= 8.0; // near-perfect lookahead fit
        } else {
            score += slack * 0.15; // large slack wastes potential
        }
    } else if next_item_size > 0 {
        // Lookahead won't fit here: penalize proportionally to how far off.
        score += (next_item_size - post) as f64 * 0.3;
    } else {
        // Last item: prefer tightest packing, no future value in residuals.
        score -= 5.0;
    }

    // Capacity-fraction thresholds on post-residual.
    let quarter = cap / 4.0;
    if (post as f64) < quarter {
        score += 10.0; // tiny residual bin is nearly dead
    } else if (post as f64) < cap / 2.0 {
        score += 2.0;
    } else if (post as f64) < 3.0 * quarter {
        score -= 2.0;
    } else {
        score -= 6.0; // roomy bin keeps flexibility
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post <= 5 {
            score -= 5.0; // extremely tight fit is excellent
        }
    }

    // New-bin candidate: only attractive when open bins are congested
    // (low mean residual) or late in the stream with many bins.
    if bin_residual == bin_capacity {
        let congestion = (mean_residual / cap).clamp(0.0, 1.0);
        score += 25.0 - 30.0 * congestion;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        if open_bins_count == 0 {
            score -= 40.0; // must open the first bin
        }
        if next_item_size > 0 && post >= next_item_size {
            score -= 6.0; // fresh bin accommodates lookahead comfortably
        }
    }

    // Mild preference to spread load when many bins are open and residual
    // is far above the mean (keep bin population balanced).
    if bin_residual as f64 > mean_residual + cap / 3.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is the ideal outcome
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // dead space relative to the known future item
    }

    // Last-chance pressure: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins that are already tight.
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // New-bin candidate: only attractive when no decent fit exists.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
