    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.4 * dev; // below mean residual is good (negative contribution)
    } else {
        score += 0.2 * dev; // above mean residual is mildly bad
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin; the penalty shrinks as stream progresses
        // and when many bins are open with poor residuals.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin can chain the next item too; slightly soften penalty
            score -= 8.0;
        }
    }

    // Mild penalty for wasting space on very small items in large-residual bins
    if (item_size as f64) < 0.25 * bin_residual as f64 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Penalize dead space that can never fit a typical item again.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: bonus if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain
        } else if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large and open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = mean_residual / bin_capacity as f64;
        // Penalize new bins mildly; less so when residuals are low and item is big.
        score += 55.0 - 30.0 * (1.0 - crowding) - 0.2 * item_size as f64 - 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
    }

    // Prefer filling bins that deviate below the mean residual (consolidate fullness).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Mild preference for keeping fewer open bins early on.
    score += 0.5 * open_bins_count as f64 * (1.0 - item_size as f64 / 100.0);

    // Small time-horizon modulation: be greedier late in the stream.
    let horizon = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * horizon * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling: post_residual normalized and shaped by progress
    let r = post_residual as f64 / bin_capacity as f64;
    let poly = r * r * (1.0 - progress) + r * progress * progress;
    score += 40.0 * poly - 20.0 * r;

    // Reward tight fits, more so late in the stream
    let tight = item_size as f64 / bin_residual as f64;
    score -= tight * tight * (30.0 + 40.0 * progress);

    // Dead-space penalty grows with progress (small residuals become useless)
    score += (post_residual as f64).powf(1.5) * 0.05 * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        score -= 12.0 + 10.0 * progress;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: penalize opening bins unless residuals are scarce
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress) - 5.0 * (mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are "dead" (too small for
    // typical items) get penalized; perfectly reusable residuals get rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class boundaries via integer division: residual / 10 classes
    let class = post_residual / 10;
    match class {
        0 => score += 18.0,          // 0..9  : nearly dead space
        1 => score += 9.0,           // 10..19: fits only tiny items
        2 => score += 3.0,           // 20..29: marginal
        3 => score -= 2.0,           // 30..39: useful
        4 => score -= 5.0,           // 40..49: very useful
        5 => score -= 6.0,           // 50..59: half-bin sweet spot
        _ => {}
    }

    // Exact-fit / near-fit reward (modulo-style harmonic check)
    if post_residual == 0 {
        score -= 60.0; // perfect fit, huge reward
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward residuals that are multiples of common item granularities
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 12.0 - slack * 0.5;
            } else {
                score += slack * 0.05; // wasteful chain fit
            }
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // or no good option exists. An empty bin has post_residual == capacity - item.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        // Prefer new bins early (many items remain) but only for large items
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 - 30.0 * fill_frac + 10.0 * progress;
        // If many open bins already have room, discourage a new one
        score += 2.0 * (open_bins_count as f64).sqrt();
    }

    // Mild preference for tighter (smaller-residual) bins overall
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight penalty when bin residual is far above item (bad coupling)
    let gap = (bin_residual - item_size) as f64;
    if gap as u32 == post_residual {
        score -= 1.0; // consistency nudge
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.87;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // or nearly matches the next item size (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if nxt <= pr {
            // Next item can chain into this bin: reward tight chains hardest.
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
            if diff < 1.0 {
                score -= 25.0; // perfect 2-step fill
            }
        } else {
            // Next item cannot fit here: penalize leaving a gap that is
            // "almost but not quite" big enough (worst dead space).
            let gap_waste = (pr / nxt).min(1.0);
            score += 8.0 * gap_waste;
        }
    } else {
        // Last item: just minimize leftover.
        score -= 5.0;
    }

    // Relative-to-mean-residual coupling: prefer filling bins that are
    // tighter than average (avoid fragmenting many half-full bins).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = pr / mean_residual;
        score += 6.0 * (rel - 1.0).clamp(-1.0, 2.0);
    }

    // Penalize creating tiny unusable residuals (< 10 cannot hold any item).
    if pr > 0.0 && pr < 10.0 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when the current item
    // is large and no tight chain exists; make empty bin mildly unattractive
    // by default so it must beat open bins on merit.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.05 * (item_size as f64);
    }

    // Slight stream-position pressure: later in the stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squaring post_residual amplifies wasted space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0 + 0.5 * item_size as f64;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / bin_capacity as f64);
    }
    // If next item cannot fit anywhere after this placement, slight penalty for fragmentation.
    if next_item_size > post_residual {
        score += 5.0;
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // (poor fit anywhere else) or late in the stream.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = 1.0 - frac;
        // Penalize opening new bins, less so for large items / late stream.
        score += 60.0 * openness * (1.0 - 0.5 * progress);
        if frac > 0.5 {
            score -= 30.0 * frac;
        }
    }

    // Prefer bins below mean residual (concentrate waste in few bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Mild preference for keeping fewer open bins.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening
    let mut score = post * (1.0 + 0.5 * fit_ratio * fit_ratio);

    // Polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space is costlier -> amplify large residuals smoothly
    let post_norm = post / cap;
    let progress_coupling = post_norm * post_norm * (post_norm + progress) * (1.0 + progress);
    score += 40.0 * progress_coupling;

    // Reward using an almost-full bin (small residual waste relative to mean)
    score -= 15.0 * (1.0 - post_norm).powi(3);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * fit_ratio;
    }

    // Penalize opening a new bin when good fits exist and stream is advanced
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress * (1.0 - fit_ratio);
        // But allow new bin if mean residual is small (open bins nearly full)
        score -= 10.0 * (1.0 - mean_residual / cap).max(0.0);
    }

    // Lookahead: reward if next item fits into the post residual
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 + 4.0 * progress;
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - post / cap);
    }

    // Mild penalty for bin proliferation
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual (capacity fractions) ---
    // Residuals are bucketed into harmonic classes relative to capacity:
    // tiny (0..=5), small (6..=15), medium (16..=34), large (35..=100)
    let tiny = if post_residual <= 5 { 1.0 } else { 0.0 };
    let small = if post_residual > 5 && post_residual <= 15 { 1.0 } else { 0.0 };
    let large = if post_residual >= 35 { 1.0 } else { 0.0 };

    // Tiny residuals are near-perfect fills: strongly reward.
    score -= 30.0 * tiny;

    // Small residuals are dead space (items >=10 can never use them): penalize.
    score += 25.0 * small;

    // Large residuals leave usable space: mild reward so we don't over-punish.
    score -= 6.0 * large;

    // --- Modulo arithmetic on post_residual: residuals divisible by common
    // item-size classes (10, 20, 25, 50) are re-usable by future items. ---
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 3.0; }
    }

    // --- Lookahead: does the next item fit exactly into post_residual? ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 12.0; // next item can still use this bin
        } else {
            score += 5.0;  // next item won't fit here
        }
    }

    // --- Integer division threshold: how many "average" items still fit? ---
    let avg_item = 30u32;
    let fits_avg = post_residual / avg_item;
    score -= fits_avg as f64 * 4.0;

    // --- Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible). ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling: brand-new empty bin. ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are crowded
        // and the item is large relative to capacity.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        score += 15.0; // base cost of opening a new bin
        score -= 20.0 * crowding * (item_size as f64 / bin_capacity as f64);
        score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // --- Many open bins with slack: discourage spreading items thin. ---
    if open_bins_count > 3 && (post_residual as f64) > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalty grows steeply as residual becomes too small to matter.
    let dead_zone = (10u32).saturating_sub(post_residual) as f64;
    score += dead_zone * dead_zone * 0.5;

    // Reward using bins that would otherwise leave large dead space.
    if post_residual >= 10 {
        score -= 5.0;
    }

    // Lookahead: if next item fits the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open bins pressure: penalize adding load when many bins are open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 1 {
            score -= 30.0; // still allow opening when the only alternative is bad
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter fills).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item -> zero future residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // chain: this bin becomes exactly full after next item
        } else if post_residual > next_item_size {
            let slack_after_next = post_residual - next_item_size;
            if slack_after_next <= 10 {
                score -= 18.0; // near-perfect two-item chain
            } else {
                score -= (10.0 / slack_after_next as f64) * 4.0; // diminishing reward
            }
        } else {
            // next item cannot follow into this bin -> potential dead space
            score += 6.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize the brand-new-bin candidate mildly; only wins when lookahead is bad elsewhere
    if bin_residual == bin_capacity {
        score += 15.0;
        // but allow a new bin if the next item pairs perfectly with the leftover space
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Contextual coupling with mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.08;

    // Late in the stream, avoid leaving tiny unusable fragments
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 5.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small (good packing).
    let fit_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 15.0 {
            score += 25.0 * (15.0 - dead) / 15.0;
        }
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Extra reward if next item fits snugly afterwards too.
        let second_res = post_residual - next_item_size;
        if second_res < 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving space unusable by the next item.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be more selective (avoid wasting bins);
    // late in the stream, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * fit_ratio;
    if progress < 0.3 && post_residual > 40 {
        score += 10.0; // discourage sloppy big-residual placement early
    }

    // Global state: many open bins with high mean residual -> prefer reusing bins.
    if open_bins_count > 3 {
        let reuse_bonus = (mean_residual / bin_capacity as f64).min(1.0);
        score -= 10.0 * reuse_bonus;
    }

    // New-bin candidate: make empty bins less attractive unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 22.0;
        // But allow new bin early when item is large and would leave a good chunk.
        if item_size >= 70 && progress < 0.5 {
            score -= 15.0;
        }
        // If no other bin fits well, allow opening a new one.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer small post residual, with smooth non-linear shaping
    let mut score = post;

    // Non-linear polynomial coupling of post residual with stream progress:
    // early on, tolerate residual slack (keep bins flexible); later, crush dead space harder.
    let coupling = norm_post * norm_post * (1.0 + 3.0 * progress);
    score += coupling * cap * 0.5;

    // Reward tight fits smoothly (quadratic in fill ratio)
    let fill = norm_item;
    score -= 10.0 * fill * fill;

    // Lookahead: bonus if the post residual can smoothly accommodate the next item
    if next_item_size > 0 {
        let gap = norm_post - norm_next;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - gap) * (1.0 - gap) * norm_next;
        } else {
            score += 6.0 * gap * gap * cap;
        }
    }

    // Last-chance bin: smooth urgency term
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 + progress);
    }

    // Penalize divergence from mean residual (smooth dispersion penalty)
    let dev = (post - mean_residual) / cap;
    score += 4.0 * dev * dev * cap;

    // Mild penalty for bin proliferation
    score += 0.3 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 and mod 25
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;

    // Penalize post-residuals that are small but not zero (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }
    // Harmonic residue penalty: residues 1..9 are least reusable
    score += (r10 as f64) * 0.8;

    // Quarters of capacity: post_residual near C/4, C/2, 3C/4 are reusable
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let d_q = (post_residual as i64 - quarter as i64).abs();
    let d_h = (post_residual as i64 - half as i64).abs();
    if d_q <= 5 || d_h <= 5 {
        score -= 15.0;
    }

    // Reward if next item fits exactly into post_residual (perfect chaining)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
            // harmonic class match: next_item and post_residual same mod 10
            if next_item_size % 10 == r10 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this bin's remainder
            score += (r25 as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish, but prefer it when mean residual is tight
    if bin_residual == bin_capacity {
        // opening fresh is fine if existing bins are fragmented
        score = 20.0 + mean_residual * 0.1 - (open_bins_count as f64);
        if fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 25.0; // existing bins too fragmented, discourage new bin
        }
    }

    // Late in the stream, consolidate: penalize spreading across many bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (open_bins_count as f64) * 0.5;

    // Integer-division threshold: post_residual in [0, C/5) is dead space
    if post_residual < bin_capacity / 5 && post_residual > 0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Dead-space avoidance: residuals too small to hold even the minimum
    // item (1) are only truly dead if they are tiny; penalize gaps that
    // cannot accommodate the next item or a plausible small item.
    let pr = post_residual;
    if pr > 0 {
        // Gap smaller than the smallest plausible item chunk -> dead space.
        if pr < 10 {
            score += 60.0;
        } else if next_item_size > 0 && pr < next_item_size {
            // This gap cannot host the lookahead item: mild dead-space tax.
            score += 25.0;
        } else if next_item_size > 0 && pr == next_item_size {
            // Gap exactly fits the lookahead item: reward heavily.
            score -= 200.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, tighten preference for the
    // fullest bins (small post_residual already favored, amplify slightly).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (pr as f64) * 0.05;

    // Progress-aware smoothing: late in the stream, consolidate more
    // aggressively by penalizing any leftover space a bit more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 10.0;

    // New-bin candidate: make an empty bin attractive only when the item
    // leaves a large, reusable residual and existing bins are fragmented.
    if bin_residual == bin_capacity {
        // Base attractiveness of a fresh bin; tuned so it loses to good fits
        // (post_residual small, bonuses applied) but wins over dead-space bins.
        score += 15.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can still host the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight post_residual relative to mean residual.
    score = post_residual as f64 * 1.0 + (post_residual as f64 - mean_residual) * 0.5;

    if next_item_size > 0 {
        // Perfect 2-step lookahead: post_residual exactly matches next item.
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // chain two items perfectly
        } else if diff <= 5.0 {
            score -= 25.0;
        } else if diff <= 15.0 {
            score -= 8.0;
        } else {
            // post_residual too far from next item: dead space risk
            score += diff * 0.3;
        }
        // If next item can't fit in post_residual, penalize proportionally
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    } else {
        // Last item: just minimize waste
        score = post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize creating tiny unusable residuals (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // New-bin candidate (empty bin): only attractive when current bin fit is bad.
    if bin_residual == bin_capacity {
        // Prefer new bin when mean residual is low (open bins are nearly full)
        // or the item is large.
        score = 40.0 + mean_residual * 0.5 - item_size as f64 * 0.3
            - if next_item_size > 0 { (bin_capacity as f64 - next_item_size as f64) * 0.1 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (waste-weighted).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Penalize residuals that strand dead space relative to lookahead.
            score += (next_item_size as f64 - post_residual as f64) * 0.35;
        }
    } else {
        // Last item: minimize waste outright.
        score -= 20.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a bin is justified only when
    // existing fits are poor (post_residual large) or many bins already fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 / bin_capacity as f64; // = 1.0 for new bin call
        let fit_pressure = if fitting_bins_count > 0 {
            1.0 / (1.0 + fitting_bins_count as f64)
        } else {
            1.0
        };
        score -= 8.0 * (1.0 - progress) * fit_pressure;
        score += 25.0 * (1.0 - poor_fit.abs() - 1.0).abs(); // neutralize, keep base high
        score += 30.0 * (mean_residual / bin_capacity as f64).min(1.0);
        // Baseline handicap so new bins only win when existing fits are bad.
        score += 35.0;
    }

    // Slight nudge toward bins with below-average residual (consolidate fullness).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Time horizon: late in the stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    // Crowding: prefer bins among few alternatives slightly less to spread load.
    if fitting_bins_count > 1 {
        score -= 1.5 * (fitting_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (norm_pr * norm_pr) * (1.0 + 2.0 * progress) - (norm_pr * norm_pr * norm_pr) * (1.0 + 3.0 * progress);
    score += poly * cap * 0.5;

    // Tight fits are strongly favored, more so later in the stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + progress) * 10.0;

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize opening a new bin when good fits exist, scaled by open bins
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64).sqrt() * 2.0;
        // New bin is acceptable if post residual leaves useful space for next item
        if next_item_size > 0 && pr >= next_item_size as f64 {
            score -= 6.0;
        }
    }

    // Lookahead: reward residual matching the next item size
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += gap * gap / cap;
    }

    // Deviation from mean residual: prefer bins whose residual is near mean (balanced use)
    score += ((pr - mean_residual) / cap).abs() * 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: reward small, well-quantized leftovers.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 35.0;
    } else if pr <= 20 {
        score -= 15.0;
    } else if pr <= 30 {
        score -= 5.0;
    } else if pr > 50 {
        score += 25.0; // large dead space penalty
    }

    // Modulo arithmetic on residual: multiples of 10 pair better with future items.
    let class = pr % 10;
    if class == 0 {
        score -= 8.0;
    } else if class >= 5 {
        score += 3.0;
    }

    // Integer-division threshold: residual bucket relative to capacity.
    let bucket = (pr * 4) / bin_capacity.max(1); // 0..3
    match bucket {
        0 => score -= 10.0,
        1 => score -= 2.0,
        2 => score += 6.0,
        _ => score += 14.0,
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0; // exact pairing
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item can't use this bin's leftover; mild penalty scaled by gap
            let gap = (next_item_size - pr) as f64;
            score += 4.0 * (gap / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Crowding: many open bins -> prefer tightening existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 3 {
        score -= 5.0 + 10.0 * progress;
    }

    // Relative tightness of fit.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Mean-residual coupling: if this bin is below mean residual, it's a good packer.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate: prefer it only when it genuinely beats packing.
    if bin_residual == bin_capacity {
        score += 18.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    // A gap below half the smallest possible item (relative scale) is "dead" space.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    } else {
        // mild superlinear penalty on mid-range waste
        score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item (chained fits),
    // penalize bins that would leave a gap just barely too small for next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing bins,
    // penalize the new-bin candidate more as open_bins_count grows.
    if bin_residual == bin_capacity {
        score += 3.0 + 1.5 * open_bins_count as f64;
    } else {
        score -= 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: if average residual across open bins is high,
    // discourage opening new bins further; encourage filling loose bins.
    if bin_residual == bin_capacity {
        score += 0.3 * mean_residual;
    } else {
        score -= 0.15 * mean_residual;
    }

    // Stream progression: early on, be picky about fits; late, be greedy to close bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual == 0) as i32 as f64;
    score += 3.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: zero post residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post residual,
    // strongly favor this bin (chain of perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how tightly it packs.
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 60.0 * tight;
        } else {
            // Next item will not fit here: penalize leftover dead space.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 40.0 * waste;
        }
    }

    // Compare post residual to the mean residual across open bins.
    // Leaving this bin far below mean residual creates fragmented small gaps.
    let gap_vs_mean = mean_residual - post_residual as f64;
    if gap_vs_mean > 0.0 {
        score -= 0.5 * gap_vs_mean; // consolidating residual near the mean keeps bins usable
    } else {
        score += 0.3 * (-gap_vs_mean); // pushing residual above mean wastes space
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and current residuals are poor (fragmented small residuals).
    if bin_residual == bin_capacity {
        let avg_res = if open_bins_count > 0 { mean_residual } else { 0.0 };
        let fragmentation = avg_res / bin_capacity as f64;
        // Open a new bin only if existing bins are mostly empty-ish (low fragmentation
        // means many bins have small residuals => better to spread) or item is huge.
        let open_bonus = 150.0 * (1.0 - fragmentation);
        score += open_bonus;
        // Slight late-stream bias: as stream progresses, be more willing to open bins
        // to keep residuals balanced.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 50.0 * progress;
    }

    // Mild penalty for very small post residuals that are not zero:
    // they are unusable dead space for future items (min item size assumption ~10,
    // but sizes unknown 1..100 so scale by capacity fraction).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: smaller post_residual relative to item size is better.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;

    // Lookahead: if next item fits in post_residual, this placement is valuable.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 4.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Dead space risk: leftover cannot hold the next item.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 8.0 * waste_frac;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty to prefer the best-fit among them via post_residual.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a bin is expensive unless the item is large
    // (i.e., current open bins would leave big unusable gaps).
    if is_new_bin {
        let fill = item_size as f64 / bin_capacity as f64;
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Base cost of opening a bin, reduced for large items or when no bin fits.
        let mut open_cost = 18.0 - 14.0 * fill;
        if desperation == 0.0 {
            open_cost -= 20.0; // no open bin fits: opening is necessary
        }
        // Late in the stream, avoid proliferating bins with small residuals.
        open_cost += 6.0 * progress;
        // If mean residual across open bins is small, packing tighter is better than opening.
        if mean_residual > item_size as f64 + 10.0 {
            open_cost += 8.0;
        }
        score += open_cost;
    } else {
        // Existing bin: slight bonus when its residual is below average (consolidating gaps).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        // Reward keeping open-bin count from growing late in the stream.
        score -= 2.0 * (1.0 - progress);
    }

    // Mild preference for bins with residual close to item_size (perfect-ish fit shaping).
    let gap = (bin_residual as i64 - item_size as i64).abs() as f64;
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: wasted space, with smooth non-linear (quadratic/cubic) shaping.
    let x = pr / cap;
    let mut score = pr as f64 * (1.0 + 0.6 * x * x + 0.4 * x * x * x);

    // Coupling: large residuals matter more late in the stream (smooth ramp).
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += late * 12.0 * x * x;

    // Lookahead: reward leaving room for the next item (smooth coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if pr >= nxt { 1.0 } else { 0.0 };
        let gap = (pr - nxt).abs() / cap;
        score -= 8.0 * fit_next * (1.0 - gap * gap);
        // Penalize blocking the next item, stronger mid-stream.
        score += (1.0 - fit_next) * (5.0 + 10.0 * late);
    }

    // Last-chance bonus: only bin that fits -> strong reward to avoid new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mean residual coupling: prefer bins near/below the mean residual (tight fits).
    score += 0.3 * (pr as f64 - mean_residual).abs();

    // New-bin candidate handling: empty bin gets a smooth opening penalty,
    // relaxed when open bins are fragmented or progress is late.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let open_factor = (open_bins_count as f64).ln().max(0.0);
        score = 25.0 + 20.0 * (1.0 - late) + 30.0 * fragmentation - 6.0 * open_factor;
        // Small item on fresh bin is wasteful; smooth penalty.
        score += 15.0 * (1.0 - (item_size as f64 / cap));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly favored (best-fit core).
    score -= (bin_capacity as f64 / (1.0 + post_residual as f64)) * 0.5;

    // Harmonic class: items divisible by common divisors pair well.
    // Penalize post_residual not in the same "harmonic class" as next_item_size.
    if next_item_size > 0 {
        let nr = post_residual as i64;
        let nx = next_item_size as i64;
        if nx <= nr {
            // Next item fits exactly: huge reward.
            if nr == nx {
                score -= 30.0;
            } else {
                // gcd-based coupling: leftover after next item, mod classes.
                let g = gcd(nr, nx);
                let leftover = nr - nx;
                let class_bonus = (g as f64) * 2.0
                    - (leftover % 10.max(g as u32).max(1)) as f64 * 0.3;
                score -= class_bonus.max(0.0);
            }
        } else {
            // Next item cannot use this residual: penalize proportionally to waste.
            score += (nx - nr) as f64 * 0.15;
        }
    }

    // Modulo thresholds on post_residual: residues 0..=3 are golden (near-perfect fills).
    match post_residual % 20 {
        0 => score -= 8.0,
        1 | 2 | 3 => score -= 5.0,
        4..=7 => score -= 2.0,
        8..=12 => { score += 1.0; }
        _ => { score += 3.0; } // large dead zones 13..=19
    }

    // Integer-division threshold: residual chunks below item/2 are hard to reuse.
    if post_residual > 0 && post_residual < item_size / 2 {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when residual would be tiny or stream early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_penalty = post_residual as f64 * 0.9;
        let open_bonus = open_bins_count as f64 * 1.5;
        let early_discount = (1.0 - progress) * 10.0;
        score += waste_penalty + open_bonus - early_discount;
        // If a perfect fill is achievable in the new bin, make it competitive.
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Mild preference for bins below mean residual (keep fat bins for big items).
    if (bin_residual as f64) > mean_residual {
        score += 1.5;
    }

    score
}

fn gcd(a: i64, b: i64) -> i64 {
    let (mut a, mut b) = (a.max(0), b.max(0));
    while b != 0 {
        let t = b;
        b = a % b;
        a = t;
    }
    a.max(1)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Tiny gap: nearly guaranteed dead space unless a tiny item arrives.
            score += 120.0 * (1.0 - post_residual as f64 / 10.0);
        } else if post_residual < 20 {
            score += 25.0;
        }
        // Perfect fit gets a strong reward.
        if post_residual == 0 {
            score -= 200.0;
        }
    }

    // Reward leaving room for the lookahead item if it fits exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 60.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for the next item: dead space penalty.
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins.
    if bin_residual != bin_capacity {
        score -= 5.0 + open_bins_count as f64 * 2.0;
    } else {
        // New bin candidate: mild penalty so it's chosen only when fits are bad.
        score += 15.0;
    }

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    // Prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match bonus: next item fits with small leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: next item cannot fit into leftover.
        score += 12.0 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward bins tighter than the mean residual (good packing density).
    score -= 0.35 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize very small unusable residuals (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild preference for reusing existing bins as stream progresses.
    if bin_residual != bin_capacity {
        score -= 3.0 + 5.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * (1.0 - tight) * (1.0 - tight) * (item_size as f64 / bin_capacity as f64);

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward bins whose post-residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual: mild penalty scaled by wasted fraction
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Prefer fuller bins relative to the fleet average residual.
    score -= 3.0 * ((bin_residual as f64) - mean_residual) / (bin_capacity as f64);

    // Time horizon: early in stream, be conservative about opening bins;
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: base cost of opening a new bin grows with
    // open bins and stream progress; discount it when item is large and no
    // open bin fits well.
    if bin_residual == bin_capacity {
        let mut open_cost = 30.0 + 2.0 * open_bins_count as f64 + 40.0 * progress;
        // If this bin is the only fitting option, opening is cheap.
        if fitting_bins_count == 0 {
            open_cost -= 25.0;
        }
        // Large items justify fresh bins more than small ones.
        open_cost -= 0.2 * item_size as f64;
        // If next item is huge, a fresh bin with room is attractive.
        if next_item_size >= 60 {
            open_cost -= 10.0;
        }
        score = open_cost + 0.1 * post_residual as f64;
    }

    // Small tie-breaker noise-free coupling on residual to break exact ties
    // toward bins with the least leftover.
    score += 0.01 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64 / cap;
    let fit = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = 0.0;

    // Base: prefer small post residual, with progress-dependent curvature
    let base = pr * pr * (0.5 + 1.5 * progress) + pr * (1.0 - progress);
    score += base;

    // Interaction: residual fill ratio vs progress, smooth polynomial
    let fill = 1.0 - pr;
    score -= 2.0 * fill.powi(3) * (0.3 + 0.7 * progress);

    // Tight fit reward amplified late in stream
    let tightness = fit / (bin_residual as f64 / cap).max(1e-6);
    score -= tightness * tightness * (0.5 + 2.0 * progress * progress);

    // Penalize leaving residual close to next item size mismatch (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let gap = (pr - nxt).abs();
        score += 0.8 * gap * gap * (1.0 - progress);
        // Reward if next item fits exactly in post residual
        if nxt <= pr {
            score -= 0.5 * (1.0 - (pr - nxt)) * (0.5 + progress);
        }
    }

    // Last-chance bin bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - pr) * (0.5 + 0.5 * progress);
    }

    // Mild penalty for too many open bins relative to progress
    score += 0.05 * open_bins_count as f64 * (1.0 - progress) * pr;

    // Mean residual coupling: penalize deviating from mean residual
    let dev = (pr - mean_residual / cap).abs();
    score += 0.3 * dev * dev * progress;

    // New empty bin candidate: penalize mildly unless residuals are all bad
    if bin_residual == bin_capacity {
        score += 2.0 - 1.5 * progress;
        if fitting_bins_count == 0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "useful" residue class (multiples of 10, i.e. class 0 mod 10) keep
    // larger future items placeable. Reward those, penalize awkward classes.
    let pr = post_residual as u32;
    let class = pr % 10;
    let harmonic_reward: f64 = match class {
        0 => 14.0,                       // perfectly harmonic leftover
        5 => 7.0,                        // half-harmonic
        1 | 2 | 3 | 4 => 2.0,            // small slivers, mildly useful
        _ => -3.0,                       // 6..9: dead space that blocks mid items
    };
    score -= harmonic_reward;

    // Integer-division threshold: how many copies of the *next* item the
    // leftover could still hold (k=2 lookahead). More copies = better bin.
    if next_item_size > 0 {
        let fits_next = pr >= next_item_size;
        if fits_next {
            let copies = pr / next_item_size.max(1);
            score -= 6.0 + 3.0 * copies as f64;
        } else {
            // leftover can't take the next item: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.35;
        }
        // harmonic coupling: next item size in a "big" class (>=50) pairs
        // best with small post_residual
        if next_item_size >= 50 {
            score += pr as f64 * 0.08;
        } else if next_item_size <= 20 {
            score -= pr as f64 * 0.03;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid a new bin.
    if fitting_bins_count == 1 && pr < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when every existing fit is bad
    // (post_residual high relative to capacity) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fits = if fitting_bins_count > 0 {
            // called alongside real bins; open new bin only if this is a
            // near-perfect fit for the item anyway
            (item_size as f64 / bin_capacity as f64) > 0.85
        } else {
            true
        };
        if bad_fits {
            score -= 10.0 + 8.0 * (1.0 - progress);
        } else {
            score += 25.0; // discourage opening bins when decent fits exist
        }
    }

    // Slight preference for filling bins below the mean residual
    // (keeps bin residuals balanced, avoids many near-empty bins).
    score += (post_residual as f64 - mean_residual) * 0.05;

    // Tight fits (small absolute leftover) get an extra nonlinear bonus.
    if pr <= 5 {
        score -= 10.0;
    } else if pr <= 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it cannot hold even a modest future item (assume min item ~1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits: post_residual small relative to bin capacity.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 100.0 * 0.1;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit creates dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
        if post_residual < 10 {
            score += 30.0; // undo bonus if it creates dead space
        }
    }

    // Open bins pressure: with many open bins, discourage opening a new one.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        score += 25.0 + pressure;
    } else {
        score -= pressure * 0.2;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if post_residual is nonzero but next item won't fit (fragmentation risk).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post_residual exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        // Penalize leaving residuals that are too small for typical future items (dead space).
        if post_residual < 10 {
            score += 40.0;
        } else if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are already tight; prefer them.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fitting bins exist, unless current bins are all tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 15.0 + 10.0 * (1.0 - progress) + 2.0 * openness;
        // Allow new bin if mean residual is small (bins nearly full anyway).
        score -= 0.4 * (bin_capacity as f64 - mean_residual);
    }

    // Mild preference for tighter fits overall (waste-averse).
    score += 0.1 * item_size as f64 / (1.0 + bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream (0..1), long-horizon aware
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly favor placements that nearly fill the bin.
    // Non-linear: residual^1.5 grows faster, punishing wasteful placements.
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score -= (fit_ratio * fit_ratio) * (bin_capacity as f64) * 1.7;

    // Lookahead coupling: if next item can still fit in the post-residual,
    // reward keeping that option alive; otherwise penalize stranding space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain-fit bonus, stronger early in the stream
            score -= (next_item_size as f64) * 0.9 * (1.0 - progress * 0.5);
        } else {
            // dead space relative to the next item's need
            let waste = (post_residual as f64 - next_item_size as f64).abs();
            score += waste * 0.6;
        }
        // perfect two-item fill: post_residual == next_item_size exactly
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else {
        // Last item: pure tight fit matters most
        score -= fit_ratio * 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0 + fit_ratio * 25.0;
    }

    // Global state: many open bins with large mean residual -> prefer reusing
    // existing capacity over opening new bins.
    if open_bins_count > 0 {
        let crowding = mean_residual / bin_capacity as f64;
        if bin_residual < bin_capacity {
            score -= crowding * 8.0;
        } else {
            // new-bin candidate: penalize when open bins still have slack
            score += crowding * 14.0 * (open_bins_count as f64).ln().max(1.0);
        }
    }

    // New-bin candidate extra guard: only attractive late in stream or when
    // item is huge relative to any plausible residual.
    if bin_residual == bin_capacity {
        if fit_ratio > 0.6 {
            score -= 10.0 * fit_ratio;
        }
        score += 6.0 * (1.0 - progress);
    }

    // Mild time-horizon shaping: early stream, consolidation is cheap;
    // late stream, avoid leaving many tiny fragments.
    let frag = post_residual as f64 / bin_capacity as f64;
    score += frag * frag * 20.0 * progress;

    // Small tie-breaker toward bins with less residual overall
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let tightness = 1.0 - prn * prn; // high when post_residual small
    score -= 30.0 * tightness * (0.5 + progress);

    // Penalize large unusable leftovers with cubic term.
    score += 0.002 * pr * pr * pr / (bin_capacity as f64);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 25.0 * (1.0 - prn);
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly early, less late; encourage later when
    // open bins are fragmented (high mean residual).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 15.0 + 60.0 * (1.0 - progress) - 40.0 * fragmentation * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty for bin count pressure.
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover is.
    // Residuals divisible by common item sizes (10/20/25/50) are gold; odd chunks are dead space.
    let r = post_residual;
    let harmony_bonus: f64 = if r == 0 {
        -12.0
    } else if r % 50 == 0 {
        -6.0
    } else if r % 25 == 0 {
        -4.0
    } else if r % 20 == 0 {
        -3.5
    } else if r % 10 == 0 {
        -2.5
    } else if r < 10 {
        6.0 // tiny unusable sliver
    } else {
        0.0
    };
    score += harmony_bonus;

    // Perfect fit / tight-fit reward scaled by stream position.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual == 0 {
        score -= 15.0 + 5.0 * progress;
    } else if post_residual <= 5 {
        score -= 6.0;
    }

    // Fractional capacity coupling: item filling a large fraction of the bin is efficient.
    let fill_frac = item_size as f64 / cap;
    score -= 4.0 * fill_frac;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size < post_residual {
            // prefer leaving room the next item can partially use, penalize awkward remainders
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 3.0;
            } else if slack > 40 {
                score += 1.5;
            }
        } else {
            // next item can't use this residual at all: mildly penalize large leftovers
            score += 0.02 * pr;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: baseline so it competes, penalize opening bins when good fits exist.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.1 * open_bins_count as f64 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative, opening a bin is fine
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual == 0 {
            score -= 5.0;
        }
    }

    // Mean residual coupling: when open bins are mostly full, keep tight packing aggressive.
    if mean_residual < 15.0 {
        score -= 2.0;
    } else if mean_residual > 60.0 {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Unusable sliver: severe penalty.
            score += 40.0 + (10 - post_residual) as f64 * 4.0;
        } else if post_residual < 20 {
            // Likely dead space for most items (min size 10 leaves some hope).
            score += 18.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits generally (post_residual small relative to residual).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage proliferating bins unless the fit is excellent.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate: only attractive if the item is large relative to capacity
    // (little to gain from stuffing it into a partially filled bin) or no good fits exist.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Base new-bin cost; discount when item is big.
        score += 30.0 - 25.0 * large_item;
        // If only this candidate fits, opening a new bin is mandatory.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, avoid opening bins for marginal gains.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next == 0 {
            score -= 20.0;
        } else if gap_after_next <= 10 {
            score += 10.0; // would leave a sliver next step; slight penalty
        } else {
            score -= 5.0;
        }
    }

    // Prefer bins whose residual is close to the mean (avoid fragmenting outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if nxt <= post {
            // Next item fits exactly in this bin's leftover -> strong reward.
            let gap = post - nxt;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 20.0; // perfect 2-step chain
            }
        } else {
            // Next item would not fit here; penalize proportionally to overshoot.
            score += 0.05 * (nxt - post);
        }
    }

    // Compare post_residual against mean residual: creating far-below-average
    // residual means dead space relative to the fleet average.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score += 0.3 * (mean_residual - post_f);
    } else {
        score -= 0.1 * (post_f - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize tight fits that leave tiny unusable slivers (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect closure reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate: neutral baseline, slightly discouraged early when
    // other bins exist, encouraged late in the stream if residuals are low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * 0.55 + 10.0 * progress - 0.2 * mean_residual;
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 8.0; // next item is large; a fresh bin is valuable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving large unusable dead space (dead space threshold depends on stream position).
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let dead_threshold = 9.0 + 6.0 * progress;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score -= 8.0; // small slivers are fine — bin is nearly perfect
    } else if post_residual as f64 >= dead_threshold {
        score += 0.06 * (post_residual as f64 - dead_threshold);
    }

    // Lookahead coupling: if the next item could exactly use the post-residual, big reward.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (nr - post_residual as f64).abs() < 1.0 {
            score -= 25.0;
        } else if nr <= post_residual as f64 {
            score -= 10.0 * (nr / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving medium gaps it might have used
            score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // last item: just fill as tightly as possible
        score -= 12.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin unless fit is awful.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0 + 10.0 * fit_ratio;
    }

    // New-bin candidate handling: prefer opening a new bin when global residuals are bloated
    // and the current fit is poor; penalize new bins when many bins exist with room.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        let bloated = mean_r / bin_capacity as f64;
        // open new bin if existing residuals are small (items mostly consumed) or fit is bad
        if fit_ratio < 0.5 && bloated < 0.35 {
            score -= 10.0;
        } else {
            score += 6.0 + 20.0 * bloated;
        }
        // early stream: opening bins is cheap and useful for future flexibility
        if progress < 0.25 {
            score -= 5.0 * (1.0 - progress * 4.0);
        }
    }

    // Mild global pressure: many open bins -> prefer consolidating into existing ones.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fit_ratio);

    // Mean-residual alignment: prefer bins whose residual is close to the mean (balanced packing),
    // unless it's a perfect fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress * (1.0 - progress);
    score += coupling * 40.0;

    // Reward tight fits more strongly later in the stream (smooth)
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score -= tightness * tightness * (20.0 + 30.0 * progress);

    // Penalize leaving residual that is small but unusable relative to lookahead
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap < 0.0 {
            score += (-gap) * (0.5 + 0.5 * progress) * 2.0;
        } else {
            score -= gap * gap / cap * (1.0 - progress) * 3.0;
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 25.0 * progress;
    }

    // Mild penalty for spreading across many open bins when residuals are high
    let mean_norm = mean_residual / cap;
    score += open_bins_count as f64 * mean_norm * mean_norm * 0.3;

    // Prefer keeping residual near future-friendly sizes (smooth harmonic term)
    score += (pr / cap * std::f64::consts::PI).sin().abs() * 4.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10 (classic dead-space classes for C=100).
    let post_class = (post_residual % 10) as f64;
    score += post_class * 0.35;

    // Reward exact / near-exact fills (harmonic classes 0 mod 10 are reusable).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Integer-division thresholds: bins whose residual falls into "awkward" thirds
    // (residuals 11..30 are hard to fill) get penalized.
    let awkward = ((post_residual / 10) as f64).min(3.0);
    score += awkward * 6.0;

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0 + (post_residual - next_item_size) as f64 * 0.15;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space relative to next item.
        score += ((next_item_size - post_residual) as f64).min(40.0) * 0.4;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (mean_residual.max(1.0) / 20.0 + 1.0);
        let poor_fit = (bin_residual - item_size) as f64;
        score = 55.0 + poor_fit * 0.5 - crowded * 2.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Mild progression pressure: prefer consolidating into existing bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible future item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small gaps (10..20) can only host tiny items; penalize proportionally.
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is highly desirable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.5 * (next_item_size as f64);
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 10.0; // dead space confirmed by lookahead
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (applied as penalty on the new-bin candidate via its full residual).
    if bin_residual == bin_capacity {
        score += 40.0 + 8.0 * (open_bins_count as f64);
        // But if no open bin fits well, new bin becomes attractive:
        if fitting_bins_count == 0 {
            score -= 120.0;
        }
    } else {
        // Slight reward for consolidating into existing bins when many are open.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Progress-based calibration: late in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.2 * ((post_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 60.0; // exact two-item completion
        } else if diff <= 5 {
            score -= 25.0;
        } else if diff <= 15 {
            score -= 8.0;
        } else {
            // penalize large leftover relative to lookahead item
            score += diff as f64 * 0.25;
        }

        // If next item fits exactly into the residual BEFORE this item (i.e.
        // post_residual + item_size == next_item_size), placing here is wasteful.
        if next_item_size > item_size && (next_item_size - item_size) <= bin_residual {
            let alt = bin_residual - (next_item_size - item_size);
            if alt < post_residual {
                score += 10.0;
            }
        }
    } else {
        // Last item: prefer zero residual strongly.
        score -= 40.0;
    }

    // Relative to mean residual: prefer bins with below-average residual
    // (tighter bins), which preserves larger residual bins for future items.
    let rel = mean_residual - post_residual as f64;
    score -= rel * 0.5;

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Avoid opening new bins early in the stream unless residual is tiny.
    if bin_residual == bin_capacity {
        // new-bin candidate: neutral-ish baseline, penalized unless
        // post_residual is small (item nearly fills a fresh bin).
        score += 15.0;
        if post_residual <= 10 {
            score -= 20.0;
        }
    }

    // Late in the stream, tighten packing (favor small post_residual more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    // If this bin's residual is much larger than the mean, it's a "storage"
    // bin; penalize using it for small items slightly.
    if post_residual as f64 > mean_residual * 1.5 && item_size <= 30 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose residual closely matches item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving tiny unusable slivers (dead space < 10 is nearly worthless).
    if post_residual < 10 {
        score -= 8.0;
    } else if post_residual > 50 {
        // Large leftover is good if more big items may come; mild penalty otherwise.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * (1.0 - progress);
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * post_residual as f64;
        } else {
            // Wasting space the next item could have used elsewhere.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Global state coupling: when many bins are open with high mean residual,
    // prefer consolidating into existing bins rather than opening new ones.
    let residual_gap = (mean_residual - bin_residual as f64).abs();
    score += 0.15 * residual_gap;
    score += 0.5 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when existing fits are poor
    // (item much smaller than any residual) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = fit_ratio < 0.6;
        if poor_fit || progress > 0.8 {
            score -= 5.0 + 3.0 * (1.0 - fit_ratio);
        } else {
            score += 15.0; // discourage opening new bins when decent fits exist
        }
    }

    // Time horizon: early in the stream, keep bins flexible (avoid near-full fills
    // of small items); late, squeeze every bin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: prefer tight fits (small post_residual), with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.35 * fill * fill);

    // Dead-space penalty grows quadratically as residual becomes small but unusable
    let dead = pr / cap;
    score += 6.0 * dead * dead * (1.0 - dead);

    // Stream-progress coupling: tighten selection as stream advances
    score *= 1.0 + 0.4 * progress * progress;

    // Reward bins whose post-residual can still accommodate the next item (lookahead fit)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 4.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 {
        score += 2.5 * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Mild penalty when many bins are open (discourage bin proliferation)
    score += 0.05 * open_bins_count as f64;

    // Mean-residual coupling: prefer bins near the mean residual (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // New-bin candidate: penalize slightly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 12.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: classify post_residual by capacity fraction.
    let quarter = bin_capacity / 4;      // 25
    let half = bin_capacity / 2;         // 50
    let three_quarter = 3 * quarter;     // 75

    // Dead-space penalty: residuals too small to hold typical items (1..=100).
    // Residual below 10 is nearly dead space; residual below 25 is weak.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < quarter {
        score += 18.0;
    }

    // Modulo arithmetic on post_residual: residuals near harmonic class
    // boundaries (multiples of quarter/half) are more reusable.
    let m25 = (post_residual % quarter.max(1)) as f64;
    let m50 = (post_residual % half.max(1)) as f64;
    score += 0.10 * m25;
    score -= 0.15 * m50;

    // Integer division thresholds: which harmonic class does post_residual fall in?
    let class = post_residual / quarter.max(1); // 0..=4
    match class {
        0 => { score += 10.0; }          // tiny leftover
        1 => { score += 4.0; }           // 25-49: fits small items
        2 => { score -= 2.0; }           // 50-74: good
        3 => { score -= 4.0; }           // 75-99: excellent
        _ => { score -= 6.0; }           // untouched bin
    }

    // Lookahead: reward if next item fits the post_residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement
    // would waste a lot. Empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; makes it lose against decent fits.
        score += 55.0;
        // But if the item is huge relative to mean residual of open bins,
        // a new bin may be justified: reduce penalty.
        let waste = (mean_residual - item_size as f64).max(0.0);
        score -= 0.4 * waste;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mild preference for bins tighter than the mean (best-fit flavor).
    score += 0.2 * ((bin_residual as f64) - mean_residual).max(0.0);

    // Progress-scaled tie-breaker: slightly favor tighter bins as stream grows.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    // Items are >= 1, but treat residuals below a small threshold as dead space.
    let dead_threshold: f64 = 4.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    }

    // Penalize "awkward" residuals: small but not zero gaps that are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 2 {
        score -= 40.0;
    }

    // Reward leaving room for the next item (lookahead coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin: strong preference to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor tight packing.
    let open_pressure = open_bins_count as f64;
    score += 0.8 * open_pressure;

    // Penalize bins whose residual deviates far above the mean (fragmentation signal).
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.3 * dev;
    } else {
        score += 0.15 * dev;
    }

    // New-bin candidate: only attractive when current bins are heavily fragmented
    // or item is large relative to all residuals.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let base = 35.0 + 30.0 * fragmentation + 0.5 * open_pressure;
        // If item fits well nowhere else, new bin becomes competitive.
        if fitting_bins_count == 0 {
            score = base - 20.0;
        } else {
            score = base;
        }
    }

    // Mild stream-progression term: slightly prefer reusing bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // chainable but leave some slack penalty proportional to leftover
            score -= 150.0 - 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot fit here: penalize proportionally to wasted potential
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: creating below-average residual
    // (tighter packing than average) is rewarded.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Penalize opening new bins when plenty of fitting bins exist
    if bin_residual == bin_capacity {
        score += 40.0 + 5.0 * open_bins_count as f64;
        if next_item_size > 0 {
            // new bin can host next item after this one
            if post_residual >= next_item_size {
                score -= 50.0;
            }
        }
    }

    // Late in the stream, prefer closing bins tightly (reduce fragmentation)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fit gets a large bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize leaving dead space that no plausible item (>=1) can use well:
    // small post_residual is good, but very large post_residual relative to capacity is wasteful.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste_frac * waste_frac;

    // Lookahead coupling: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits: moderate reward scaled by how snugly
            let nfit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 6.0 * nfit;
        } else {
            // next item won't fit here: slight penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 4.0 * over;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.25 * item_size as f64;
    }

    // New-bin candidate handling: empty bin gets baseline penalty so we prefer
    // reusing open bins with decent fits, but bonus if open bins are crowded/fragmented.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing residuals are small (fragmented)
        // or few bins can fit the item.
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64);
        score += 20.0 - 25.0 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in the stream, avoid spawning bins for small items.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * t * (1.0 - item_size as f64 / 100.0);
    }

    // Global state: many open bins with high mean residual -> encourage consolidation
    // into bins with below-average residual (denser bins).
    if open_bins_count > 1 && bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Mild time-horizon term: early in the stream, be slightly conservative about
    // leaving large residuals (future items may use them well).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * (1.0 - t) * waste_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: quadratic waste penalty, amplified as the stream progresses.
    let mut score = pr * (1.0 + 1.5 * progress) + 0.004 * pr * pr;

    // Smooth non-linear coupling: reward tight fits scaled by progress.
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness.powi(3) * (0.5 + progress);

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - gap / cap) * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // Dead space risk for the upcoming item: penalize proportionally to leftover.
        score += 3.0 * (pr / cap) * (1.0 - (next_item_size as f64 / cap));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly; allow it when residuals across bins are large
    // (existing bins are fragmented) or late in the stream with big leftover space.
    if is_new_bin {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 8.0 - 6.0 * fragmentation.powi(2) - 4.0 * progress * fragmentation;
        score += 0.5 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Prefer bins whose residual is below the mean (consolidate small leftovers).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 2.0 * dev.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" classes are preferred since leftover space is more likely wasted.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class penalty by integer division of post_residual into octiles.
    let octile = post_residual / (bin_capacity / 8).max(1);
    let class_penalty: f64 = match octile {
        0 => -40.0,           // near-perfect fit
        1 => -25.0,
        2 => -12.0,
        3 => 0.0,
        4 => 6.0,             // half-full leftover
        5 => 10.0,
        6 => 16.0,
        _ => 22.0,            // mostly empty bin
    };
    score += class_penalty;

    // Modulo coupling: leftover that is congruent to small multiples of common
    // item sizes (10s) is reusable; odd leftovers are penalized.
    let m = post_residual % 10;
    if m == 0 {
        score -= 8.0;
    } else if m <= 3 {
        score += 4.0 * m as f64;
    }

    // Lookahead harmony: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by waste
            score += 0.15 * pr;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // tie-break among many fitting bins: prefer tighter fit
        score += 5.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: only attractive when no open bin fits well or stream early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize new bins generally, but relax late in stream or when mean residual is high
        let mut nb = 35.0 + 0.3 * pr;
        nb -= 25.0 * progress;
        if mean_residual > 40.0 {
            nb -= 15.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 && post_residual == 0 {
            nb -= 50.0; // fresh bin pairs well with a large upcoming item
        }
        score += nb;
    }

    // Global balance: avoid draining bins far below the mean residual.
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=9) are almost certainly wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize proportionally to open bins pressure,
    // but allow opening when residual would leave a large dead gap anyway.
    if bin_residual == bin_capacity {
        score += 10.0 + 1.5 * open_bins_count as f64;
        if post_residual >= 10 && next_item_size as f64 <= post_residual as f64 * 0.9 {
            score -= 8.0;
        }
    }

    // Lookahead: reward if next item fits the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }

    // Open-bin pressure: mildly penalize spreading across many bins.
    score += 0.05 * open_bins_count as f64;

    // Late-stream tightening: prefer filling existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if diff < 0.5 {
            score -= 1000.0; // perfect two-step match
        } else {
            score += diff * 1.5; // penalize mismatch proportional to gap
        }
        // If next item also fits after this placement, mild bonus.
        if pr >= nxt {
            score -= 5.0;
        }
        // Penalize leaving residual that nothing reasonable (>=10) can use.
        if pr < nxt && pr < 10.0 {
            score += 40.0 * (1.0 - pr / 10.0);
        }
    } else {
        // Last item: prefer tightest fit.
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious;
    // avoid wasting a tight bin on an item when looser bins exist.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (res - mean_residual) / mean_residual;
        score -= rel * 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless it's the new-bin candidate itself).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with reasonable fit win by default.
        score += 25.0;
        if fitting_bins_count == 1 {
            score -= 120.0; // open a new bin rather than cramming the only fitting bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // big next item: keep space fresh
        }
    }

    // Prefer filling bins with small residual tightly (waste minimization).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 10.0;

    // Slight late-stream bias toward consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 3.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 2.5 * tightness * (0.5 + 0.5 * progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 6.0 * (0.3 + 0.7 * progress);
    }

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 1.5 * (1.0 - (pr - ni) / cap);
        } else {
            score += 1.0 * (ni - pr) / cap;
        }
    }

    // Penalize bins deviating from mean residual (favor homogeneous fills)
    let dev = (pr - mean_residual).abs() / cap;
    score += 0.8 * dev * dev;

    // Mild penalty for opening new bins when many are open and residual is usable
    if bin_residual == bin_capacity {
        score += 4.0 + 2.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
        if fitting_bins_count > 0 && pr.max(0.0) >= 0.0 {
            score += 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (0..=10, 21..=30, ...) are near-perfect fits.
    let pr = post_residual;
    let class = pr % 10;
    let decade = pr / 10;

    // Reward tiny dead space strongly (perfect packing).
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 25.0 - 2.0 * class as f64;
    }

    // Harmonic pairing: does the leftover match a plausible future item class?
    // Items in 1..100; if next item fits the post residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        // Exact harmonic match (next item leaves another tiny residue) is golden.
        let nxt_class = (pr - next_item_size) % 10;
        let match_bonus = if pr - next_item_size <= 5 {
            30.0
        } else if nxt_class <= 2 {
            18.0
        } else {
            8.0
        };
        score -= match_bonus;
    } else if next_item_size > 0 {
        // Lookahead item cannot use this leftover: penalize proportionally to waste.
        score += (next_item_size as f64) * 0.15;
    }

    // Mid-range leftovers (dead zone 31..=60) are hard to fill: penalize.
    if pr > 30 && pr <= 60 {
        score += 10.0 + 0.2 * (pr - 30) as f64;
    }

    // Decade-based harmonic weighting: prefer leaving residues that are
    // multiples of common item sizes (10/20/25/50).
    if pr % 50 == 0 && pr > 0 {
        score -= 12.0;
    } else if pr % 25 == 0 && pr > 0 {
        score -= 8.0;
    } else if pr % 20 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current bins are crowded or
    // the fit here would be terrible.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        let poor_fit = (item_size as f64) < 0.5 * (bin_capacity as f64);
        if crowded < 0.8 && poor_fit {
            score -= 20.0;
        } else {
            score += 30.0;
        }
    }

    // Prefer filling bins that are already mostly full (small residual relative
    // to capacity) — classic best-fit bias, scaled harmonically.
    let fill_frac = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 15.0 * fill_frac;

    // Mild stream-phase coupling: early on, be more open to new bins.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - phase);

    // Tie-break with mean residual coupling: when open bins are loose on
    // average, tighten selection (penalize loose bins).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are worthless.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Penalize small "unusable" gaps more harshly than large ones (non-linear).
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += (10.0 - gap) * 6.0; // tiny gap = heavy penalty
        } else if gap < 25.0 {
            score += (25.0 - gap) * 1.5;
        }
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 500.0;
        }
    }

    // Exact-fill lookahead: if next item fits the post residual exactly, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 300.0;
    }
    // If next item cannot fit in post residual but could fit elsewhere, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // brand-new bin candidate
        score += 40.0 + 10.0 * open_bins_count as f64;
        // But if mean residual is small (open bins are full), new bin is fine.
        score -= mean_residual * 0.8;
        // Late in stream, prefer new bins less (consolidation).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    } else {
        // Reward placing into bins whose residual is close to item (tight fit).
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score -= (bin_capacity as f64 - tightness) * 0.3;
        // Favor bins with residual below mean (fill the fullest bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: residual after placement exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0; // ideal: next item fills this bin completely
        } else if post_residual > next_item_size {
            // Next item also fits here: reward tighter packing.
            let gap = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit after placement: penalize proportionally.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss;
        }
    } else {
        // Last item: prefer minimal final residual.
        score += 0.0;
    }

    // Reward bins already tighter than average (good candidates).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize creating tiny unusable slivers (< 10, min item size).
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // Slight preference for reusing bins over opening new ones as stream grows.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.001 * step_index as f64;
    }

    // Early in stream: be a bit greedy with residual minimization.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream completed
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized fit quality: how well the item fills the bin
    let fit_ratio = item_size as f64 / bin_residual as f64;

    // Reward tight fits (post_residual small relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize leaving dead space that no typical item can use
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // tiny unusable slivers are fine, they were "used up"
    } else if post_residual >= 10 {
        // dead space that could hold a future item is mildly penalized
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits more aggressively
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 20.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize wasting a good bin on this item
            score += 10.0 * (1.0 - progress);
        }
    }

    // Global state: when mean residual is high, prefer consolidating into fullest bins
    if mean_residual > 0.0 {
        let deviation = bin_residual as f64 - mean_residual;
        score -= 0.05 * deviation; // favor bins fuller than average
    }

    // Time horizon: early on, be more willing to open new bins (exploration);
    // late in the stream, avoid opening bins (exploit existing space)
    let new_bin_penalty = 30.0 + 70.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // but if nothing open fits at all, opening is necessary
        if fitting_bins_count == 0 {
            score -= new_bin_penalty + 100.0;
        }
    }

    // Slight preference for bins with residuals close to item size (exact-ish fit)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * gap;

    // Mild regularization by open bin count to discourage bin proliferation
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let base = norm_post.powi(2) * (1.0 + 2.0 * progress) + 0.35 * norm_post;

    // Penalize dead space that cannot fit the lookahead item (smooth gate).
    let lookahead_waste = if next_item_size > 0 && post_residual > 0 {
        let gap = (next_item_size as f64 - post).max(0.0) / cap;
        gap * gap * (0.5 + progress)
    } else {
        0.0
    };

    // Reward using the last fitting bin before opening a new one.
    let last_chance = if fitting_bins_count == 1 && bin_residual >= item_size {
        -(0.6 + 0.8 * progress)
    } else {
        0.0
    };

    // Discourage opening a new bin when existing bins fit decently.
    let new_bin_penalty = if bin_residual == bin_capacity {
        let tight = (post_residual as f64 / cap);
        (1.5 + 2.0 * progress) * (1.0 - tight * tight) + 0.1 * open_bins_count as f64
    } else {
        0.0
    };

    // Mild preference for bins tighter than the mean residual (smooth coupling).
    let mean_coupling = -0.15 * ((mean_residual - post) / cap);

    base + lookahead_waste + last_chance + new_bin_penalty + mean_coupling
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Harmonic class index: integer division of post_residual into 10-wide bands
    let band = post_residual / 10;
    // Dead space penalty: residuals that are too small to host typical items
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Modulo arithmetic: post_residual divisible by common item sizes is reusable
    let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0) || (post_residual % 50 == 0);
    if reusable {
        score -= 8.0;
    } else {
        score += 3.0;
    }

    // Reward near-exact fits (harmonic closure)
    if post_residual == 0 {
        score -= 40.0;
    } else if frac < 0.1 {
        score -= 12.0;
    } else if frac < 0.25 {
        score -= 4.0;
    } else if frac > 0.7 {
        // Large residual: good candidate for a fresh placement, mild reward
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits into post_residual, this is a great chain
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.25;
        // extra reward if next item exactly fills the residual (harmonic pair)
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }
    // Penalize if next item almost fits but not quite (dead space risk)
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin
    if bin_residual == bin_capacity {
        // Prefer new bin only when all open bins have tiny residuals and item is large
        let pressure = mean_residual / cap;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if pressure < 0.15 && item_size >= 50 {
            score -= 5.0 * (1.0 - progress);
        } else {
            score += 25.0 + 10.0 * progress; // discourage opening new bins generally
        }
        // If many open bins already, opening another dilutes packing
        score += open_bins_count as f64 * 0.5;
    }

    // Mild penalty for bins deviating from mean residual (prefer balanced fills)
    score += ((bin_residual as f64 - mean_residual) * 0.05).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to ever be useful
    // are heavily penalized. Minimum plausible item size is 1, but gaps below
    // a "usable threshold" relative to the stream's typical item size are waste.
    let usable_threshold = 12.0; // gaps smaller than this are near-dead
    if (post_residual as f64) < usable_threshold && post_residual > 0 {
        score += (usable_threshold - post_residual as f64) * 14.0;
    }
    // Perfect fit: zero waste gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Exact-match lookahead: if the next item fits exactly in post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0; // next item still fits: mildly good
    } else if next_item_size > 0 && next_item_size > 0 {
        // next item won't fit here; penalize proportionally to wasted potential
        score += 5.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading to
    // fresh space; favor filling existing bins to consolidate.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += open_pressure;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It should only win when the item fits badly everywhere else.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how many bins fit.
        score += 25.0 + 8.0 * (fitting_bins_count as f64);
        // Late in the stream, opening bins is cheaper (no long tail to manage).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * progress;
        // If the item is large relative to capacity, a fresh bin is natural.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 12.0;
        }
    } else {
        // Reward filling bins that are already mostly full (low residual).
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 10.0 * fill_ratio;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's a good "garbage collector" bin; reward closing the gap to the mean.
    let residual_diff = mean_residual - bin_residual as f64;
    if residual_diff > 0.0 {
        score -= residual_diff * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), but avoid near-zero dead space
    // that can never host the smallest useful item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead-space penalty: unusable sliver
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post >= next {
            // Next item fits: reward proportionally to how snugly it fits.
            let snug = 1.0 - (post - next) / bin_capacity as f64;
            score -= 20.0 + 25.0 * snug;
            // Extra bonus for perfect chaining (post_residual == next_item_size)
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            // Next item won't fit here: penalize, scaled by how badly it misses.
            let miss = (next - post) / bin_capacity as f64;
            score += 15.0 + 40.0 * miss;
        }
    }

    // Relative to mean residual: placing into a bin with residual below mean
    // (i.e. a well-filled bin) is desirable; above mean wastes open capacity.
    let mean_gap = (post_residual as f64) - mean_residual;
    score += 0.5 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Late in the stream, consolidation matters more: penalize leaving large residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Mild penalty for proliferating bins when the new-bin candidate is compared:
    // favor filling existing bins unless post_residual is tiny.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if all existing fits are poor.
        score += 40.0 + (post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio for dynamic time horizon
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: reward tight fits (low post_residual) more strongly over time
    score -= 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * (1.0 + progress);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 20.0;
    }

    // Penalize small unusable dead space (post_residual < smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_gap = post_residual - next_item_size;
        if lookahead_gap == 0 {
            score -= 25.0;
        } else if lookahead_gap < 10 {
            score -= 12.0;
        } else {
            score -= 4.0 * (1.0 - lookahead_gap as f64 / bin_capacity as f64);
        }
    }
    // If next item cannot fit in the leftover, mild penalty proportional to leftover waste
    else if next_item_size > post_residual && post_residual > 0 {
        score += 2.0 + 0.05 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Scarcity pressure: when many bins are open, prefer consolidating into existing bins
    if open_bins_count > 3 && bin_residual < bin_capacity {
        score -= 0.5 * (open_bins_count as f64).ln().max(1.0);
    }

    // Compare this bin's residual against mean residual: prefer bins tighter than average
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: brand-new empty bin
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 10.0;
        // Opening a new bin is attractive when no existing bin gives a tight fit
        // (large post_residual everywhere) or when this is the last-chance scenario fails
        if post_residual >= 40 {
            score -= 12.0; // item is small relative to bin; fresh bin keeps flexibility
        }
        // Late in the stream, avoid proliferating bins
        if progress > 0.7 {
            score += 6.0 * progress;
        }
        // If many bins are open and mean residual is large, reuse instead
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 8.0;
        }
        // Early stream with few bins: opening fresh bins is cheap
        if open_bins_count <= 2 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: as the stream progresses, waste becomes more costly.
    let waste_weight = 1.0 + 2.0 * progress * progress;
    score *= waste_weight;

    // Smooth quadratic penalty for awkward residuals (dead space that few items can use).
    let frac = pr / cap;
    score += 12.0 * frac * frac * (1.0 - frac);

    // Reward tight fits (small post_residual) more strongly late in the stream.
    score -= (cap - pr) / cap * 6.0 * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize if next item cannot use the post-residual.
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 4.0 + 6.0 * progress;
    } else if next_item_size > 0 {
        // Reward leaving just enough room for the next item.
        score -= 3.0 * (1.0 - (pr - next_item_size as f64) / cap).abs();
    }

    // New-bin candidate: prefer opening a new bin only when open bins have poor residuals
    // or the item fits many bins (fragmentation risk low).
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0) / cap;
        let crowding = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).ln();
        score = cap - 18.0 * mean_gap * (1.0 + progress)
            + 10.0 * (fitting_bins_count as f64).powf(0.5)
            + 5.0 * crowding * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 40.0; // never open a new bin when this is the only fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strong reward for zero or tiny post residual.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 60.0 + (5 - post_residual) as f64 * 8.0;
    }

    // Harmonic classes of post_residual: residues divisible by small moduli
    // are more likely to be filled by future small items.
    let pr = post_residual as i64;
    let harmonic_bonus: f64 = if pr > 0 {
        let mut hb = 0.0;
        if pr % 10 == 0 { hb -= 25.0; }       // multiples of 10 align with item grid
        else if pr % 5 == 0 { hb -= 12.0; }
        if pr % 25 == 0 { hb -= 15.0; }        // quarter-capacity alignment
        if pr % 20 == 0 { hb -= 10.0; }
        // Penalize "dead" residues: small odd leftovers unlikely to be reused.
        if pr < 10 && pr % 2 == 1 { hb += 30.0; }
        hb
    } else { 0.0 };
    score += harmonic_bonus;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let new_pr = post_residual - next_item_size;
            if new_pr % 10 == 0 { score -= 40.0; }
            if new_pr < 10 { score -= 15.0; }
            score -= 10.0; // mild reward for keeping next item placeable
        } else {
            // Next item won't fit here; penalize mildly unless bin is nearly full anyway.
            if post_residual < 10 { score += 5.0; } else { score += 20.0; }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer tight bins relative to mean residual of open bins.
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.5;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // offer poor fits. Make the empty bin moderately attractive by default,
    // but discourage hoarding many open bins early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
        score = 55.0 + pressure * 6.0;
        // If item is large, a fresh bin is a decent choice.
        if item_size > bin_capacity / 2 { score -= 15.0; }
        // Near the end of the stream, avoid opening bins.
        if progress > 0.9 { score += 60.0; }
    }

    // Progression-based tightening: as stream advances, reward fuller bins more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.4 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it is too small for the smallest plausible item (1..100 interface,
    // but treat < 10 as near-dead and < next_item_size as unusable for lookahead).
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0; // hard penalty: nothing can ever fill this
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 18.0; // gap unusable for the lookahead item
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0; // perfect lookahead fit: strongly reward
    }

    // Reward tight fits (small relative waste).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins unless fit is excellent.
    let pressure = (open_bins_count as f64).ln().max(0.5);
    score += 6.0 * pressure * (1.0 - tightness);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only allow opening a new bin when no open bin gives
    // a good fit (e.g., item nearly fills the new bin or open bins are crowded).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 {
            score -= 40.0 * (fill_ratio - 0.7) / 0.3; // big items prefer fresh bins
        } else {
            score += 45.0 + 8.0 * pressure; // penalize opening bins for small items
        }
        // If existing bins are nearly full on average, opening a bin is more acceptable.
        score -= 10.0 * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
    }

    // Mild stream-position term: later in stream, prefer consolidating into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale waste by relative fill achieved
    let fill = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill * fill;

    // Penalize dead space that is too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly-full bin: good, but tiny残 space is fine — actually reward
        score -= 45.0; // net reward for near-closure
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // penalize leaving a gap that next item barely misses
            let gap = (next_item_size as f64 - post_residual as f64).max(0.0);
            score += 0.4 * gap;
        }
    } else {
        // last item: strongly prefer fullest packing
        score -= 20.0;
    }

    // Prefer using bins with below-average residual (concentrate waste)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // When many bins are open, prefer closing them out (reduce fragmentation)
    if open_bins_count > 4 {
        score -= 1.5 * (open_bins_count as f64).ln() * fill;
    }

    // Time horizon: early in stream, be pickier about creating small residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 25 {
        score += 10.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        let base = 45.0 + 0.5 * (open_bins_count as f64);
        // allow new bin if this item is large and would leave bad residual elsewhere
        let poor_fit = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
        score = base + 60.0 * (1.0 - poor_fit) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer minimal post-residual, with non-linear polynomial shaping
    let mut score = pr
        + 30.0 * pr_norm * pr_norm * cap
        - 20.0 * pr_norm * pr_norm * pr_norm * cap * (0.5 + 0.5 * progress);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 15.0 * tightness * tightness * (1.0 + progress);

    // Lookahead coupling: bonus if next item fits the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 12.0 * (1.0 - (pr - nxt) / cap) * (0.6 + 0.4 * progress);
        } else {
            score += 8.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else {
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Penalize bins whose residual deviates from the mean (fragmentation control)
    score += 5.0 * (pr - mean_residual).abs() / cap;

    // Slight preference for consolidating into fewer bins early on
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    // New-bin candidate: penalize opening a bin unless it is genuinely better
    if bin_residual == bin_capacity {
        score += 18.0 + 15.0 * (1.0 - progress) + pr_norm * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition [0,C] into 5 residue bands.
    let q = bin_capacity / 5; // 20
    let class = post_residual / q; // 0..=5
    let within = (post_residual % q) as f64;

    // Penalize small dead-space classes (unusable leftovers), reward large ones.
    match class {
        0 => score += 30.0 + within * 0.5,          // post_residual < 20: worst
        1 => score += 12.0,                          // 20..40
        2 => score += 0.0,                           // neutral
        3 => score -= 8.0,                           // 60..80: good
        _ => score -= 15.0,                          // >=80: excellent
    }

    // Exact-fit reward (item fills bin completely).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic pairing: does the next item fit into the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: strongly reward, scaled by how snugly.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 + 25.0 * snug;
        } else {
            // Next item won't fit here: penalize leaving this class of residual.
            score += 10.0;
            // Extra penalty if next item is in the "awkward" 41..60 harmonic class
            let nq = next_item_size / q;
            if nq == 2 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when residuals
    // across open bins are large relative to capacity (wasted space everywhere)
    // or the item would leave a tiny unusable residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste_pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of a fresh bin; drops when open bins are badly fragmented.
        score = 55.0 - 30.0 * waste_pressure - 10.0 * progress;
        if item_size > 60 {
            score -= 10.0; // big items start fresh bins more readily
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 15.0; // pair potential exists in an open bin instead
        }
    } else {
        // Mild preference for tighter existing bins (best-fit flavor) modulated
        // by mean residual: when mean residual is high, tighten more aggressively.
        let tight = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * tight * (mean_residual / bin_capacity as f64);
    }

    // Late-stream consolidation: prefer closing bins near the end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && post_residual < q {
        score += 5.0 * progress; // avoid creating tiny dead space late
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny dead space is nearly worthless
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0; // small gap, only fits tiny items
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit, strongly reward
    }

    // Reward residual gaps that can still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // gap too small for next item: dead space risk
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, allow opening new ones for better structure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only when few bins are open
        // or current fits are poor (large post_residual elsewhere).
        score -= 18.0 - 6.0 * pressure;
        if post_residual > 50.0 {
            score -= 5.0; // big residual: keep it flexible
        }
    } else {
        score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);
    }

    // Late in the stream, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with below-mean residual (tighter bins) for small items.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter post-fit (small post_residual) is better.
    // Penalize dead space non-linearly: residuals too small for any item (1..100) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 20.0 - (slack as f64).min(20.0); // perfect chain gets up to -20
        if slack == 0 {
            score -= 15.0; // perfect two-item packing
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item can't chain here; mildly penalize closing off this bin.
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless item fits poorly everywhere
    // or the lookahead chains well in a fresh bin.
    if bin_residual == bin_capacity {
        let base_penalty = 35.0;
        // In a fresh bin, would the next item chain nicely?
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0; // fresh bin enables a good chain
        }
        // If few fitting bins and current bins are tight, new bin is reasonable.
        if fitting_bins_count > 1 {
            score += base_penalty;
        } else {
            score += 12.0; // still slightly discouraged if it's the only option
        }
    }

    // Contextual coupling with mean residual: prefer bins whose post_residual
    // aligns with the fleet average (keeps a portfolio of usable gaps).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Late in the stream, prefer filling existing bins more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.2 * progress;

    // Tie-break: prefer bins with larger pre-fit residual when otherwise equal
    // (keeps small-gap bins for small items).
    score -= (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small for the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving exactly enough room for the next item.
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, scaled by how many.
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: opening a bin is penalized early, allowed late.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(0.1);
        let open_penalty = 18.0 * (1.0 - t) + 4.0;
        score += open_penalty;
        // If mean residual is large and fragmented, opening a fresh bin is attractive.
        if mean_residual > 2.0 * item_size as f64 {
            score -= 10.0;
        }
        // Penalize opening bins when pressure is low (many bins, big residuals).
        score += 0.05 * pressure;
    } else {
        // Slight preference for bins whose residual is close to item (best-fit flavor).
        score += 0.15 * ((bin_residual - item_size) as f64).abs();
    }

    // Global state: many open bins with small mean residual -> prefer consolidating.
    if mean_residual < item_size as f64 {
        score += 5.0;
    }

    // Time-horizon modulation: late in the stream, be more conservative (avoid waste).
    score *= 1.0 + 0.3 * t;

    // Small deterministic tie-breaker based on residual parity structure.
    score += 0.01 * ((post_residual % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling: reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    let coupling = tightness * tightness * (0.5 + progress);
    score -= 40.0 * coupling;
    // penalize large residuals late in the stream (dead space becomes costlier)
    let late = progress * progress;
    score += 25.0 * late * norm_pr * norm_pr;
    // lookahead: reward residual that still fits the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - slack) * (1.0 - progress * 0.5);
    }
    // last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }
    // slight penalty for spreading across many open bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;
    // interaction with mean residual: prefer bins below mean residual (tighter)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * (0.3 + 0.7 * progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residuals that fall into "dead zones" — small but useless slivers.
    // Class boundaries via integer division on post_residual.
    let cls = post_residual / 10; // harmonic class of size 10
    match cls {
        0 => score += 40.0,                 // 0..9 : perfect fill, reward
        1 => score -= 5.0,                  // 10..19 : usable for small items
        2 => score += 6.0,                  // 20..29 : moderate dead space
        3 => score += 10.0,                 // 30..39
        4 => score -= 8.0,                  // 40..49 : half-bin, very reusable
        5 => score += 4.0,
        6 => score -= 6.0,                  // 60..69
        7 => score += 2.0,
        8 => score -= 4.0,                  // 80..89
        _ => {}
    }

    // Modulo-10 harmonic: residuals divisible by 10 pair well with common item sizes.
    if post_residual % 10 == 0 {
        score -= 3.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Reward proportionally to how well next item fills the leftover.
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 12.0 * fill;
        // Penalize leaving a tiny sliver after the hypothetical next placement.
        let post2 = post_residual - next_item_size;
        if post2 < 10 && post2 > 0 {
            score += 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here: leftover becomes dead unless reusable later.
        score += 5.0 * frac;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, offset by stream progression (fewer new bins late).
        score = 55.0 - 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // If many bins already fit the item, new bin is unattractive.
        if fitting_bins_count > 0 {
            score += 18.0;
        }
        // If mean residual across open bins is large, prefer reusing.
        score += (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 25.0;
        // Large items starting fresh bins is fine early.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Tight fit reward: item nearly fills the bin.
    if item_size >= bin_residual * 9 / 10 {
        score -= 15.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize gaps too small for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
    }
    // Penalize tiny unusable slivers hard (dead space archetype).
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits aggressively.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward tight fit relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer bins with below-average residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: keep it neutral-to-slightly-high unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 3.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching.
    let progress = step_index as f64 / total_items.max(1) as f64;

    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward bins whose post_residual exactly matches the next item's size.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            // Penalize mismatch proportionally, stronger early in the stream.
            score += gap * (1.2 - 0.5 * progress);
        }
        // If next item fits exactly in the residual BEFORE placement, mild bonus.
        if bin_residual == item_size + next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual that cannot host the next item but is small (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.9;
        }
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit flavor).
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64; // = capacity - item
        score += waste * 0.5 + 10.0;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Slight preference to consolidate into fewer bins when many are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins whose residual is barely consumed.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Lookahead: if the next item exactly fills the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // next item can still fit here: mild reward proportional to how well it fills
            let nxt_fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * nxt_fill;
        } else {
            // next item cannot use leftover space: penalize dead space creation
            score += 25.0;
        }
    } else {
        // Last item: minimize leftover as much as possible.
        score += 40.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: opening a bin is expensive when decent fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        // Penalize new bins more early on; relax later when fragmentation grows.
        score += 80.0 + 60.0 * (1.0 - progress) - 70.0 * scarcity;
        // If the item is large relative to capacity, a fresh bin is more acceptable.
        score -= 30.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Global fragmentation: if mean residual is small, bins are nearly full —
    // prefer using them rather than opening new ones.
    score -= 15.0 * (mean_residual / bin_capacity as f64);

    // Slight preference for bins already below mean residual (consolidate emptier bins).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // Penalize very small unusable leftovers, scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: penalize leftover residual, with smooth non-linear coupling to progress.
    let base = pr as f64 * (1.0 + 0.5 * progress * x);

    // Non-linear penalty on unusable dead space: residuals too small for any item are bad.
    let dead = if x > 0.0 { (x * (1.0 - x)).powi(2) } else { 0.0 };
    let dead_penalty = 30.0 * dead * (1.0 - progress);

    // Tight fit reward: quadratic coupling of fill ratio with progress.
    let fill = 1.0 - x;
    let tight_reward = -(fill * fill) * (10.0 + 20.0 * progress);

    // Lookahead: reward leaving space for the next item, smoothly.
    let next = next_item_size as f64;
    let lookahead = if next > 0.0 {
        let diff = (pr - next).abs();
        -15.0 * (1.0 - diff / cap).exp() * (1.0 - progress)
    } else {
        0.0
    };

    // Last-chance bonus: strongly favor the only bin that fits.
    let last_chance = if fitting_bins_count == 1 { -40.0 } else { 0.0 };

    // Mild penalty for spreading across many bins early.
    let spread = 0.5 * open_bins_count as f64 * (1.0 - progress) * x;

    // New-bin candidate: penalize lightly unless residuals elsewhere are messy.
    let new_bin_bias = if bin_residual == bin_capacity {
        8.0 * (1.0 - progress) + 0.2 * mean_residual
    } else {
        0.0
    };

    base + dead_penalty + tight_reward + lookahead + last_chance + spread + new_bin_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: exact or near-exact fills are gold.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Harmonic class logic on post_residual: classify dead space into
    // capacity fractions (C=100 => classes of 25, but works generically).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let class = match post_residual {
        0 => 0,
        r if r <= quarter / 2 => 1,
        r if r <= quarter => 2,
        r if r <= half => 3,
        _ => 4,
    };
    // Penalize leaving residual in the "awkward" middle classes.
    score += match class {
        0 => -200.0,
        1 => -30.0,
        2 => 10.0,
        3 => 25.0,
        _ => 5.0,
    };

    // Modulo arithmetic on post_residual: residuals that divide the
    // typical small-item sizes (e.g. divisible by 10) are reusable.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 15.0;
    }
    if post_residual > 0 && post_residual % 5 == 0 {
        score -= 5.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 40.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow here; slight penalty grows with overflow.
            let over = next_item_size - post_residual;
            score += (over as f64).min(50.0) * 0.3;
        }
    } else {
        // Last item: just minimize waste.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it attractive only when open bins are crowded
    // or the fit here is bad. An empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; cheaper late in the stream is wrong,
        // actually opening early amortizes better, so penalize more late.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + 30.0 * progress;
        // Opening a new bin is good if the item is large and mean residual is small.
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 60.0 * large_item;
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
        // If many bins can fit, prefer reusing one.
        score += 20.0 * (fitting_bins_count as f64).min(5.0);
        // If next item also large, a fresh bin gives flexibility.
        if next_item_size >= half {
            score -= 15.0;
        }
    }

    // Mild preference for filling fuller bins first (best-fit flavor)
    // scaled by how many alternatives exist.
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 20.0 * fullness / (fitting_bins_count as f64).max(1.0).sqrt();

    // Small tie-breaker on stream position to stabilize choices.
    score += 0.001 * (step_index as f64).sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 15.0 / (1.0 + tightness);

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage new bins, encourage filling.
    let pressure = (open_bins_count as f64) / 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 25.0 + 10.0 * pressure;
    } else {
        score -= pressure;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 18.0;
    }
    // If next item cannot fit in post_residual but could fit elsewhere, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: prefer bins whose residual is below mean (tighter bins).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (low post residual)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // 2-step lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits: residual after next placement
            let next_post = post_residual as f64 - next_item_size as f64;
            score -= 200.0 - next_post * 2.0;
        } else {
            // next item won't fit here: penalize large wasted residual
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Penalize residuals that are too small to ever fit future items (dead space)
    if post_residual < 10 {
        score += 150.0;
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base_penalty = 120.0 + item_size as f64 * 1.0;
        // late in stream, prefer packing into existing bins even more
        score += base_penalty * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.02;

    // Penalize small unusable dead space (post_residual < 10 typically wasted).
    if post_residual < 10 {
        score -= 15.0; // dead space is actually fine (bin nearly full) -> reward
    } else {
        score += post_residual as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item could combine with post_residual, reward leaving that gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect pairing
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0; // next item won't fit in leftover
        }
    }

    // Time horizon: early in stream, be more willing to open new bins (penalize cramming);
    // late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 * open_bins_count as f64;
    score -= progress * 5.0;

    // Global state: many open bins with high mean residual -> favor filling existing bins.
    if mean_residual > 30.0 && open_bins_count > 3 {
        score -= 8.0;
    }

    // New-bin candidate bias: empty bin gets a moderate handicap unless item is large.
    if bin_residual == bin_capacity {
        score += 12.0 - (item_size as f64 * 0.1);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let t = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual
    let pr = post_residual as f64 / bin_capacity as f64;

    // Smooth polynomial coupling: penalize large residuals more as stream progresses
    let progress_weight = 1.0 + 2.0 * t * t;
    score += 8.0 * pr * pr * progress_weight;

    // Reward tight fits (small post_residual) with a smooth non-linear bonus
    score -= 6.0 * (1.0 - pr) * (1.0 - pr) * pr;

    // Penalize residual that is large but unusable relative to the lookahead item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64) < ni {
            score += 4.0 * (ni - post_residual as f64) / bin_capacity as f64 * (0.5 + t);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Slight penalty for many open bins to encourage consolidation
    score += 0.3 * open_bins_count as f64 * pr;

    // Coupling with mean residual: prefer bins whose residual deviates below mean (tighter bins)
    score += 2.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;

    // New-bin candidate: mildly discouraged unless residual would otherwise be dead space
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Dead-space penalty: tiny residuals are nearly unusable (items >= 1).
    if pr == 0 {
        score -= 30.0; // perfect fit is great
    } else if pr < 10 {
        score += 25.0; // dead space class
    } else if pr < 20 {
        score += 12.0;
    }

    // Modulo-class harmonic: residuals divisible by 8 or 10 pair well with
    // common item granularities; reward those classes.
    if pr % 8 == 0 && pr > 0 {
        score -= 4.0;
    }
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    }
    // Odd awkward class penalized.
    if pr % 2 == 1 && pr < 30 {
        score += 3.0;
    }

    // Integer-division threshold: can next item fit here after placement?
    if next_item_size > 0 && pr >= next_item_size {
        // Lookahead bonus scaled by how snugly the pair packs.
        let pair_waste = (pr - next_item_size) as f64;
        score -= 8.0 - 0.05 * pair_waste;
        // Harmonic bonus if next item leaves another divisible-class residual.
        let pr2 = pr - next_item_size;
        if pr2 % 10 == 0 && pr2 > 0 {
            score -= 3.0;
        }
        if pr2 == 0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && pr < next_item_size && pr > 0 {
        // Next item cannot use this residual: penalize proportionally.
        score += 0.15 * prf;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer fuller bins relative to mean residual of open bins.
    score += 0.3 * (prf - mean_residual);

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; increases with stream progress.
        let progress = step_index as f64 / (total_items.max(2) as f64);
        score = cap * 0.55 + 20.0 * progress;
        if next_item_size > 0 && pr >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small for the smallest plausible item are "dead space".
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0; // unusable sliver
    }
    // Dead space relative to capacity: small but nonzero gaps that likely can't
    // fit future items are heavily penalized (non-linear).
    let dead_ratio = post_residual as f64 / bin_capacity as f64;
    if post_residual > 0 && dead_ratio < 0.10 {
        score += 60.0 * (0.10 - dead_ratio) * 10.0; // up to +60 for near-zero gaps
    }
    // Perfect fit bonus: zero post residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // --- Lookahead coupling ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin stays useful for the next item: reward.
            score -= 12.0;
            // Extra reward if post_residual is a tight fit for next item (efficient packing).
            let slack_after_next = post_residual - next_item_size;
            score -= 8.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            // Bin becomes dead after this placement but next item won't fit: penalize.
            score += 25.0;
        }
    }

    // --- Last-chance pressure ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // This is the only bin that fits; strongly prefer using it over opening a new bin.
        score -= 35.0;
    }

    // --- Open bins pressure ---
    // Many open bins: encourage consolidating into existing bins (subtracted reward),
    // especially when mean residual is large.
    let consolidation = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    score -= 1.5 * consolidation;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when nothing fits well:
        // penalize it when good alternatives exist.
        if fitting_bins_count > 0 {
            score += 45.0;
        }
        // Slight stream-progression bias: later in the stream, prefer closing out bins.
        score += 5.0 * (step_index as f64 / total_items.max(1) as f64);
    } else {
        // Existing bin: reward tightness (small post_residual already base score).
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 10.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post_residual exactly matches next item (perfect 2-step chain)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post residual can still host next item: mild reward proportional to tightness
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize wasted capacity relative to next size
        score += 15.0 + 0.5 * (post_residual as f64).min(next_item_size as f64);
    }

    // Penalize small dead space (< 10, unusable for most items)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score -= 0.4 * (mean_residual - bin_residual as f64);

    // Mild preference for consolidating into fewer bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open and stream is early
        score += 20.0 + 10.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on leftover space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            // Extra reward if the next item then leaves a small remainder (chaining).
            let chain_left = post_residual - next_item_size;
            if chain_left < 10 {
                score -= 15.0;
            }
        } else {
            // Penalize leaving a sliver the next item cannot use (dead space).
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Fragmentation guard: penalize creating residuals in the awkward 1..20 zone.
    if post_residual >= 1 && post_residual < 20 {
        score += 12.0;
    }

    // Global pressure: when many bins are open relative to progress, be conservative
    // (favor filling existing bins); early on, allow spreading into new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count as f64 > 4.0 + progress * 10.0 {
        score += 8.0; // discourage opening yet another bin
    }

    // Compare against mean residual: bins with residual well below mean are "dense";
    // filling them keeps the bin set compact.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream
        // or when many bins would otherwise be left fragmented.
        let new_bin_cost = 45.0 - 20.0 * (1.0 - progress);
        score += new_bin_cost;
        // If the item is large, a fresh bin is more attractive (less fragmentation risk).
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // If next item is also large, fresh bin keeps room for it.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    let mut score = pr as f64;

    // Non-linear coupling: reward tight fits more strongly as stream progresses
    score -= (1.0 - x).powf(2.0) * cap * (0.5 + progress);

    // Penalize large dead space with a convex term
    score += x * x * cap * 0.3;

    // Interaction with mean residual: prefer bins near the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * 0.4;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= cap * 0.75 * (1.0 + progress);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= (1.0 - slack).powf(2.0) * cap * 0.25;
        } else {
            score += (nx - pr) * 0.5;
        }
    }

    // Mild penalty for spreading across too many open bins late in the stream
    score += (open_bins_count as f64) * progress * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_class = post_residual % 25; // quarter-capacity harmonic class
    let half_class = post_residual % 10; // decade harmonic class

    // Reward post-residuals that fall into "usable" harmonic classes:
    // small residues (near 0 mod 25) mean the bin is nearly full -> good packing
    score -= (25 - post_class as f64) * 0.35;

    // Penalize mid-range dead space classes (residues 8..17 mod 25 are awkward)
    if post_class >= 8 && post_class <= 17 {
        score += 6.0;
    }

    // Integer-division thresholds: how many items of size 10 could still fit
    let fit_units = post_residual / 10;
    score -= fit_units as f64 * 1.2;

    // Perfect fills get strong reward
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // harmonic match between next item and post-residual class
            let nclass = next_item_size % 25;
            if nclass == post_class {
                score -= 8.0;
            }
            score -= (post - next_item_size as f64) * 0.15;
        } else {
            // next item won't fit here; penalize leaving large awkward residue
            score += (next_item_size as f64 - post) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a bin unless residuals are all bad
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if stream is early and open bins are fragmented, allow new bin
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 && mean_residual < cap * 0.4 {
            score -= 25.0;
        }
        // if next item is huge, a fresh bin is safer
        if next_item_size > 60 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - post) * 0.08;

    // Open bins pressure: more open bins -> favor filling existing ones
    score -= open_bins_count as f64 * 0.05;

    // Half-capacity harmonic boundary: residues just under 50 are wasteful
    if post_residual >= 45 && post_residual <= 55 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
