pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact matches between
    // post_residual and the next item's size (perfect follow-up placement).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            score -= 60.0; // perfect two-item packing (item + next fills bin)
        } else if post >= nxt {
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize proportional to wasted gap
            score += 5.0 + diff * 0.15;
        }
        // If post_residual fits next item but leaves tiny unusable sliver, penalize
        if post >= nxt && (post - nxt) < 5.0 {
            score -= 10.0; // near-perfect double fill
        }
        if post > 0.0 && post < nxt && post < 10.0 {
            score += 20.0; // dead sliver unusable by next item
        }
    } else {
        // Last item: strongly prefer tightest fit
        score -= 40.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Penalize large remaining residual (wasted space) nonlinearly
    let post_f = post_residual as f64;
    score += 0.01 * post_f * post_f / bin_capacity as f64;

    // Last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin
        score += 45.0;
        // Attractive if item is large and current bins are fragmented
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if large_item || mean_residual < item_size as f64 {
            score -= 55.0;
        }
        // Slightly less penalized early in stream
        score -= 10.0 * (1.0 - progress);
        // Prefer new bin if next item pairs well with residual after placing item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Mild penalty for proliferating open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively.
    score += (post_residual as f64 / bin_capacity as f64).powf(1.7) * 40.0;

    // Penalize dead space that is too small to hold any future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count <= 1 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; mild penalty for wasting residual
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Time horizon: early in the stream, be picky (penalize loose fits);
    // late in the stream, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64) * 0.3;

    // Global state: many open bins with high mean residual -> prefer reusing
    // bins with residual close to the mean (keeps bin profile uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;
    if open_bins_count > 4 && mean_residual > item_size as f64 * 1.5 {
        score -= 5.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and current residuals are poor.
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual / bin_capacity as f64;
        score += 45.0 - avg_fit * 30.0;
        if item_size > 60 && post_residual < 40 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        }
    }

    // Prefer bins whose residual is just above the item (perfect-ish fits).
    let slack = (bin_residual - item_size) as f64;
    score += slack * slack * 0.004;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping
    let mut score = pr as f64;
    score += 12.0 * norm_pr * norm_pr * (1.0 + 2.0 * progress);

    // Stream-progress coupling: later in the stream, penalize large residuals more
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 8.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 6.0 * (ni - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Many open bins: prefer filling existing ones over spreading
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    // Mean residual coupling: if this bin deviates badly from mean, slight penalty
    score += 0.05 * ((mean_residual - pr).abs());

    // New-bin candidate: mild penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: mod-10 buckets penalize "dead" residues
    let pr = post_residual;
    let class = pr % 10;
    if pr > 0 {
        // residues that are hard to fill (small odd remainders) get penalized
        score += match class {
            0 => -30.0,                     // perfectly divisible leftover: very reusable
            1 | 3 | 7 | 9 => 12.0,          // odd small residues: poor fillability
            5 => -8.0,                      // halves-friendly
            2 | 4 | 6 | 8 => -3.0,         // even residues: moderately reusable
            _ => 0.0,
        };
        // graded penalty scaled by how small the leftover is
        if pr < 10 { score += 25.0 * (10.0 - pr as f64); }
        else if pr < 20 { score += 6.0; }
    } else {
        score -= 40.0; // perfect fit: strongly reward
    }

    // Integer-division threshold: does next item fit into post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // lookahead fit: reward, more if it nearly fills the bin
            let gap = (pr - next_item_size) as f64;
            score -= 18.0 - 0.25 * gap;
            if (pr % next_item_size.max(1)) == 0 { score -= 10.0; } // exact division harmony
        } else {
            // next item cannot use the leftover: penalize proportionally
            score += 0.35 * (next_item_size - pr) as f64;
        }
    }

    // Capacity-fraction coupling of item size
    let frac = item_size as f64 / cap;
    if frac > 0.5 {
        score -= 10.0 * frac; // big items prefer tightest bin
    } else if frac < 0.2 {
        score += 5.0 * (1.0 - frac); // tiny items in a roomy bin: mild penalty
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure from open bins / progress
        score += 20.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 8.0; // next item is large, fresh bin may help
        }
    } else {
        // favor bins whose residual is below mean (tighter bins first)
        if (bin_residual as f64) < mean_residual { score -= 4.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for unusable dead space: gaps too small for the minimum item size.
    if post_residual < 10 {
        score -= 60.0; // a filled bin is a "perfect" outcome
    } else if post_residual < item_size {
        // gap smaller than current item: likely dead space unless future items are tiny
        score += 25.0;
    }

    // Reward tight fits (small usable post_residual relative to item size)
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Pressure from many open bins: prefer consolidating into existing bins
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate: only attractive if existing residuals are large (poor fits elsewhere)
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let mean_r = mean_residual;
        // open a new bin when mean residual is big but unusable, or when few bins open
        if mean_r > 35.0 && post_residual as f64 >= mean_r - 5.0 {
            score -= 20.0;
        } else if open_pressure < 2.0 {
            score -= 10.0;
        } else {
            score += 15.0 + 0.5 * open_pressure;
        }
    }

    // Lookahead: if next item can exactly fill the resulting gap, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_match = (post_residual as f64 - next_item_size as f64).abs();
        if gap_match < 5.0 {
            score -= 25.0;
        } else {
            score += 0.2 * gap_match;
        }
    }

    // Late in the stream: avoid opening bins, squeeze into existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual as f64 - next_item_size as f64;
            // Perfect chain (next item exactly fills remainder) is highly desirable.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            score += 0.3 * gap;
        } else {
            // Next item cannot chain into this bin: penalize leftover dead space.
            score += 8.0;
        }
    } else {
        // Last item: purely minimize post_residual.
        score += 10.0 * fit_ratio;
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * open_bins_count as f64;
        // But if next item is large, a fresh bin may be fine: soften penalty.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Late-stream consolidation: prefer reusing bins as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit bias: reward bins that are already well filled.
    let used = bin_capacity - bin_residual;
    score -= used as f64 * 0.15;

    // Lookahead coupling (k=2): reward leaving space the next item can use,
    // penalize leaving a large unusable remnant.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Dead space relative to what's coming next.
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoids opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Mild pressure toward consolidating into fewer open bins.
    score += (open_bins_count as f64).sqrt() * 0.4;

    // Global residual state: high mean residual means slack is abundant,
    // slightly discourage wasting more of it.
    score += mean_residual * 0.02;

    // Dynamic time horizon: early in the stream, keep bins open-flexible
    // (penalize tight fills less late, more early via a horizon term).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - t) * 3.0;

    // New-bin candidate must not win unless existing bins are truly bad:
    // add a small constant handicap to the empty bin via residual baseline
    // (post_residual is already high for it, so no extra term needed).

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * t * t);

    // Penalize wasted residual more as stream progresses (dead space matters late)
    score += 12.0 * pr_norm * pr_norm * (0.3 + 0.7 * t) * cap;

    // Reward tight fits (small post residual) with smooth quadratic bonus
    score -= 30.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.5 + 0.5 * t);

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + t);
    }

    // Lookahead: reward bins whose residual can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            score -= 6.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.3 * open_bins_count as f64 * (0.2 + 0.8 * t);

    // Deviation from mean residual: prefer bins near the mean (smooth coupling)
    score += 2.0 * (pr - mean_residual).abs() / cap * (1.0 + t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
