        // late in stream, prefer filling existing bins
        score += 15.0 * progress;
        // many open bins with slack -> discourage new bin
        score += (open_bins_count as f64).sqrt() * 2.0 + mean_residual * 0.05;
        // if nothing fits elsewhere, opening is fine
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Tie-break with slight deterministic preference for tighter bins
    score += 0.01 * (bin_residual as f64 - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // realistic future item (items >= 1, but tiny gaps < ~15 are near-worthless)
    // get an escalating penalty.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 15.0 {
            // Nearly unusable sliver: heavy penalty so we avoid creating it.
            score += (15.0 - gap) * 8.0;
        } else if gap < 30.0 {
            // Moderately hard to fill: mild penalty.
            score += (30.0 - gap) * 1.5;
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // If the NEXT item fits exactly in the post residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 + slack * 0.05;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than fragmenting capacity.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.15;

    // Last-chance bin: strongly favor using it before opening a new bin,
    // unless the fit would create a terrible sliver.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: it starts with a huge residual, so the base term
    // already disfavors it; add a mild extra cost that shrinks late in the
    // stream when consolidating is less valuable.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - 0.5 * progress);
    }

    // Slight preference for bins below-mean residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (2-step aware).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 400.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size,
    // enabling a perfect follow-up placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next == 0 {
            score -= 600.0;
        } else if slack_after_next <= 10 {
            score -= 250.0;
        } else {
            // Mild reward proportional to how tight the two-step chain is.
            score -= 80.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Penalize bins that cannot host the next item (dead-space risk).
        score += 60.0;
    }

    // Relative-to-mean coupling: bins tighter than average are good targets.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (residual_f - mean_residual) / mean_residual.max(1.0);
        score += 50.0 * rel;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no tight fit exists anywhere (handled implicitly by score comparisons).
    if bin_residual == bin_capacity {
        score += 200.0;
        if item_size >= 70 {
            score -= 120.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size + item_size <= bin_capacity {
            score -= 100.0; // good pair candidate in a fresh bin
        }
    }

    // Slight stream-progression pressure: later in stream, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual fits the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect two-item packing
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty scaled by gap
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // among many options, prefer fuller bins (small residual waste)
        score += 3.0 * (bin_residual as f64 - post_residual as f64) / item_size.max(1) as f64;
    }

    // New-bin candidate handling: discourage opening a new bin unless the item
    // is large and open bins would leave ugly fragments
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragment_risk = if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        let pressure = (item_size as f64 / bin_capacity as f64).powf(2.0);
        let new_bin_cost = 60.0
            - 25.0 * pressure
            - 15.0 * fragment_risk
            - 10.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64).min(1.0);
        score += new_bin_cost.max(-5.0);
    }

    // Global state: many open bins with high mean residual -> prefer reusing fuller bins
    if open_bins_count > 2 {
        let mean_tight = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 8.0 * mean_tight * (bin_residual as f64 / bin_capacity as f64);
    }

    // Time horizon: early in stream, be picky about tight fits; late, just close gaps
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    // smooth non-linear coupling of post_residual with stream progress
    score += 12.0 * norm_post * norm_post * (0.5 + progress);
    score -= 8.0 * (norm_post * (1.0 - norm_post)) * (1.0 - progress);
    // reward tight fits more as stream progresses
    score -= 6.0 * (1.0 - norm_post) * (1.0 + progress.sin());
    // penalize dead space relative to mean residual
    score += 0.3 * (post - mean_residual).abs() * (0.5 + progress);
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - norm_post);
    }
    // lookahead coupling: favor bins leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score += 0.05 * gap * (1.0 + progress);
        if post >= nxt {
            score -= 3.0 * (nxt / cap) * (1.0 - norm_post);
        }
    } else {
        // last item: strongly prefer minimal post residual
        score += 10.0 * norm_post;
    }
    // mild new-bin preference when many bins are open and fit is poor
    let is_new = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new {
        score += 2.0 + 15.0 * (1.0 - norm_post) * (1.0 - norm_post) - 4.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: residuals divisible into
    // "clean" capacity fractions are more reusable. Classify post_residual
    // by modulo arithmetic against capacity quarters.
    let q = bin_capacity / 4; // 25
    let class = post_residual % q;
    // Residuals landing exactly on a quarter boundary are premium slots.
    if class == 0 && post_residual > 0 {
        score -= 12.0;
    } else if class <= 3 {
        // near-boundary residuals are almost as good
        score -= 6.0 - class as f64 * 2.0;
    } else if class >= q - 3 {
        // just above a boundary: nearly full quarter, also decent
        score -= 3.0;
    } else {
        // dead-space middle of a class: penalize proportionally
        score += (class as f64) * 0.35;
    }

    // --- Integer division threshold: residual "band" via post_residual / q.
    let band = post_residual / q;
    score -= band as f64 * 4.0; // larger usable blocks preferred

    // --- Lookahead coupling: if the next item fits exactly in the post
    // residual, this is a perfect chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // harmonic match: next item's residue class aligns
            let next_class = (post_residual - next_item_size) % q;
            if next_class == 0 {
                score -= 10.0;
            }
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item won't fit here; penalize if we leave a large orphan
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // --- Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // --- New-bin candidate (bin_residual == bin_capacity): only attractive
    // when the open bins are congested or the fit here is terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = (open_bins_count as f64) / (1.0 + mean_residual / bin_capacity as f64);
        // discourage opening new bins early / when few bins open
        score += 30.0 + progress * 10.0 - congestion * 4.0;
        if item_size > bin_capacity * 3 / 4 {
            score -= 20.0; // huge items deserve a fresh bin
        }
    }

    // --- Tight-fit reward: near-perfect fills are excellent.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // --- Mild penalty for spreading across many bins when mean residual
    // is already large (consolidation pressure).
    score += mean_residual * 0.02 - (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements that leave room for a typical future item (nonlinear fit shaping).
    let fit_window = |r: u32| -> f64 {
        let r = r as f64;
        if r >= 10.0 && r <= 60.0 {
            // smooth bump peaking around 30
            let x = (r - 30.0) / 20.0;
            -25.0 * (1.0 - x * x)
        } else {
            0.0
        }
    };
    score += fit_window(post_residual);

    // Lookahead: bonus if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this gap: penalize large leftover gaps mildly
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight fit exists.
    score += 0.8 * open_bins_count as f64 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Relative tightness vs mean residual of open bins.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Late-stream bias: consolidate more aggressively as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless current bin would be nearly empty after.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if the next item exactly fills the post-residual, this is a
    // chained perfect fit -> very strong reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 900.0;
    }

    // If next item can also fit into the post-residual, mildly reward (keeps
    // chain alive); otherwise penalize leaving a gap the next item can't use.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Dead space for the next item: penalize proportionally to how
            // much the next item overshoots the residual.
            score += 15.0 + (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Reward tightness relative to bin residual (small waste fraction).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 50.0 * tightness;

    // Penalize bins far below the mean residual (fragmented outliers), unless
    // this is a last-chance bin.
    if fitting_bins_count > 1 {
        score += (mean_residual - post_residual as f64).max(0.0) * 0.3;
    }

    // Last-chance bin: if this is the ONLY bin that can fit the item, strongly
    // favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate (empty bin): only attractive when current fit is bad
    // or no good fit exists. Penalize opening new bins early in the stream and
    // when open bins exist with reasonable fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = (post_residual as f64) / (bin_capacity as f64);
        // Empty bin gets a moderate score; good fits in open bins (small
        // post_residual) will beat it, poor fits (large post_residual) lose.
        score += 250.0 - 200.0 * progress + 150.0 * fit_quality;
        if open_bins_count == 0 {
            score -= 500.0; // must open a bin
        }
        if next_item_size == item_size {
            score -= 100.0; // same-size next item pairs well in fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 25.0 * (fit_ratio - 0.85) / 0.15;
    } else if fit_ratio > 0.6 {
        score -= 10.0 * (fit_ratio - 0.6) / 0.25;
    }

    // Penalize leaving awkward dead space (small unusable residuals).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 30.0;
        } else if next_item_size as u32 <= post_residual {
            score -= 6.0;
        } else {
            // Next item won't fit here; slight penalty for wasting capacity.
            score += 3.0;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins (keep
    // residuals large and flexible); late in the stream, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;

    // New-bin candidate scoring: attractive early, unattractive late.
    score += new_bin * (15.0 - 40.0 * progress);

    // If many bins are open, discourage opening yet another one.
    score += new_bin * (open_bins_count as f64 * 1.5);

    // Prefer bins with residual below the mean residual (consolidating fuller bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Mild preference for already-open bins vs new bin mid-stream.
    score -= (1.0 - new_bin) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = (r / cap).clamp(0.0, 1.0);

    // Base: prefer tight fits (small post_residual), smoothed polynomial
    let mut score = 100.0 * x * x + 10.0 * x;

    // Non-linear coupling with stream progress: tighten packing later in the stream
    let progress_coupling = prog * (1.0 - prog) * 40.0 * (1.0 - x);
    score -= progress_coupling;

    // Penalize dead space relative to mean residual of open bins (smooth quadratic)
    let dev = r - mean_residual;
    score += 0.05 * dev * dev / (mean_residual + 1.0);

    // Reward scarce fitting bins (last-chance placement), smoothly scaled
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x) * (1.0 - prog);
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln() * x;
    }

    // Lookahead coupling: reward leaving space compatible with next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (r - n).abs();
        score -= 15.0 * (1.0 - gap / cap).max(0.0) * (1.0 - prog);
        // Penalize post_residual that can't fit next item but is large (waste)
        if r < n {
            score += 5.0 * (1.0 - r / cap) * prog;
        }
    }

    // New-bin candidate: neutral-ish baseline, slightly favored early, penalized when open bins are few
    if bin_residual == bin_capacity {
        score = 60.0 - 30.0 * prog + 5.0 * (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into residue classes
    // modulo 10 and modulo 25 (harmonic subdivisions of C=100).
    let post = post_residual;
    let class10 = (post % 10) as f64;
    let class25 = (post % 25) as f64;

    // Penalize post residuals that are "off-harmonic": small nonzero remainders
    // create unusable slivers. Perfect zero or large remainders are better.
    if post > 0 {
        score += 4.0 * (class10 / 10.0) * (1.0 - class10 / 10.0) * 4.0; // peaks at 5
        score += 2.0 * (class25 / 25.0) * (1.0 - class25 / 25.0) * 4.0;
    } else {
        // Perfect fill: strong reward
        score -= 25.0;
    }

    // Tightness reward: the tighter the fit, the better (low post_residual relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Dead-space threshold: post_residual in (0, 10) is nearly unusable for items >= 10
    if post > 0 && post < 10 {
        score += 18.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, mildly prefer bins where the next item also fits
        if next_item_size > 0 && next_item_size <= post {
            score -= 8.0;
        }
    }

    // Lookahead: penalize if next item cannot fit in post residual but could elsewhere
    if next_item_size > post && next_item_size > 0 {
        score += 5.0;
    }

    // New-bin candidate handling: empty bin gets a neutral-but-high baseline so it is
    // only chosen when all open bins fit poorly.
    if bin_residual == bin_capacity {
        // Harmonic prior: expected leftover if item goes into fresh bin
        let fresh_left = (bin_capacity - item_size) as f64;
        score = cap * 0.55 + fresh_left * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 6.0;
        }
        if fitting_bins_count == 0 {
            score -= cap; // must open a new bin
        }
        return score;
    }

    // Stream progression: later in the stream, avoid opening marginal bins;
    // consolidate into existing residuals more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post as f64 / cap);

    // Mean residual coupling: if this bin is far below mean residual, it is a
    // laggard bin — prefer filling it to consolidate.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0 * (mean_residual - bin_residual as f64) / cap;
    }

    // Prefer bins whose residual is harmonically aligned with the item size
    // (residual divisible by item or by common divisors reduces future waste).
    if item_size > 0 && bin_residual % item_size == 0 {
        score -= 5.0;
    }
    if post % 10 == 0 && post > 0 {
        score -= 3.0; // decadal residual is reusable by typical item sizes
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" (small, unusable
    // gap below the minimum plausible item size) is heavily penalized.
    let dead_threshold = 12.0;
    if (post_residual as f64) > 0.0 && (post_residual as f64) <= dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0 + 20.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Perfect-fit lookahead: if the next item exactly fills the post_residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    // If next item fits into the post residual, mild bonus (chaining).
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 5.0;
    }
    // If next item cannot fit in the leftover, mild penalty (wasting chain potential).
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening a new bin
    // by making this bin more attractive (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins with scattered residuals -> prefer
    // consolidating into existing bins rather than opening new ones.
    score += open_bins_count as f64 * 1.5;

    // For the brand-new empty bin candidate (bin_residual == bin_capacity),
    // it should only win when existing bins give bad fits: give it a baseline
    // penalty that scales with how "wasteful" the best existing fit would be.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If mean residual across open bins is large, opening new bin is fine.
        if mean_residual > 40.0 {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheap.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    }

    // Mild preference for bins with residual close to the mean (balance residuals).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain: item + next item fills bin
        } else if next_item_size < post_residual {
            // next item fits too: mild reward proportional to how well it fits
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * frac;
            // extra reward if next item leaves small residue again
            let second_res = post_residual - next_item_size;
            if second_res <= 10 {
                score -= 10.0;
            }
        } else {
            // next item cannot fit here: penalize leaving large dead space
            if post_residual < next_item_size && post_residual < 10 {
                score += 5.0; // small unusable dead space
            }
        }
    } else {
        // last item: just minimize post_residual
        score -= 5.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish score so it's chosen only when
    // no open bin offers a good fit. Penalize opening new bins as stream matures.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 0.55 * bin_capacity as f64 + 60.0 * progress;
        // allow new bin if lookahead chain would be perfect from scratch
        if next_item_size > 0 && (bin_capacity as u32 - item_size) == next_item_size {
            score -= 45.0;
        }
    }

    // Slight preference to fill bins with more usage already (fewer bins overall)
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize large dead space, especially small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Bonus if post-residual is a snug home for the next item.
            let snug = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * snug;
        } else {
            score += 6.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score -= 2.0 * pressure;

    // Time horizon: late in the stream, tighten packing discipline.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate handling: only attractive if no open bin fits well
    // (i.e., current item is large relative to typical residuals).
    if bin_residual == bin_capacity {
        let desperation = (item_size as f64 / bin_capacity as f64 - mean_residual / bin_capacity as f64).max(0.0);
        score = 0.9 * bin_capacity as f64 - 60.0 * desperation + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - br / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + t * (0.8 - 1.6 * t) + t * t * 0.9; // smooth progress modulation
    score += 0.35 * pr * pr / cap * poly;

    // Reward tight fits: non-linear in fill ratio
    score -= 12.0 * fill * fill * fill;

    // Penalize small dead space relative to item size (unusable gap)
    let gap_ratio = pr / it.max(1.0);
    score += 6.0 * gap_ratio * gap_ratio / (1.0 + gap_ratio);

    // Lookahead: reward leaving room for next item, penalize near-miss
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) / cap;
            score -= 5.0 * (1.0 - slack * slack);
        } else {
            score += 3.0 * (1.0 - pr / n);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + t);
    }

    // New-bin candidate: keep it slightly unattractive unless residuals are all poor
    if bin_residual == bin_capacity {
        let tightness = 1.0 - mean_residual / cap;
        score += 8.0 - 10.0 * tightness * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by residue classes.
    // Leftovers in class 0 (multiples of 10) or class 5 are "reusable"; others penalized.
    let pr = post_residual;
    let residue = (pr % 10) as f64;
    if pr > 0 {
        let class_penalty = match pr % 10 {
            0 => -14.0,
            5 => -7.0,
            1 | 9 => 9.0,
            2 | 8 => 6.0,
            3 | 7 => 4.0,
            _ => 2.0,
        };
        score += class_penalty;
    }

    // Integer-division threshold: very small leftovers are dead space.
    let q = pr / 10;
    if q == 0 && pr > 0 {
        score += 30.0; // dead space < 10
    } else if q >= 8 {
        score -= 6.0; // large leftover, still flexible
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            // harmonic compatibility: does next_item_size divide/align with pr?
            if pr % next_item_size == 0 {
                score -= 12.0;
            }
            score -= 4.0;
        } else {
            // next item cannot use this leftover: penalize proportionally to mismatch
            score += ((next_item_size - pr).min(20)) as f64 * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: brand-new empty bin should only win when current
    // bin fit is terrible. Give it a baseline cost plus openness pressure.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in stream with many open bins, opening new bins is costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0 + (open_bins_count as f64) * 1.5;
    } else {
        // Mild bonus for tighter existing bins relative to mean residual.
        let diff = mean_residual - bin_residual as f64;
        score += diff.clamp(-20.0, 20.0) * 0.4;
    }

    // Modulo coupling between item_size and bin_capacity fractions.
    let frac = (bin_residual as f64) / (bin_capacity as f64);
    if frac > 0.9 {
        score += 3.0; // nearly full bin: leave it alone unless great fit
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead = if post_residual > 0 && post_residual < 10 {
        (10 - post_residual) as f64 * 6.0
    } else if post_residual == 0 {
        -30.0 // perfect fit reward
    } else {
        0.0
    };
    score += dead;

    // Reward bins whose residual matches the next item (lookahead chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= (10.0 - gap) * 3.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual too small for the lookahead item: penalize as dead space.
        score += post_residual as f64 * 2.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 8.0 + mean_residual * 0.5;
    } else {
        // Slight preference for tighter (smaller-residual) bins among open ones.
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: keep it attractive only when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin; the penalty shrinks when this is the only fitting option.
        score += 40.0 - 25.0 * (fitting_bins_count == 1) as f64;
        // If the next item exactly fills a fresh bin alongside this one, opening is attractive.
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64 - next_item_size as f64).abs() < 1e-9 {
            score -= 30.0;
        }
        return score;
    }

    // Aggressive 2-step lookahead: perfect match between post_residual and next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 35.0 / (1.0 + diff); // strong reward for exact/very close 2-step match
        if diff == 0.0 {
            score -= 20.0; // exact chain: item + next item perfectly fill the bin
        }
    } else {
        // Last item: prefer minimal waste directly.
        score -= 15.0;
    }

    // Penalize creating small unusable dead space relative to the minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Prefer bins tighter than the current mean residual (good packing density).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early in the stream, slightly encourage bin consolidation to keep open set small.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Strong reward for very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Penalize residual dead space that is too small to fit any plausible item
    // (items >= 1..=100, but small residuals < typical minimum sizes are wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead sliver
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // this placement chains beautifully; reward it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as u32) >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / cap);
            if gap == 0.0 {
                score -= 25.0; // perfect chain
            }
        } else {
            // Next item won't fit here regardless; residual becomes dead space
            // relative to the lookahead. Penalize proportionally.
            score += 8.0 * (post / cap);
        }
    } else {
        // Last item: prefer any bin, mild bonus to close out bins.
        score -= 5.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many fitting bins => competition; prefer the tightest, so scale base residual.
    if fitting_bins_count > 1 {
        score *= 1.0 + 0.05 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate logic: opening a new bin is only good when the current
    // item fits poorly everywhere. Compare fit ratio.
    let fit_ratio = item / bin_residual.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Fresh bin: neutral residual = cap - item. Penalize unless item is large
        // relative to capacity (large items deserve fresh bins) or fit is bad elsewhere.
        let fill = item / cap;
        score += 45.0 * (1.0 - fill); // cost of opening a bin, discounted for big items
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // If mean residual across open bins is high, bins are empty-ish; opening
        // another is wasteful.
        score += (mean_residual / cap).min(1.0) * 15.0;
    } else {
        // Using an existing bin with a good fit ratio is great.
        score -= 20.0 * fit_ratio;
        // Prefer filling bins that are already mostly full (consolidation).
        let used_frac = 1.0 - bin_residual as f64 / cap;
        score -= 10.0 * used_frac;
    }

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, pack aggressively into whatever fits.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * t * fit_ratio;   // late-stream: reward tight fits more
    score += 10.0 * (1.0 - t) * (post / cap); // early-stream: penalize large leftovers

    // Global pressure: many open bins with low mean residual => consolidate hard.
    if open_bins_count > 3 && mean_residual < 30.0 {
        if !is_new_bin {
            score -= 12.0;
        } else {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // tight fits (small post_residual) are rewarded more strongly later in the stream.
    let tightness = 1.0 - post / cap;
    let progress_weight = 0.5 + 0.5 * progress;
    score -= 8.0 * tightness * tightness * progress_weight;

    // Penalize post_residuals that are too small to be useful later (dead space),
    // with a smooth quadratic valley around a moderately useful residual.
    let useful = 0.25 * cap;
    let dead = (post - useful) / cap;
    score += 6.0 * dead * dead;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Mild crowding penalty spread smoothly over alternatives.
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere else.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = (bin_residual as f64 - item_size as f64) / cap; // 0 for perfect fit
        score = post + 4.0 - 6.0 * poor_fit * poor_fit;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Lookahead: reward leaving room for the next item when it would otherwise not fit.
    if next_item_size > 0 {
        let need = next_item_size as f64;
        if post >= need {
            score -= 3.0 * (1.0 - post / cap) * (need / cap);
        } else {
            score += 2.0 * (need - post) / cap;
        }
    }

    // Mild preference for reducing the number of open bins when residuals are balanced.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * (1.0 - (mean_residual / cap).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of 10, or small enough to matter) are favored.
    let pr = post_residual;
    if pr > 0 {
        // Class A: post_residual divisible by 10 -> highly reusable slot.
        if pr % 10 == 0 {
            score -= 12.0;
        }
        // Class B: post_residual divisible by 5 but not 10 -> mildly reusable.
        else if pr % 5 == 0 {
            score -= 5.0;
        }
        // Class C: dead space - tiny leftovers are wasted capacity.
        if pr < 10 {
            score += (10 - pr) as f64 * 1.5;
        }
    } else {
        // Perfect fill is the ideal outcome.
        score -= 40.0;
    }

    // Integer-division harmonic tier of the fill ratio.
    let fill_tier = (item_size * 4) / bin_capacity; // 0..=3 quarters
    score -= fill_tier as f64 * 6.0;

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward this placement (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // Next item still fits: bonus scaled by how well it nests.
            score -= (next_item_size as f64 / pr.max(1) as f64) * 10.0;
        } else {
            // Next item cannot use this bin's leftover: mild penalty.
            score += 4.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless current bins are crowded
    // or this is early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0
            + mean_residual * 0.25
            + (open_bins_count as f64) * 2.0
            - progress * 10.0;
    }

    // Slight preference for tighter bins overall.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: hugely reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead = post_residual > 0 && post_residual < 10;
    if dead {
        score += 60.0 + 8.0 * (10 - post_residual) as f64;
    }

    // Mid-size residual (10..=20) is moderately useful; slight penalty to prefer tighter fits.
    if post_residual >= 10 && post_residual <= 20 {
        score += 5.0;
    }

    // Reward bins whose residual is "shaped" for the next item (lookahead coupling).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 15 {
        score -= 30.0;
    }

    // Open-bin pressure: penalize opening a new bin when existing bins fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Opening new bin is only acceptable if alternatives are poor fits.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 25.0 + 15.0 * (1.0 - progress) + 3.0 * open_bins_count as f64;
        }
        // If no open bin fits, new bin must win: keep score low.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else if fitting_bins_count == 1 {
        // This bin is the last chance: strongly favor using it.
        score -= 45.0;
    }

    // Slight preference for bins below mean residual (tighter bins get filled first).
    score += 0.5 * (post_residual as f64 - mean_residual).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/near-exact fit
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if next_item_size <= post_residual {
            score -= 80.0 - diff * 1.5; // perfect chain match heavily rewarded
        } else {
            score += 15.0 + diff * 0.5; // next item cannot follow here
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Penalize large dead space creation
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize mildly so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 35.0 + 0.3 * open_bins_count as f64;
    }

    // Late-stream consolidation: favor using existing bins more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.3 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 8.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Last-chance bonus: only one bin fits the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins -> prefer filling existing ones.
    let pressure = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
    score -= 3.0 * pressure.min(20.0);

    // Time horizon: early in stream, be more willing to open new bins (penalize less);
    // late in stream, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, modulated by progress and mean residual.
        let mut new_bin_cost = 55.0 + 70.0 * progress;
        if mean_residual > item_size as f64 + 15.0 {
            new_bin_cost += 20.0; // existing bins have plenty of room; don't open new
        }
        if fitting_bins_count == 0 {
            new_bin_cost = 5.0; // forced
        }
        score += new_bin_cost;
    } else {
        // Existing bin: late-stream consolidation bonus.
        score -= 15.0 * progress;
    }

    // Prefer bins whose residual is close to mean (balanced packing) mid-stream.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Smooth non-linear penalty on residual waste, amplified by stream progress
    let norm_post = post / cap;
    score += 6.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item) with polynomial coupling
    let tightness = 1.0 - (post / cap);
    score -= 4.0 * tightness * tightness * tightness * (1.0 + progress);

    // Lookahead: penalize residuals that cannot fit the next item (smoothly)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post < nx {
            let gap = (nx - post) / cap;
            score += 5.0 * gap * (1.0 + progress);
        } else {
            // reward leaving room exactly usable by next item
            let fit_q = (post - nx) / cap;
            score -= 2.5 * (1.0 - fit_q).max(0.0) * (1.0 - fit_q).max(0.0);
        }
    } else {
        // last item: heavily reward zero waste
        score -= 8.0 * (1.0 - norm_post) * (1.0 - norm_post);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 3.0;
    }

    // Crowd coupling: many open bins with high mean residual -> discourage wasting space
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 2.0 * crowd * ((post - mean_residual) / cap).abs();

    // New-bin candidate: prefer keeping it closed unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) + 2.0 * (item / cap);
        if next_item_size > 0 {
            let share = item + next_item_size as f64;
            if share >= cap {
                score -= 3.0; // good pair candidate for fresh bin
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Harmonic class of post_residual: dead space vs reusable space.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Small post_residual classes are usable by typical small items.
        let cls = post_residual / 10; // harmonic decade class
        score += (cls as f64).powi(2) * 1.5;
        // Penalize odd/awkward residuals (not multiples of 5 or 10)
        if post_residual % 10 != 0 {
            score += 4.0;
            if post_residual % 5 != 0 {
                score += 3.0;
            }
        }
    }

    // Reward when post_residual can exactly host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 40.0; // chained perfect fit
        } else {
            score -= 15.0 - (slack as f64) * 0.2;
        }
    } else if next_item_size > 0 {
        // Lookahead cannot follow in this bin: penalize, worse if item was big.
        score += 6.0 + (next_item_size as f64) * 0.1;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current residuals are poor.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        let new_bin_bonus = 25.0 + mean_gap * 0.8 + (open_bins_count as f64).powf(0.5) * 3.0 + progress * 10.0;
        score -= new_bin_bonus;
        // Discourage opening a new bin for small items early on.
        if item_size < 40 {
            score += 12.0 * (1.0 - progress);
        }
    }

    // Mild pressure to consolidate into fewer bins.
    score -= 1.0 / (1.0 + open_bins_count as f64);

    // Prefer filling bins that are already substantially full.
    let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_frac * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: worst outcome.
            score += 60.0;
        } else if post_residual <= 20 {
            // Only tiny items could use it: strong penalty.
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin size.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Pressure from number of open bins: when many bins are open, prefer
    // consolidating into existing bins rather than opening more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.15 + 0.35 * progress);
    score += bin_pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here anyway: slight penalty for wasting capacity.
            score += 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mean-residual coupling: prefer bins below the mean residual (tighter bins first),
    // keeping larger residuals available for larger future items.
    score += 0.1 * (mean_residual - post_residual as f64);

    // Mild preference for opening a fresh bin early in the stream when the current
    // bin would be left with a large awkward residual.
    if post_residual > 50 && progress < 0.3 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a convex penalty
    // so that leaving a small-but-annoying dead space is punished extra.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // --- 2-step lookahead: does the next item fit into the post-residual? ---
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            // Excellent: this bin can host both current and next item.
            // Reward proportionally to how snugly the next item matches.
            let slack_after_next = post_residual - next_item_size;
            score -= 60.0 + 0.5 * (slack_after_next as f64);
            // Extra reward for an exact two-item chain fill.
            if slack_after_next == 0 {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here; penalize if post_residual is a
            // "useless" sliver that no plausible item (>=1) can use well.
            let gap = (next_item_size - post_residual) as f64;
            // Small gap => near miss, mildly frustrating; large gap means
            // the residual is still broadly usable, so penalize less.
            if post_residual < 10 {
                score += 25.0; // dead space: nothing in [1,100] range likely fits well
            } else {
                score += 0.15 * gap.min(60.0);
            }
        }
        // Coupling with mean residual: if this bin's post-residual deviates
        // favorably from the fleet mean, reward it (keeps residual spread tight).
        let dev = pr - mean_residual;
        score += 0.10 * dev;
    } else {
        // Last item: just minimize waste.
        score += 0.2 * pr;
    }

    // --- Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin. ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit badly
        // (large post_residual everywhere) or many bins are already open.
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = bin_capacity as f64
            - 25.0 * mean_tightness
            - 3.0 * (open_bins_count as f64).sqrt();
        // If next item is huge, a fresh bin is more attractive.
        if next_item_size >= 70 {
            score -= 15.0;
        }
        // Never open a new bin when this is the only fitting bin.
        if fitting_bins_count == 1 {
            score += 200.0;
        }
    }

    // Mild preference for consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual already does this); amplify near-perfect fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that is too small to likely hold a future item (items >= 1,
    // so any residual can hold something; instead penalize residuals just below common sizes).
    let dead = if post_residual > 0 && post_residual < 10 { 25.0 } else { 0.0 };
    score += dead;

    // Lookahead: strongly reward bins whose post-residual can host the next item exactly well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 / (1.0 + slack);
        } else {
            score += 4.0; // next item won't fit here; deprioritize
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
        if post_residual < 5 { score += 12.0; } // unless it creates near-zero dead space
    }

    // New-bin candidate handling: opening a new bin is expensive; make it attractive only
    // when item is large relative to capacity or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let load_frac = item_size as f64 / bin_capacity as f64;
        // Prefer new bins for large items early on; penalize when many bins are open with slack.
        score += 3.0 + 20.0 * (1.0 - load_frac);
        score += 0.15 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 5.0; // there exist bins with room; don't open a new one
        }
    }

    // Time horizon: later in the stream, prefer consolidating (favor fuller bins more strongly).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;

    // Global pressure: many open bins -> discourage spreading; few bins -> mild new-bin tolerance.
    score += 0.05 * (open_bins_count as f64).powf(1.2) * (1.0 - tightness);

    // Mean-residual coupling: if this bin's residual deviates favorably from mean (smaller), reward.
    score += 0.1 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Smooth polynomial penalty shaping: penalize large residuals more as stream progresses
    let poly = norm_pr * norm_pr * (1.0 + progress * 2.0) + norm_pr * (1.0 - progress);
    score += 30.0 * poly;

    // Reward tight fits (small post_residual) with smooth cubic decay
    let tight = (1.0 - norm_pr).powi(3);
    score -= 25.0 * tight * (0.5 + progress);

    // Penalize dead space relative to mean residual (non-linear interaction)
    let dead = (pr - mean_residual) / cap;
    score += 15.0 * dead * dead.abs();

    // Lookahead coupling: favor bins whose post_residual fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 20.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 10.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - norm_pr);
    }

    // Mild penalty for proliferating bins late in the stream
    score += open_bins_count as f64 * progress * 0.5;

    // Slight preference for filling larger fraction of the bin
    score -= 10.0 * fit * fit;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
