    } else if post_residual <= 10 {
        score -= 35.0;
    } else if post_residual <= 15 {
        score -= 18.0;
    }

    // Penalize dead space by class: classes 0..3
    score += match class {
        0 => 0.0,
        1 => 4.0,
        2 => 10.0,
        _ => 18.0,
    } as f64;

    // Modulo coupling: residual divisible by common item sizes is reusable
    if post_residual > 0 {
        let reusable = (post_residual % 10 == 0) as i32
            + (post_residual % 20 == 0) as i32
            + (post_residual % 25 == 0) as i32;
        score -= 8.0 * reusable as f64;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // next item won't fit here; penalize more if post_residual is large waste
            score += 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-ish score so it's chosen only when
    // existing fits are poor; scale with stream progression
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 40.0 + 20.0 * progress;
        if item_size > bin_capacity / 2 {
