        }
    }

    // Mild preference for tighter bins overall
    score += 0.02 * (mean_residual - post_residual as f64);

    // Integer division threshold: residual in (10,20) is prime dead space
    if post_residual > 10 && post_residual / 10 == 1 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible future item (size 1) are still "usable" in principle, but
    // residuals below a practical threshold rarely get filled.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        // Heavy penalty proportional to how "useless" the gap is.
        score += 60.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }

    // Moderate penalty for medium gaps that likely can't fit next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward using the tightest bin: closeness of fit.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly prefer placing here over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0 + 3.0 * open_bins_count as f64;
        // If existing bins would leave bad gaps, opening fresh is fine.
        if fitting_bins_count >= 1 {
            let worst_gap_ok = mean_residual > item_size as f64 * 1.5;
            if worst_gap_ok {
                score += 25.0;
            }
        }
        // Early in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits: strongly discount small post_residual.
    let exactness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * exactness * exactness;

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            (next_item_size - post_residual) as f64 * 1.5
        };
        score -= 45.0 * (-gap / 12.0).exp();
        // If post_residual is exactly next item size, huge reward.
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Penalize post_residual too small for next item (dead space for lookahead)
        if post_residual < next_item_size && post_residual > 0 {
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average.
    score += 0.6 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: penalize opening a new bin, unless residuals are fragmented
    // (many open bins with poor fit potential) or the fit here is very poor.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.35;
        let mut penalty = 90.0;
        if fragmentation < 0.15 { penalty -= 55.0; }      // open bins nearly full -> new bin ok
        if poor_fit && fragmentation < 0.3 { penalty -= 25.0; }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size && post_residual < next_item_size {
            penalty -= 15.0; // lookahead suggests a fresh bin is more flexible
        }
        score += penalty;
    }

    // Late in stream: consolidate aggressively, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post-residual.
    let cap_f = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap_f;
    score -= 6.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Lookahead: reward if next item fits into post_residual (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 4.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / cap_f;
        } else {
            // Penalize leaving a dead gap next item cannot use.
            score += 3.0 * (post_residual as f64) / cap_f;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Cost of opening a new bin grows with number of open bins and progress.
        let mut open_cost = 12.0 + 2.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);
        // If this bin is the only fitting bin among open bins, opening is wasteful.
        if fitting_bins_count == 1 {
            open_cost += 20.0;
        }
        // If mean residual is small (bins nearly full), opening a new bin is fine.
        open_cost -= 0.5 * mean_residual.max(0.0);
        score += open_cost;
    }

    // Mild preference for fuller bins when many bins are open (bin consolidation).
    if open_bins_count > 3 {
        score += 0.05 * (open_bins_count as f64) * (bin_residual as f64) / cap_f;
    }

    // Time-horizon modulation: later in stream, be more conservative with gaps.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * progress * (post_residual as f64) / cap_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, waste is cheap; late, waste is heavily penalized.
    let waste_weight = 0.5 + 2.5 * progress * progress;
    score += waste_weight * fit_ratio * fit_ratio * cap * 0.1;

    // Smooth interaction: penalize residuals that are too small to be useful,
    // scaled by how far along the stream we are.
    let unusability = 1.0 - (fit_ratio * 4.0).min(1.0);
    score += progress * unusability * unusability * 15.0;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * progress * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 10.0 * progress;
    }

    // Scarcity pressure: when few bins fit the item, mildly favor them.
    if fitting_bins_count > 0 {
        score -= (1.0 / fitting_bins_count as f64) * 3.0;
    }

    // Lookahead: if the next item could use the post-residual, reward leaving it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= (1.0 - ((pr - nxt) / cap)) * 4.0 * (0.5 + progress);
        } else {
            score += (nxt - pr) / cap * 6.0;
        }
    }

    // Dampen preference for bins far from the mean residual (smooth coupling).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev.abs() * dev.abs() * 5.0 * (0.5 + progress);

    // Mild penalty for opening a brand-new bin when other bins fit,
    // softened early in the stream when bin count is low.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0 * (1.0 - progress) * (1.0 - 1.0 / (open_bins_count as f64 + 1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of small divisors) are more attractive.
    let pr = post_residual as u32;
    let class = if pr == 0 {
        0.0 // perfect fit: huge reward
    } else if pr % 25 == 0 {
        1.0
    } else if pr % 10 == 0 {
        2.0
    } else if pr % 5 == 0 {
        3.0
    } else {
        4.0
    };
    score += class * 6.0;

    // Perfect closure bonus
    if pr == 0 {
        score -= 60.0;
    }

    // Next-item lookahead: reward residuals that exactly fit the next item
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 35.0;
        } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 12.0;
        } else if pr < next_item_size {
            // dead space relative to lookahead
            score += (next_item_size - pr) as f64 * 0.4;
        }
    }

    // Last-chance bin: strong pull to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is huge
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac < 0.5 {
            score += 45.0;
        } else {
            score += 10.0;
        }
    }

    // Prefer packing into bins with below-average residual (balance classes)
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Integer-division threshold: small post-residuals are dead space
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 1.5;
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Dead space that cannot fit the lookahead item is worse than average.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can still host the next item.
        score -= 6.0;
        // Extra reward for near-perfect two-item packing.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Reward tight fits (small post_residual relative to residual).
    let tightness = if bin_residual > 0 { (item_size as f64) / (bin_residual as f64) } else { 0.0 };
    score -= 20.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit
    // is genuinely good; pressure grows with open_bins_count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with below-average residual (more filled bins first).
    score -= (mean_residual - post_residual as f64) * 0.25;

    // New-bin candidate: only attractive when it enables a good lookahead fit
    // or current bins are nearly saturated.
    if bin_residual == bin_capacity {
        let base = 55.0 + 0.5 * open_bins_count as f64;
        let lookahead_bonus = if next_item_size > 0 && (bin_capacity as f64 - item_size as f64 - next_item_size as f64).abs() < 1.0 { -20.0 } else { 0.0 };
        let saturation = if mean_residual < item_size as f64 * 1.5 { -18.0 } else { 0.0 };
        score = base + lookahead_bonus + saturation + post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits perfectly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            let waste_after = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - waste_after / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving a large orphan residual
            let orphan = post_residual as f64;
            score += 0.15 * orphan * (next_item_size as f64 / bin_capacity as f64);
        }
    } else {
        // last item: minimize residual tightly
        score += 0.5 * post_residual as f64;
    }

    // Prefer tight fits relative to mean residual
    let tightness = (post_residual as f64) - mean_residual;
    score += 0.08 * tightness;

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let desperation = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        score += 25.0 + 10.0 * progress - 40.0 * desperation * (fitting_bins_count == 0) as i32 as f64;
        // penalize new bins when a decent fit exists elsewhere
        if fitting_bins_count > 0 {
            let best_gap = mean_residual - item_size as f64;
            if best_gap < 20.0 {
                score += 15.0;
            }
        }
    }

    // Slight preference for filling nearly-full bins early
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (best-fit core).
    score += (post_residual as f64 / bin_capacity as f64).powf(2.5) * 40.0;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Penalize creating dead space the next item cannot use.
            score += (post_residual as f64).min(next_item_size as f64) * 0.6;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer fuller bins relative to the fleet's average residual.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Early in stream: mild preference to consolidate into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 18.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Discourage leaving residuals that no plausible item (>=1) can exploit well.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: wasted space after placement, softly compressed
    let mut score = (pr / cap).powf(1.7) * cap;

    // Reward tight fits (fit_ratio near 1), non-linearly
    score -= 18.0 * fit_ratio.powf(3.0);

    // Smooth coupling: post_residual matters more as stream progresses
    score += 12.0 * progress * (pr / cap);

    // Penalize leaving residuals that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 8.0 * ((nx - pr) / cap).powf(1.5);
        } else {
            score -= 4.0 * (pr / cap) * (nx / cap);
        }
    }

    // Last-chance bin bonus: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize crowding when many bins are open but residual is large
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (pr / cap).powf(2.0);

    // Divergence from mean residual: prefer bins with smaller residual (tighter bins)
    score += 5.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer minimal waste.
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Harmonic class of post_residual: classify leftover space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / cap * 8.0).floor(); // 8 harmonic classes of residual
    // Dead-space penalty: residual classes that few item sizes can use.
    let dead_penalty = match class as u32 {
        0 => -30.0,          // perfect fit
        1 => 10.0,           // tiny unusable sliver
        2 => 15.0,
        3 => 8.0,
        4 => 0.0,            // ~half capacity: highly reusable
        5 => 4.0,
        6 => -6.0,
        _ => -10.0,          // large residual, still flexible
    };
    score += dead_penalty;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item cannot use this residual; penalize small leftovers more
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: avoid opening a new bin when only one bin fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer filling bins when many bins are open (reduce bin count pressure).
    score -= (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 - pr) * 0.02;

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual * 0.05;
    } else {
        // reward using bins whose residual deviates from mean (diversity preservation)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.03;
    }

    // Stream progression: early on be conservative, later pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (1.0 - pr / cap);

    // Integer-division threshold: residuals divisible by common item sizes are valuable.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 20 == 0) {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..)
    // can use efficiently are heavily penalized. Treat very small gaps as waste.
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable dead space: harsh penalty.
        score += 45.0;
    } else if post_residual < 20 {
        // Marginal gap: mild penalty.
        score += 12.0;
    } else {
        // Usable residual: mild reward proportional to size.
        score -= 4.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins, but less strongly
    // as the stream progresses (avoid overpacking early).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 - progress);

    // Penalize bins far below the mean residual only mildly (keep spread tight).
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate: allow opening a fresh bin only when current item is large
    // and would leave a big usable gap anyway, or when many bins are still slack.
    if bin_residual == bin_capacity {
        if item_size >= 50 {
            score += 8.0; // default: prefer existing bins slightly
        } else {
            score += 25.0; // small items should go into open bins
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits elsewhere: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
