    }

    // Penalize leaving tiny unusable slivers
    if post_residual > 0 && next_item_size > 0 && post_residual < 10.min(next_item_size) {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is consumed almost exactly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can never be reused by typical items (post_residual < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate handling: only attractive when no good open bin exists.
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            // Last-chance bin beats opening a new bin.
            score += 15.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Last-chance bonus for the single fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild penalty when this bin's residual is far above the mean (fragmented bin).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // Prefer filling bins with larger residuals when many bins are open (bin consolidation).
    score -= 0.02 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: raw waste after placement
    let mut score = pr;

    // Smooth non-linear waste penalty: quadratic in normalized fill usage
    let fill = it / cap;
    score -= 18.0 * fill * fill * (1.0 + progress);

    // Tight-fit reward: smooth sigmoid-like coupling of post_residual with item size
    let tight = 1.0 - pr / cap;
    score -= 10.0 * tight * tight * tight;

    // Lookahead: penalize post_residual that cannot host the next item (dead space),
    // smoothly scaled by how close the gap is to next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += 14.0 * gap * (1.0 - progress * 0.5);
        } else {
            // reward leaving room exactly usable by the next item
            let snug = 1.0 - ((pr - nxt) / cap);
            score -= 6.0 * snug * snug * snug * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.3);
    } else if fitting_bins_count > 2 {
        // many alternatives: mild penalty to keep selective (best-fit-like) behavior
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Coupling with mean residual: prefer bins below mean residual early (diversify),
    // prefer bins above mean later (consolidate)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * (progress - 0.5);

    // New-bin candidate: neutral-ish baseline so it wins only when open bins are poor.
    // Penalize opening bins as stream progresses, unless residual of this bin would be tiny.
    if bin_residual == bin_capacity {
        score += 6.0 + 14.0 * progress - 20.0 * fill * fill;
    }

    // Late-stream consolidation: reward filling existing bins harder
    score -= 5.0 * progress * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 and mod 25.
    let pr = post_residual;
    let class10 = (pr % 10) as f64;
    let class25 = (pr % 25) as f64;

    // Penalize residuals that are small but not zero (unusable dead space).
    if pr > 0 && pr < 10 {
        score += 12.0;
    }
    // Perfect fit reward.
    if pr == 0 {
        score -= 20.0;
    }

    // Harmonic bonus: post_residual exactly divisible by common item sizes.
    if pr >= 10 {
        if pr % 10 == 0 { score -= 4.0; }
        if pr % 20 == 0 { score -= 2.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 3.0; }
    }

    // Penalize fractional dead space (non-multiple residues) proportionally.
    score += class10 * 0.3 + class25 * 0.15;

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            score -= 6.0;
            // Harmonic match of next item with post residual.
            if pr % next_item_size.max(1) == 0 { score -= 4.0; }
        } else {
            // Next item cannot use the leftover: penalize large leftovers mildly.
            score += (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so that
    // open bins with reasonable fits are preferred, but a bad fit in an open
    // bin can still lose.
    if bin_residual == bin_capacity {
        score = cap - (item_size as f64);
        // Bias against opening new bins when stream is late and bins are few.
        score += 8.0;
        if next_item_size > 0 && next_item_size <= pr && pr >= 10 {
            score -= 2.0; // fresh bin can host both items
        }
        if open_bins_count == 0 { score -= 30.0; }
    }

    // Mild penalty for spreading across many bins when mean residual is high.
    if bin_residual < bin_capacity {
        score += (mean_residual - post_residual as f64).abs() * 0.02;
    }

    // Slight pressure to consolidate early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Dead space that cannot fit a typical future item is penalized proportionally.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 {
        let unusable = (10.0_f64).min(post_residual as f64);
        score += unusable * (1.5 + 2.5 * progress);
    }

    // Reward tight fits strongly.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness;

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bins pressure: when many bins are open, prefer filling existing ones.
    let pressure = open_bins_count as f64 / (1.0 + open_bins_count as f64).ln();
    score += 0.0; // baseline
    if bin_residual == bin_capacity {
        // New bin candidate: penalize when pressure is high or decent fits exist.
        score += 25.0 + 3.0 * pressure;
        if fitting_bins_count > 0 {
            score += 20.0 * fitting_bins_count.min(5) as f64;
        }
    } else {
        // Existing bin: reward being chosen, more so under pressure.
        score -= 2.0 * pressure;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item almost fits but not quite, slight penalty (creates near-dead space).
    if next_item_size > post_residual && next_item_size - post_residual.min(next_item_size) < 5 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Prefer bins whose residual is below the mean residual (filling emptier-first hurts).
    if bin_residual as f64 > mean_residual {
        score += 4.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit relative to mean residual.
    score -= 0.5 * mean_residual;

    // 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if diff < 1.0 {
            score -= 60.0; // perfect 2-chain: item + next fills bin
        } else if post_residual as f64 >= next {
            // next item fits afterwards; reward proportional closeness
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // dead space that cannot host the next item
            score += 0.8 * diff;
        }
    } else {
        // last item: just prefer minimal leftover
        score += 0.2 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good chain.
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 && next_item_size <= bin_capacity {
            (bin_capacity - next_item_size) as f64
        } else {
            0.0
        };
        // Penalize new bins slightly; escalate with number of open bins.
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But if post_residual of a new bin would perfectly chain the next item,
        // opening a fresh bin is excellent.
        if next_item_size > 0 && (bin_capacity - next_item_size) == item_size {
            score -= 70.0;
        }
        let _ = best_possible;
    }

    // Mild stream-progression adaptation: early on, be conservative about
    // fragmenting bins; late, pack greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit preference: reward tight fits.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - tightness).powi(3);

    // Penalize tiny dead space that nothing small can reuse; exact fits heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score += 15.0; // dead space below min item size
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits perfectly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let next_leftover = post_residual - next_item_size;
            score -= 8.0 * (1.0 - next_leftover as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: slight penalty for small leftovers.
            score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: make empty bin attractive only when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, modulated by stream progress and existing bins.
        score += 20.0 + 5.0 * (step_index as f64 / total_items.max(1) as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin can also host next item comfortably
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    } else if post_residual < 10 && fitting_bins_count > 1 {
        // Prefer not to waste a bin that could serve a larger future item if alternatives exist.
        score += 6.0;
    }

    // Global state coupling: when many open bins with slack, prefer consolidating into
    // below-mean-residual bins (fill the emptier ones less).
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 10.0 * dev; // prefer bins with residual below mean (tighter bins)
    }

    // Mild time-horizon term: late in the stream, prioritize closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: strongly prefer small post-residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr + 60.0 * norm_pr * norm_pr + 40.0 * norm_pr.powi(3);

    // Stream-progress coupling: tighten tolerance as stream progresses
    score *= 1.0 + 0.8 * progress * norm_pr;

    // Perfect / near-perfect fits get extra reward, amplified late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness.powi(4) * (0.5 + progress);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let waste = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - waste / cap);
    } else if next_item_size > 0 {
        score += 6.0 * (next_item_size as f64 / cap);
    }

    // Penalize bins far below mean residual (fragmented outliers), smooth coupling
    score += 3.0 * ((mean_residual - pr) / cap).abs().powi(2);

    // Mild penalty on new-bin candidate scaled by how many bins are already open
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful"
    // for common future item sizes (multiples of 10, 20, 25, 50).
    let post = post_residual;
    if post > 0 {
        let mut harmony_bonus = 0.0;
        if post % 10 == 0 { harmony_bonus += 6.0; }
        if post % 20 == 0 { harmony_bonus += 4.0; }
        if post % 25 == 0 { harmony_bonus += 3.0; }
        if post % 50 == 0 { harmony_bonus += 5.0; }
        score -= harmony_bonus;
        // Dead space penalty: residuals too small to hold the minimum item (1..=100)
        if post < 10 {
            score += 25.0; // nearly unusable sliver
        } else if post < 20 {
            score += 8.0;
        }
    } else {
        score -= 20.0; // perfect closure
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 18.0;
        } else if next_item_size <= post {
            let slack = (post - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit here; slight penalty proportional to overflow
            score += 4.0;
        }
    }

    // Integer-division threshold on post_residual quartiles.
    let q = post / (bin_capacity / 4);
    match q {
        0 => score += 6.0,   // < 25% residual left
        1 => score += 1.0,
        2 => score -= 1.0,
        _ => score -= 2.0,   // roomy bin
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when open bins are quite full on average
    // and this placement would leave a bad (non-harmonic) residual.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / cap;
        score = cap - post as f64; // = 0 for empty bin baseline
        // Penalize new bin early in stream or when open bins still roomy
        score += (open_bins_count as f64) * 3.0;
        score -= avg_fill * 30.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    } else {
        // Mild preference for tighter (fuller) existing bins
        score += (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Mean residual coupling: if this bin is much tighter than average, reward.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: small gaps (1..=9) are nearly unusable
    // since future items are >= 1 but useful fill is rare; penalize hard.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0;
    } else if post_residual > 9 && post_residual <= 19 {
        score += 12.0;
    }

    // Reward tight fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead space is worse late in the stream when bins can't be amortized.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * 0.5 * progress;

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Lookahead: if next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 9 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New empty bin candidate: only attractive if no tight fit exists elsewhere;
    // make it moderately expensive but allow it when residuals are large/wasted.
    if bin_residual == bin_capacity {
        score += 15.0;
        score -= 0.3 * mean_residual;
    }

    // Prefer bins whose residual is close to the item (best-fit coupling).
    score += 0.4 * ((bin_residual as f64 - item_size as f64) - (post_residual as f64)).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead fit: post_residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-match lookahead: next item could almost fill the remainder.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 200.0 / (1.0 + gap);
        // Penalize large leftover relative to next item size (dead space).
        if post_residual < next_item_size {
            score += 30.0;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 500.0;
    }

    // Last-chance bin: only bin that can fit this item — reward strongly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 400.0;
    }

    // Prefer bins with residual below mean (tight bins get tighter).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Penalize new-bin opening unless residuals across open bins are all poor.
    if bin_residual == bin_capacity {
        let poor_fit = (mean_residual - item_size as f64).max(0.0);
        score -= 50.0 - poor_fit.min(50.0);
        // Early in stream, opening bins is cheap; late, avoid fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 * (1.0 - progress);
    }

    // Small absolute post_residual is good (tight packing), non-linearly.
    score -= 100.0 * (-post_residual as f64 / 20.0).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is barely consumed.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 60.0 * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Lookahead: reward leaving space the next item can use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // or early in the stream when opening bins is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let poor_alternatives = mean_residual < item_size as f64 * 1.1;
        if poor_alternatives || progress < 0.05 {
            score -= 80.0;
        } else {
            score += 100.0 + 50.0 * (1.0 - progress);
        }
    }

    // Prefer filling bins with above-average residuals (consolidate emptiness).
    if bin_residual < bin_capacity {
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        // Slight preference for closing out nearly-full bins.
        if post_residual <= 15 {
            score -= 30.0;
        }
    }

    // Late stream: be greedier, avoid opening new bins.
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear coupling: post_residual weighted by stream progress
    score += 20.0 * norm_pr * norm_pr * (0.5 + t);

    // Reward tight fits (small post_residual) more strongly later in stream
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * t;

    // Penalize bins whose residual deviates strongly from mean residual
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (cap * cap);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * t;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            score -= 10.0 * (1.0 - ns / pr.max(1.0));
        } else {
            score += 8.0 * (ns - pr) / cap;
        }
    }

    // Mild penalty for too many open bins relative to progress
    score += 0.5 * open_bins_count as f64 * t * t;

    // Smooth cubic interaction of fill ratio and progress
    let fill = 1.0 - norm_pr;
    score -= 12.0 * fill * fill * fill * (0.3 + 0.7 * t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into classes of 10
    let post_class = post_residual / 10;
    // Small post_residual classes are good (tight fit) -> reward (subtract)
    match post_class {
        0 => score -= 60.0,             // near-perfect fit
        1 => score -= 40.0,             // leftover <= 19
        2 => score -= 22.0,             // leftover <= 29
        3 => score -= 10.0,             // leftover <= 39
        4 => score -= 3.0,              // leftover <= 49
        _ => {}                          // half-empty or worse: no reward
    }

    // Exact fill is always ideal
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_class = next_item_size / 10;
        score -= 8.0 + (next_class as f64) * 2.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space that next item cannot use: penalize proportionally to how close next item is
        let gap = (next_item_size - post_residual) as f64;
        score += (gap / 10.0).min(8.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening new bins when decent open bins exist
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty scaled by how much residual mass exists elsewhere
        score += 30.0 + mean_residual * 0.5;
        // early in stream, opening bins is cheaper (more items to come to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    } else {
        // using existing bins slightly favored as stream progresses
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Prefer filling bins that deviate below mean residual (consolidate emptier bins)
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.3;
    } else {
        score += (resid - mean_residual) * 0.3;
    }

    // Item size harmonic class: big items should go into tight bins (small residual)
    let item_class = item_size / 10;
    if item_class >= 6 {
        // large item: reward placing into bins with small residual before placement
        score -= (100 - bin_residual.min(100)) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable, penalize hard.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (1.0 - (post_residual as f64) / 12.0);
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Reward tight fits relative to residual.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // Open-bin pressure: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when open bins are mostly full/tight.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score = 35.0 - pressure * 40.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: post residual exactly matches next item -> strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // next item fits here; reward proportionally to how snugly it will fit
            let next_post = post_residual - next_item_size;
            score -= 8.0 * (1.0 - next_post as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving awkward leftover space
            let gap = next_item_size - post_residual;
            score += 0.15 * gap as f64;
        }
    }

    // Penalize unusable dead space (post_residual below minimum item size 1 is impossible,
    // but very small post_residual is fine only if next item matches; otherwise it's waste)
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Favor bins tighter than average (good fits)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Slight preference for filling existing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * progress * post_residual as f64;

    // New-bin candidate: prefer it only when item is large relative to capacity
    // or when current bin would leave a big awkward residual
    if bin_residual == bin_capacity {
        let big_item_bonus = 0.4 * item_size as f64;
        score -= big_item_bonus - 10.0;
        if post_residual > 60 {
            score += 6.0; // opening fresh bin for small items wastes capacity
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= tightness * tightness * 40.0;

    // Penalize wasted residual that is too small to be useful later.
    if post_residual > 0 {
        let waste = (post_residual as f64 / bin_capacity as f64).powi(3);
        score += waste * 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // chain fit: two items perfectly fill the bin
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= (1.0 - slack / bin_capacity as f64) * 15.0;
        } else {
            score += 8.0; // next item won't fit here afterwards
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 + item_size as f64 * 0.2;
    }

    // Many fitting bins: mild penalty to prefer the tightest one, already covered,
    // but discourage spreading across too many open bins.
    if open_bins_count > 0 {
        let spread = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        score += spread * 6.0 * (mean_residual / bin_capacity as f64);
    }

    // Time horizon: late in the stream, prefer closing bins out (tight fits matter more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * tightness;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: opening a fresh bin is worthwhile only when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_options = if fitting_bins_count == 0 {
            0.0
        } else {
            let best_possible = (bin_residual - item_size) as f64;
            (best_possible / bin_capacity as f64).powi(2)
        };
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        let new_bin_score = 30.0 + poor_options * 90.0 - open_pressure * 5.0
            + if next_item_size > 0 && next_item_size >= item_size { 10.0 } else { 0.0 };
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, small residuals become more valuable (tighter packing).
    let progress_weight = 0.5 + 1.5 * t * t;
    score += progress_weight * (pr * pr) / cap;

    // Reward when the lookahead item fits exactly into the post-residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let tightness = 1.0 - ((pr - nx) / cap).powi(2);
            score -= 12.0 * tightness * (1.0 + t);
        } else {
            // Penalize residuals too small for the next item (dead space risk).
            score += 3.0 * (nx - pr) / cap * (1.0 + t);
        }
    }

    // Last-chance bonus: this is the only bin that fits, so strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty proportional to crowding of open bins, smoothed by mean residual.
    score += 0.3 * open_bins_count as f64 * (mean_residual / cap).powi(2);

    // New-bin candidate: discourage unless residual of open bins is very fragmented.
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: residual close to zero.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * (1.0 - 4.0 * tight).max(0.0) * (1.0 - 4.0 * tight).max(0.0);

    // Harmonic class: perfect / near-perfect fills get huge reward.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 10 {
        score -= 150.0;
    } else if post_residual % 10 == 0 {
        // residual is a "clean class" that future items may match
        score -= 20.0;
    }

    // Penalize dead space that no plausible item (1..100) can use well:
    // small residuals are fine (few items that small), mid residuals bad.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0; // awkward dead zone
    }

    // Lookahead: if next item fits the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0 + 0.5 * (post_residual - next_item_size) as f64;
    }
    // If next item just barely misses, slight penalty (bin becomes useless).
    if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 5 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalize opening
    // new bins unless remaining open bins have large mean residual but
    // none fit well (fragmentation).
    if bin_residual == bin_capacity {
        score = 70.0 + mean_residual * 0.3;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0;
        }
        // late in the stream, prefer closing out open bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 30.0;
        }
    }

    // Mild preference for fuller bins among ties.
    score += 0.1 * (bin_capacity - bin_residual) as f64 * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize unusable gaps relative to the upcoming item (dead space it cannot exploit).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Open-bin pressure: when many bins are open, prefer reusing existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (4.0 + 6.0 * progress);
    score += pressure;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight bias toward bins tighter than average (best-fit flavor).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // New-bin candidate: penalize opening a new bin mildly, more when open bins exist.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up — heavily reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = post_residual - next_item_size;
        if chain == 0 {
            score -= 600.0;
        } else {
            score -= 150.0 - (chain as f64).min(150.0);
        }
    }
    // If next item cannot use the residual, penalize large leftover space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (post_residual as f64) * 0.5;
    }

    // Compare residual against mean residual across open bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Mild penalty for opening a new bin when open bins exist that fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 + 40.0 * (1.0 - progress);
    }

    // Prefer denser bins (less residual before placement) slightly.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score -= 4.0; // usable pocket
    }

    // Lookahead: if next item fits the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.2 * next_item_size as f64;
    }
    // If next item would exactly fill post-residual, huge bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, mild penalty for wasting a scarce large residual.
        if post_residual as f64 > mean_residual {
            score += 2.0;
        }
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty for opening a bin; relax late in stream or when many bins fit poorly.
        let mut new_bin_penalty = 20.0;
        if next_item_size > 0 && next_item_size >= item_size {
            new_bin_penalty -= 8.0; // big item coming, fresh bin useful
        }
        if fitting_bins_count == 0 {
            new_bin_penalty = 0.0; // forced open anyway
        }
        if fitting_bins_count == 1 {
            new_bin_penalty += 30.0; // don't skip the last-chance bin
        }
        if open_bins_count == 0 {
            new_bin_penalty -= 25.0;
        }
        // Slight time decay: early on keep bins consolidated.
        new_bin_penalty *= 1.0 - 0.3 * progress;
        score += new_bin_penalty;
    }

    // Global consolidation pressure: prefer bins with below-average residual
    // (i.e., fuller bins) to concentrate waste.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild preference for filling bins more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_n = pr / cap;
    let fill_n = 1.0 - pr_n;

    // Base: prefer tight fits, with non-linear sharpening as stream progresses
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth non-linear coupling: squared residual term amplified by progress
    score += 12.0 * pr_n * pr_n * (0.5 + progress);

    // Dead-space penalty: residuals too small for typical future items
    score += 6.0 * (pr_n * (1.0 - pr_n)) * (1.0 - progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 8.0 * (next_item_size as f64 / cap) * (1.0 + progress);
        } else {
            score += 4.0 * pr_n;
        }
    }

    // Mild pressure toward consolidating bins when many are open
    score += 0.3 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Alignment with mean residual: prefer bins near the mean to keep flexibility
    score += 2.0 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / cap;
        score += 18.0 - 14.0 * big_item * (1.0 + progress) - 0.5 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into decile buckets.
    let class = post_residual / 10;
    // Reward small dead-space classes nonlinearly.
    score -= (10 - class.min(10)) as f64 * 0.35;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 5 {
        score -= 120.0;
    }

    // Lookahead coupling: penalize if post_residual cannot fit next item
    // but is close (wasted potential), reward if next item fits snugly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 60.0; // chains nicely
            } else {
                score += gap as f64 * 0.15;
            }
        } else {
            // next item won't fit here; small residual left behind is bad
            if post_residual < 20 {
                score += (20 - post_residual) as f64 * 1.5;
            }
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize new-bin candidate slightly unless residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 25.0;
        let frag = mean_residual / bin_capacity as f64;
        if frag > 0.45 && next_item_size > 0 && next_item_size <= mean_residual as u32 {
            score -= 40.0; // fragmentation high, but a bin can chain next item
        }
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Modulo harmonic: residuals divisible by common item sizes are useful.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Progress scaling: tighten criteria late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64 * (step_index as f64 / (total_items.max(1) as f64)).sqrt();

    // New-bin candidate: keep it neutral-ish, only attractive when existing bins are fragmented.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * mean_residual.min(50.0);
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly.
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            let gap = post - nxt;
            // Strong reward for perfect 2-chain (post_residual == next_item_size)
            if gap == 0.0 {
                score -= 60.0;
            } else {
                // Proportional reward for near-exact matching
                score -= 30.0 * (1.0 - gap / post).min(1.0);
            }
        } else {
            // Next item cannot use the leftover: penalize dead space scaled by overflow
            let overflow = nxt - post;
            score += 0.4 * overflow;
        }
    }

    // Penalize bins whose post_residual deviates far above the mean residual
    // (keeps residual distribution tight, preserving flexibility).
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score += 0.05 * dev; // slightly reward below-mean residuals
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mild reward for tight fits overall (small post_residual relative to item).
    if item_size > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 10.0 * tightness;
    }

    // Penalize opening a new bin when existing bins fit well, especially early/late.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty unless item is huge or stream near end.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 15.0;
        if item_size >= 70 { new_bin_penalty -= 10.0; }
        if next_item_size > 0 && next_item_size as f64 + item_size as f64 <= bin_capacity as f64 {
            // Pairing potential in a fresh bin
            new_bin_penalty -= 5.0;
        }
        if progress > 0.9 && open_bins_count > 0 { new_bin_penalty += 10.0; }
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the fuller the bin becomes, the better.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small unusable post-residuals that are still nonzero
    // (dead space), but reward exact or near-exact closures.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    } else {
        // Larger leftover is somewhat tolerable; mild superlinear penalty.
        let pr = post_residual as f64;
        score += 0.02 * pr * pr;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chaining future placements).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * chain_fit;
        } else {
            // Next item won't fit here; leftover is likely dead space.
            score += 0.1 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item in the stream: closing a bin is ideal.
        score -= 25.0 * fill_ratio;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, scaled by how late in the stream we are.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 18.0 + 12.0 * progress;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when existing bins fit poorly. Penalize opening new bins, more so
    // when many bins are already open and mean residual is large.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 45.0
            + 0.15 * open_bins_count as f64
            + 0.3 * mean_residual
            + 0.05 * waste;
        // Early in the stream, opening bins is cheaper (fewer alternatives).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    } else {
        // Prefer bins whose residual deviates favorably from the mean
        // (below-mean residual means this bin is already tight; use it).
        let dev = mean_residual - bin_residual as f64;
        score -= 0.2 * dev;
    }

    // Mild global pressure: with many open bins, consolidate into
    // existing bins rather than spreading items.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: quadratic waste penalty (dead space hurts super-linearly)
    let mut score = 2.0 * x * x + 1.0 * x;

    // Reward near-perfect fits strongly (small post residual)
    score -= 3.0 * (1.0 - x).powi(8);

    // Stream-progress coupling: later in the stream, waste is costlier
    score += progress * x * x * 2.5;

    // Non-linear interaction between post residual and mean residual:
    // if this bin's residual is far below the mean, it's a good squeeze
    let mean_x = mean_residual / cap;
    score += 0.8 * (x - mean_x).abs() - 1.2 * (x - mean_x).powi(3);

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 1.5 + 2.0 * (1.0 - progress);
    } else {
        score += 0.2 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: penalize if post residual can't fit next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if x >= nx {
            score -= 0.9 * (1.0 - (x - nx)) * (1.0 - progress);
        } else {
            score += 0.6 * (nx - x) * (1.0 + progress);
        }
    }

    // New-bin candidate handling: opening a fresh bin is a last resort,
    // unless current placement would leave large unusable residue
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases late in stream
        score = 2.2 - 1.0 * progress;
        // If item would leave a very small residue in existing bins, new bin is fine
        score += 1.5 * (1.0 - x).powi(6);
        // If many bins are open, prefer consolidating instead
        score += 0.15 * (open_bins_count as f64);
    } else {
        // Slight preference for using already-open bins vs new ones
        score -= 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common item
    // granularities are more reusable, so reward them (subtract).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space (unusable for typical items) is penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic divisibility classes on post_residual.
    if post_residual % 10 == 0 {
        score -= 25.0; // aligns with 10-multiple items
    }
    if post_residual % 20 == 0 {
        score -= 20.0; // aligns with 20-multiple items
    }
    if post_residual % 25 == 0 {
        score -= 15.0;
    }
    if post_residual % 50 == 0 {
        score -= 15.0;
    }

    // Fraction-of-capacity thresholds via integer division.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    match post_residual / quarter {
        0 => score += 10.0,          // very tight leftover
        1 => score -= 5.0,           // quarter-class residual
        2 => score -= 10.0,          // half-class residual: most reusable
        _ => score -= 3.0,
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // heavily reward this placement (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item fills the leftover
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 40.0 * fill;
            // harmonic match: next item and leftover share a divisor class
            if post_residual % next_item_size.max(1) == 0 {
                score -= 30.0;
            }
        } else {
            // next item cannot use the leftover: penalize large stranded space
            score += 0.15 * pr;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a bin should only win when no
    // open bin offers a decent fit. Penalize the empty-bin call.
    if bin_residual == bin_capacity {
        score += 80.0;
        // but if the item is huge relative to mean residual, opening a fresh
        // bin may be better; ease the penalty.
        if item_size as f64 > mean_residual + 20.0 {
            score -= 90.0;
        }
        // late in the stream, prefer consolidating into open bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 40.0;
        }
    }

    // Prefer tighter (fuller) bins among equals: classic best-fit coupling.
    score -= 0.3 * (cap - bin_residual as f64);

    // Mild pressure to keep the number of open bins from exploding.
    score += 0.5 * open_bins_count as f64;

    // Slight preference for bins below the mean residual (keeps big holes
    // available for big future items).
    if bin_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual gap is "dead" if it cannot fit even the smallest plausible item.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 + (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 3 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits into the post-residual gap, reward keeping it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + (next_item_size as f64 / post_residual as f64) * 6.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Gap too small for the known next item: extra penalty for wasted space.
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor denser packing.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling: if this bin's residual is well below average, it is
    // a tight fit candidate; reward using it rather than the mean-residual bins.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.4;
    } else {
        score += (res_f - mean_residual) * 0.2;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a good fit (i.e., the fit here would leave a large dead gap).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 18.0 + open_bins_count as f64 * 2.0;
        // But if placing the item here would leave a tiny gap, a fresh bin is great.
        if post_residual <= 5 {
            score -= 20.0;
        }
        // Late in the stream, opening bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Mild tightness bonus: reward high fill ratio of this placement.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // New bin is only attractive when no open bin can fit the item;
        // otherwise strongly prefer reusing an existing bin.
        if fitting_bins_count == 0 {
            return -100.0;
        }
        return 1000.0 + post_residual as f64;
    }

    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: does the leftover space exactly or comfortably fit the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Chain fit: leftover exactly consumed by next item.
            score -= 200.0;
        } else if post_residual >= next_item_size {
            // Leftover can at least host the next item.
            score -= 60.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // Dead space: cannot host next item; penalize proportionally.
            let dead = post_residual as f64;
            score += dead * 0.5 + 20.0;
        }
    } else {
        // Last item: pure best-fit, minimal leftover is best (post_residual==0 handled).
        score += post_residual as f64 * 0.1;
    }

    // Last chance bin: if this is the only open bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Compare residual against mean residual across open bins: placing into a bin
    // with below-mean residual (tighter bin) is good; above-mean is wasteful.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Late in the stream, consolidate: penalize leaving many nearly-empty bins.
    if open_bins_count > 1 {
        score += (open_bins_count as f64 - 1.0) * (5.0 + 10.0 * progress);
    }

    // Slight preference for tighter fits overall.
    score += (post_residual as f64 / bin_capacity as f64) * 25.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize large dead space left behind (post residual that is hard to reuse).
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // tiny unusable slivers are fine — item was well packed
    } else if post_residual >= 10 {
        // Dead space that could still hold typical items: mild penalty scaled by openness
        score += 0.05 * post_residual as f64 * (1.0 - fit_ratio);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: slight penalty for wasting residual
            score += 3.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Competition among fitting bins: keep base comparison on fit quality
        score += 0.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless current fit is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Cost of a new bin decays if mean residual across open bins is fragmented.
        let fragmentation = mean_residual / bin_capacity as f64;
        let mut new_bin_cost = 40.0;
        // If open bins have plenty of space but this item is small, discourage new bin.
        if item_size as f64 <= fragmentation * bin_capacity as f64 {
            new_bin_cost += 20.0;
        }
        // Late in stream, prefer filling existing bins.
        new_bin_cost += 15.0 * progress;
        // If many bins open and mean residual large, opening new bin wastes capacity.
        new_bin_cost += 0.3 * open_bins_count as f64 * fragmentation;
        // If item is huge relative to mean residual, new bin may be wise.
        if item_size as f64 > mean_residual {
            new_bin_cost -= 25.0;
        }
        score += new_bin_cost;
    }

    // Mild global pressure: when few bins fit the item stream-wide, tighten selection.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    // Base: prefer small post-residual (tight fits)
    let mut score = r;

    // Smooth non-linear coupling: post-residual penalty shaped by stream progress.
    // Late in the stream, small residuals matter more (dead space is costly).
    let progress_coupling = norm_r * norm_r * (1.0 - progress) * 40.0
        + norm_r * progress * 25.0;
    score += progress_coupling;

    // Reward near-perfect fits with a smooth saturating term
    let tightness = 1.0 - norm_r;
    score -= 30.0 * tightness * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement smoothly
    if next_item_size > 0 && (next_item_size as f64) <= r {
        let compat = 1.0 - ((r - next_item_size as f64) / cap).abs();
        score -= 20.0 * compat * compat;
    }

    // Penalize bins far from mean residual (encourage residual homogeneity)
    let dev = (r - mean_residual).abs();
    score += 0.15 * dev * (0.5 + progress);

    // Mild pressure against proliferating bins late in the stream
    score += (open_bins_count as f64).ln() * progress * 2.0;

    // New-bin candidate: penalize slightly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 45.0 - 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it cannot
    // accommodate any plausible future item (small classes).
    let cls = post_residual / 10;
    let class_penalty = match cls {
        0 => 60.0,               // 0..9 : almost dead
        1 => 30.0,               // 10..19
        2 => 15.0,               // 20..29
        3 => 7.0,                // 30..39
        4 => 3.0,                // 40..49
        _ => 0.0,
    };
    score += class_penalty;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 + (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to wasted potential.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: neutral baseline, slightly penalized so we prefer
    // reusing open bins unless fit is bad; adjust by stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 - 10.0 * progress;
        // Opening a new bin is attractive when open bins are already tight.
        if mean_residual < 20.0 {
            score -= 15.0;
        }
    }

    // Prefer filling bins below the mean residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Modulo-25 harmonic banding of residual: reward residuals near multiples
    // of 25 (versatile split points).
    let m = post_residual % 25;
    if m == 0 && post_residual > 0 {
        score -= 10.0;
    } else if m < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item are pure waste.
    let dead_threshold: u32 = 10;
    if post_residual < dead_threshold {
        // Perfect-ish fit: strong reward proportional to tightness.
        score -= (dead_threshold - post_residual) as f64 * 3.0;
    } else if post_residual <= 30 {
        // Small but usable gap: mild penalty to prefer tighter fits.
        score += (30.0 - post_residual as f64) * 0.4;
    }

    // Reward using bins that are already quite full (low residual).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but strongly penalize opening a brand-new bin when others fit.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus scaling with open bins.
        score += 25.0 + open_bins_count as f64 * 2.0;
        // If nothing else fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
    } else {
        // Using an existing bin that fits: reward, stronger if it's the last chance.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Lookahead synergy: prefer bins whose leftover accommodates next item.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 6.0;
        }
    }

    // Mild pressure against keeping many open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 0.5;

    // Prefer bins below mean residual (relatively emptier) to be filled first.
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual closely matches next item.
    if next_item_size > 0 {
        let fit2 = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 6.0 * fit2.max(0.0).recip().min(2.0);
        // Perfect 2-step chain: post_residual exactly fits next item
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Item + next item both fit snugly (post_residual < next but small waste)
        else if post_residual < next_item_size && post_residual <= 15 {
            score -= 12.0;
        }
        // Penalize leaving residuals that are too large AND unmatched by lookahead
        if post_residual > next_item_size + 25 && post_residual > 40 {
            score += 8.0;
        }
    } else {
        // Last item: prefer tightest fit, zero residual is ideal
        score += 0.5 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins already tighter than average
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        score += 20.0;
        // Opening new bin is fine early in stream or when next item is large
        if next_item_size >= 60 {
            score -= 15.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Discourage wasting large bins on tiny items
    if item_size <= 20 && bin_residual >= 80 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where item leaves minimal waste.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize residual waste non-linearly (dead space that can't hold mid-size items).
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // tiny slivers are fine, item nearly fills bin
    } else if post_residual >= 10 && post_residual <= 40 {
        score += 6.0 * (post_residual as f64 / 40.0); // awkward mid-range gap
    }

    // Lookahead: reward bins whose residual can also host the next item (pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_waste = post_residual - next_item_size;
        score -= 14.0 * (1.0 - pair_waste as f64 / bin_capacity as f64);
    }
    // Penalize if next item would leave this bin stranded with unusable residual.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0 * (post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly or are scarce.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fits = (mean_residual - item_size as f64).abs();
        score += 55.0 - 40.0 * scarcity - 12.0 * (poor_fits / bin_capacity as f64);
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Many open bins with slack: discourage new bins.
        score += 3.0 * (open_bins_count as f64).sqrt() * (mean_residual / bin_capacity as f64);
    }

    // Mild preference for filling bins that are already mostly consumed.
    let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 5.0 * used * used;

    // Global pressure: when mean residual is low, be extra frugal with space.
    score += 2.0 * (1.0 - mean_residual / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * (1.0 - progress) * 0.5;
    score += poly * cap * 0.3;

    // Penalize large residuals early, less late (bins will close anyway)
    score += (norm_pr * pr) * (0.2 * (1.0 - progress));

    // Reward tight fits
    score -= (item_size as f64 / cap) * 6.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward residual matching next item
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += diff * 0.15;
    }

    // Crowding effect: more open bins -> prefer filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mean residual coupling
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: quantize dead space into buckets of 10.
    let class = post_residual / 10;
    // Dead-space penalty grows super-linearly for awkward leftover classes.
    score += (class as f64).powi(2) * 0.7;

    // Perfect fit reward: post_residual exactly in {0, 10, 20} is highly valuable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual == 10 {
        score -= 40.0;
    } else if post_residual == 20 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (chain of harmonic fills).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            // Penalize leftovers that fall into "dead" classes (1..9 mod 10)
            if leftover % 10 != 0 {
                score += (leftover as f64) * 1.5;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item cannot follow here: penalize proportionally to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Encourage filling nearly-full bins when many bins are open (bin consolidation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * fill_ratio * 25.0;

    // Mild pressure to keep open-bin count low as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.3 * progress;

    // Prefer bins below mean residual slightly (balance residual distribution).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: make empty bin moderately attractive so it wins only
    // when open bins would create truly bad classes (post_residual in 1..10).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55;
        if post_residual % 10 != 0 {
            // small dead space elsewhere -> new bin becomes competitive
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size >= 70 {
            // big upcoming item: fresh bin is useful
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual as f64) * 8.0; // tiny gaps are worthless
    } else if post_residual > 10 && post_residual <= 25 {
        score += (25 - post_residual as f64) * 1.5; // medium-small gaps mildly bad
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: reward strongly
    }

    // Reward tight fits relative to bin size (low waste fraction).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * 20.0;

    // Open-bin pressure: discourage proliferating bins.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0; // creates a gap the next item cannot use
    }

    // New-bin candidate: make it moderately attractive when mean residual is low
    // (open bins are mostly full) but penalize it when open bins have room.
    if bin_residual == bin_capacity {
        score -= 10.0;
        score += mean_residual * 0.3;
        score += open_bins_count as f64 * 1.2;
    }

    // Stream progression: later in stream, be slightly greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - waste_frac) * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: post_residual exactly matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 40.0; // exact lookahead match: strongest reward
        } else if (post_residual as u32) >= next_item_size {
            // next item still fits after this placement: reward closeness
            score -= 15.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // dead space too small for next item: penalize proportionally
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }

        // Pair packing: item + next item nearly fill the bin
        if item_size + next_item_size >= bin_capacity - 2 {
            score -= 25.0;
        }
    }

    // Reward tight fits relative to capacity
    score -= 20.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize bins far above/below mean residual (prefer balanced or very tight bins)
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // Prefer opening new bins early in the stream when current fits are loose
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual as f64 > 0.5 * bin_capacity as f64 {
        score += 12.0 * (1.0 - progress); // loose fits worse early on
    }

    // Slight preference to keep many bins from proliferating mid-stream
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}
